   ========================================================= */

@media (max-width: 480px) {

    .jfinHero {
        height: 225px !important;
    }


    .jfinHeroContent {
        padding: 15px 12px 10px !important;
    }


    .jfinHeroText {
        width: 53% !important;
    }


    .jfinHeroTitle {
        font-size: 17px !important;
    }


    .jfinHeroDescription {
        font-size: 7.2px;

        max-width: 195px;
    }


    .jfinHeroBtn {
        width: 90px;

        min-width: 90px;

        height: 39px;

        font-size: 10.5px;
    }


    .jfinHeroArrow {
        width: 37px;

        height: 37px;
    }
}

/* =========================================
   MOBILE - FINANCIAL JOURNEY FIX
========================================= */

@media (max-width: 768px) {

    .financial-journey-section {
        width: 100%;
        padding: 25px 14px 40px !important;
        margin-top: 0 !important;
        box-sizing: border-box;
    }

    /* Remove any unwanted spacing before section */
    .financial-journey-section::before {
        display: none;
    }

    .financial-journey-section .section-header {
        margin-top: 0 !important;
        padding-top: 0 !important;
    }

    /* About Company */
    .financial-journey-section .finserv-eyebrow {
        font-size: 16px;
        line-height: 1.4;
        margin: 0 0 8px !important;
    }

    /* Main heading */
    .financial-journey-section .finserv-trusted {
        font-size: 31px;
        line-height: 1.15;
        margin: 0 0 14px !important;
    }

    /* Description */
    .financial-journey-section .section-header p {
        font-size: 15px;
        line-height: 1.6;
        margin: 0 auto !important;
        max-width: 100%;
    }

    /* =========================================
       MOBILE IMAGE AREA
    ========================================= */

    .financial-journey-images {
        width: 100%;
        max-width: 100%;
        gap: 8px;
        margin: 35px auto 40px !important;
        padding: 0;
        box-sizing: border-box;
    }

    .journey-image {
        width: calc((100% - 16px) / 3);
        height: 145px;
        padding: 2px;
    }

    .journey-image-center {
        width: calc((100% - 16px) / 3);
        height: 145px;
    }

    .journey-image-left {
        transform: translateY(12px);
    }

    .journey-image-center {
        transform: translateY(-12px);
    }

}


/* =========================================================
   360px
   ========================================================= */

@media (max-width: 360px) {

    .jfinHero {
        height: 220px !important;
    }


    .jfinHeroContent {
        padding: 14px 10px 8px !important;
    }


    .jfinHeroText {
        width: 54% !important;
    }


    .jfinHeroTitle {
        font-size: 16px !important;
    }


    .jfinHeroDescription {
        font-size: 7px;

        -webkit-line-clamp: 3;
    }


    .jfinHeroBtn {
        width: 83px;

        min-width: 83px;

        height: 37px;

        font-size: 10px;
    }


    .jfinHeroNavigation {
        right: 8px;

        bottom: 8px;
    }


    .jfinHeroArrow {
        width: 34px;

        height: 34px;
    }
}
/* =====================================================
   FIX HEADER OVERLAPPING HERO
   ===================================================== */

@media (max-width: 767px) {

    .jfinHero {
        margin-top: 0 !important;
        height: 225px !important;
        min-height: 225px !important;
        padding: 0 !important;
    }

    .jfinHeroContent {
        padding-top: 12px !important;
    }

    .jfinHeroText {
        margin-top: 0 !important;
    }

    .jfinHeroLabel {
        margin-top: 0 !important;
    }

    .jfinHeroTitle {
        margin-top: 0 !important;
        transform: none !important;
        top: auto !important;
    }
}
/* =========================================
   SMALL MOBILE
   ========================================= */

@media (max-width: 480px) {

    .hero {
        height: 560px !important;
        min-height: 560px !important;
    }

    .hero .slide {
        height: 560px !important;
        min-height: 560px !important;

      
        background-position: right bottom !important;
    }

    .hero .hero-content {
        width: 65% !important;
        max-width: 65% !important;

        padding-top: 65px !important;
    }

    .hero .hero-content h1 {
        font-size: 23px !important;
    }

    .hero .hero-content p {
        font-size: 12px !important;
    }
}



