/* =========================================================
   EXTRA SMALL MOBILE
========================================================= */

@media (max-width: 360px) {

    .jfm-products-section {
        padding: 30px 0 40px;
    }


    .jfm-products-container {
        padding: 0 10px;
    }


    .jfm-products-title {
