    }


    .jfm-product-readmore {
        font-size: 12px;
    }

}


    /* =========================================================
   JFINMATE LENDING PARTNERS
   UNIQUE CLASS NAMES
========================================================= */

.jfm-lenders-section {
    width: 100%;
    background: #dce9fe;
    padding: 0;
    overflow: hidden;
}


/* =========================================================
   HEADING
========================================================= */

.jfm-lenders-heading {
    width: 100%;
    text-align: center;

    padding: 25px 15px 20px;

    background: #ffffff;

    border-bottom: 1px solid #eeeeee;
}


.jfm-lenders-heading h2 {
    margin: 0;

    color: #444444;

    font-size: 18px;
    font-weight: 700;

    line-height: 1.3;
}


/* =========================================================
   SLIDER WRAPPER — MORE LEFT & RIGHT SPACE (INCREASED AGAIN)
========================================================= */

.jfm-lenders-slider-wrapper {
    width: 100%;

    /* ← MORE LEFT & RIGHT SPACE (increased further) */
    padding: 0 200px;

    box-sizing: border-box;
}


/* =========================================================
   SLIDER (full width inside the padded wrapper)
========================================================= */

.jfm-lenders-slider {
    width: 100%;

    overflow: hidden;

    background: #dce9fe;

    border-bottom: 1px solid #eeeeee;

    position: relative;

    padding: 0;
}


/* =========================================================
   SLIDER TRACK
========================================================= */

.jfm-lenders-track {
    width: max-content;

    display: flex;

    align-items: center;

    animation: jfmLenderSlide 25s linear infinite;
}


/* =========================================================
   LOGO ITEM
========================================================= */

.jfm-lender-logo {
    width: 180px;
    height: 75px;

    flex-shrink: 0;

    display: flex;

    align-items: center;
    justify-content: center;

    padding: 12px 20px;
}


/* =========================================================
   LOGO IMAGE
========================================================= */

.jfm-lender-logo img {
    max-width: 135px;
    max-height: 45px;

    width: auto;
    height: auto;

    display: block;

    object-fit: contain;

    transition: transform 0.3s ease;
}


/* =========================================================
   LOGO HOVER
========================================================= */

.jfm-lender-logo:hover img {
    transform: scale(1.05);
}


/* =========================================================
   SLIDER ANIMATION
========================================================= */

@keyframes jfmLenderSlide {

    0% {
        transform: translateX(0);
    }

    100% {
        transform: translateX(-50%);
    }

}


/* =========================================================
   PAUSE ON HOVER
========================================================= */

.jfm-lenders-slider:hover .jfm-lenders-track {
    animation-play-state: paused;
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 991px) {

    .jfm-lenders-heading {
        padding: 22px 15px 17px;
    }


    .jfm-lenders-heading h2 {
        font-size: 17px;
    }


    /* ← MORE LEFT & RIGHT SPACE (tablet) */
    .jfm-lenders-slider-wrapper {
        padding: 0 120px;
    }


    .jfm-lender-logo {
        width: 165px;
        height: 70px;

        padding: 10px 18px;
    }


    .jfm-lender-logo img {
        max-width: 125px;
        max-height: 42px;
    }

}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 767px) {

    .jfm-lenders-heading {
        padding: 20px 12px 16px;
    }


    .jfm-lenders-heading h2 {
        font-size: 16px;
    }


    /* ← MORE LEFT & RIGHT SPACE (mobile) */
    .jfm-lenders-slider-wrapper {
        padding: 0 60px;
    }


    .jfm-lender-logo {
        width: 145px;
        height: 65px;

        padding: 9px 15px;
    }


    .jfm-lender-logo img {
        max-width: 115px;
        max-height: 38px;
    }


    .jfm-lenders-track {
        animation-duration: 20s;
    }

}


/* =========================================================
   SMALL MOBILE
========================================================= */

@media (max-width: 480px) {

    .jfm-lenders-heading {
        padding: 18px 10px 14px;
    }


    .jfm-lenders-heading h2 {
        font-size: 15px;
    }


    /* ← MORE LEFT & RIGHT SPACE (small mobile) */
    .jfm-lenders-slider-wrapper {
        padding: 0 40px;
    }


    .jfm-lender-logo {
        width: 130px;
        height: 60px;

        padding: 8px 12px;
    }


    .jfm-lender-logo img {
        max-width: 105px;
        max-height: 35px;
    }


    .jfm-lenders-track {
        animation-duration: 18s;
    }

}



/* ==========================================
   ALL PROPERTIES SECTION — PRO UI
========================================== */

.all-properties-section {
    padding: 80px 0 90px;
    background: #ffffff;
    position: relative;
}


/* ==========================================
   CONTAINER — INCREASED LEFT & RIGHT SPACE
========================================== */

.all-properties-section .container {
    max-width: 1280px;
    margin: 0 auto;
    padding: 0 60px;   /* ← increased side space (was ~24px) */
}


/* ==========================================
   SECTION HEADER
========================================== */

.properties-section-header {
    max-width: 760px;
    margin: 0 auto 55px;
    text-align: center;
}


.properties-eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 14px;
    padding: 6px 16px;
    background: #eef4ff;
    border: 1px solid #d9e5fb;
    border-radius: 40px;
    color: #295cab;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 1.6px;
}


.properties-section-header h2 {
    margin: 0 0 16px;
    color: #1e2a41;
    font-size: 40px;
    font-weight: 700;
    line-height: 1.18;
    letter-spacing: -0.02em;
}


.properties-section-header h2 strong {
    color: #00abeb;
    font-weight: 700;
}


.properties-section-header p {
    max-width: 640px;
    margin: 0 auto;
    color: #6c7480;
    font-size: 15px;
    line-height: 1.75;
}


/* ==========================================
   PROPERTY GRID
========================================== */

.properties-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 30px;
}


/* ==========================================
   PROPERTY CARD
========================================== */

.property-card {
    position: relative;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    background: #ffffff;
    border: 1px solid #e9edf3;
    border-radius: 18px;
    box-shadow: 0 4px 20px rgba(24, 55, 90, 0.05);
    transition:
        transform 0.4s cubic-bezier(0.2, 0.7, 0.3, 1),
        box-shadow 0.4s ease,
        border-color 0.4s ease;
}


.property-card:hover {
    transform: translateY(-8px);
    border-color: #d9e5fb;
    box-shadow:
        0 24px 45px -12px rgba(24, 55, 90, 0.18),
        0 0 0 1px rgba(0, 171, 235, 0.05);
}


/* ==========================================
   PROPERTY IMAGE
========================================== */

.property-image-wrapper {
    position: relative;
    width: 100%;
    height: 245px;
    overflow: hidden;
    background: #f1f3f6;
}


.property-image-wrapper img {
    width: 100%;
    height: 100%;
    display: block;
    object-fit: cover;
    object-position: center;
    transition: transform 0.7s cubic-bezier(0.2, 0.7, 0.3, 1);
}


.property-card:hover .property-image-wrapper img {
    transform: scale(1.07);
}


/* ==========================================
   STATUS BADGE
========================================== */

.property-status-badge {
    position: absolute;
    top: 16px;
    left: 16px;
    z-index: 5;
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 7px 13px;
    background: rgba(255, 255, 255, 0.96);
    border: 1px solid rgba(255, 255, 255, 0.9);
    border-radius: 40px;
    box-shadow: 0 6px 18px rgba(15, 40, 80, 0.12);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    white-space: nowrap;
}


.status-dot {
    width: 7px;
    height: 7px;
    flex-shrink: 0;
    background: #18b76a;
    border-radius: 50%;
    box-shadow: 0 0 0 3px rgba(24, 183, 106, 0.15);
    animation: pulse-dot 2s infinite;
}


@keyframes pulse-dot {
    0%   { box-shadow: 0 0 0 0 rgba(24, 183, 106, 0.35); }
    70%  { box-shadow: 0 0 0 6px rgba(24, 183, 106, 0); }
    100% { box-shadow: 0 0 0 0 rgba(24, 183, 106, 0); }
}


.status-text {
    color: #1e3a8a;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.3px;
    line-height: 1.2;
}


/* ==========================================
   IMAGE OVERLAY
========================================== */

.property-overlay {
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    padding: 50px 16px 16px;
    background: linear-gradient(
        to top,
        rgba(10, 25, 50, 0.85) 0%,
        rgba(10, 25, 50, 0.45) 45%,
        transparent 100%
    );
    opacity: 0;
    transition: opacity 0.4s ease;
}


.property-card:hover .property-overlay {
    opacity: 1;
}


.quick-stats {
    display: flex;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
}


.stat-item {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 6px 12px;
    background: rgba(255, 255, 255, 0.14);
    border: 1px solid rgba(255, 255, 255, 0.18);
    border-radius: 40px;
    color: #ffffff;
    font-size: 11.5px;
    font-weight: 500;
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
}


.stat-item i {
    color: #00c3ff;
    font-size: 11px;
}


/* ==========================================
   PROPERTY DETAILS
========================================== */

.property-details {
    display: flex;
    flex-direction: column;
    flex: 1;
    padding: 22px 22px 22px;
}


/* ==========================================
   TITLE / BUNGALOW NAME
========================================== */

.property-title {
    min-height: 50px;
    margin: 0 0 12px;
    color: #1e2a41;
    font-size: 20px;
    font-weight: 700;
    line-height: 1.28;
    letter-spacing: -0.01em;
    transition: color 0.3s ease;

    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}


.property-card:hover .property-title {
    color: #295cab;
}


/* ==========================================
   DEVELOPER
========================================== */

.property-developer {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 16px;
    color: #5e6a7a;
    font-size: 13px;
}


.property-developer i {
    width: 16px;
    color: #295cab;
    font-size: 13px;
    text-align: center;
}


/* ==========================================
   SPECS ROW — Configuration · Location · Area
========================================== */

.property-specs {
    display: flex;
    align-items: stretch;
    width: 100%;
    margin-top: auto;
    padding: 15px 0;
    border-top: 1px solid #edf0f4;
    border-bottom: 1px solid #edf0f4;
}


.spec-item {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 5px;
    min-width: 0;
}


.spec-label {
    color: #89919c;
    font-size: 10px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.6px;
}


.spec-value {
    color: #253858;
    font-size: 13px;
    font-weight: 700;
    line-height: 1.35;
    word-break: break-word;
}


.spec-value.spec-location {
    font-weight: 600;
    color: #35485c;

    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}


.spec-divider {
    width: 1px;
    height: auto;
    min-height: 34px;
    margin: 0 16px;
    background: #e5e8ed;
    flex-shrink: 0;
}


/* ==========================================
   FOOTER
========================================== */

.property-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding-top: 18px;
}


/* ==========================================
   PRICE
========================================== */

.property-price {
    display: flex;
    flex-direction: column;
    gap: 4px;
    min-width: 0;
}


.price-label {
    color: #9299a2;
    font-size: 10px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.6px;
}


.property-price strong {
    color: #295cab;
    font-size: 16px;
    font-weight: 700;
    line-height: 1.3;
    white-space: nowrap;
}


/* ==========================================
   VIEW DETAILS BUTTON
========================================== */

.contact-btn {
    flex-shrink: 0;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 11px 18px;
    background: #295cab;
    color: #ffffff !important;
    border-radius: 10px;
    font-size: 12px;
    font-weight: 600;
    text-decoration: none !important;
    box-shadow: 0 6px 16px -4px rgba(41, 92, 171, 0.35);
    transition:
        background 0.3s ease,
        transform 0.3s ease,
        box-shadow 0.3s ease;
}


.contact-btn:hover {
    background: #00abeb;
    color: #ffffff !important;
    transform: translateY(-2px);
    box-shadow: 0 10px 22px -6px rgba(0, 171, 235, 0.5);
}


.contact-btn i {
    font-size: 10px;
    transition: transform 0.3s ease;
}


.contact-btn:hover i {
    transform: translateX(3px);
}


/* ==========================================
   VIEW ALL
========================================== */

.properties-view-all {
    margin-top: 55px;
    text-align: center;
}


.view-all-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    padding: 15px 34px;
    background: #1e4fd8;
    color: #ffffff !important;
    border-radius: 50px;
    font-size: 14px;
    font-weight: 600;
    text-decoration: none !important;
    box-shadow: 0 10px 24px -8px rgba(30, 79, 216, 0.45);
    transition:
        background 0.3s ease,
        transform 0.3s ease,
        box-shadow 0.3s ease;
}


.view-all-btn:hover {
    background: #00abeb;
    color: #ffffff !important;
    transform: translateY(-3px);
    box-shadow: 0 16px 30px -8px rgba(0, 171, 235, 0.55);
}


.view-all-btn i {
    font-size: 12px;
    transition: transform 0.3s ease;
}


.view-all-btn:hover i {
    transform: translateX(4px);
}


/* ==========================================
   NO PROPERTY
========================================== */

.no-properties {
    padding: 70px 24px;
    text-align: center;
    border: 1px solid #edf0f4;
    border-radius: 20px;
    background: #fafcff;
}


.no-properties-icon {
    margin-bottom: 18px;
    color: #295cab;
    font-size: 46px;
    opacity: 0.8;
}


.no-properties h3 {
    margin: 0 0 10px;
    color: #253858;
    font-size: 24px;
    font-weight: 700;
}


.no-properties p {
    max-width: 420px;
    margin: 0 auto;
    color: #777f89;
    font-size: 14px;
    line-height: 1.6;
}


/* ==========================================
   EXTRA PROPERTY
========================================== */

.extra-property {
    display: none;
}


/* ==========================================
   TABLET
========================================== */

@media (max-width: 991px) {

    .all-properties-section {
        padding: 60px 0 70px;
    }


    .all-properties-section .container {
        padding: 0 40px;   /* ← increased side space (tablet) */
    }


    .properties-section-header {
        margin-bottom: 45px;
    }


    .properties-section-header h2 {
        font-size: 34px;
    }


    .properties-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 24px;
    }


    .property-image-wrapper {
        height: 225px;
    }


    .spec-divider {
        margin: 0 12px;
    }

}


/* ==========================================
   MOBILE
========================================== */

@media (max-width: 767px) {

    .all-properties-section {
        padding: 50px 0 60px;
    }


    .all-properties-section .container {
        padding: 0 28px;   /* ← increased side space (mobile) */
    }


    .properties-section-header {
        margin-bottom: 35px;
    }


    .properties-eyebrow {
        font-size: 10px;
        letter-spacing: 1.2px;
        padding: 5px 13px;
    }


    .properties-section-header h2 {
        font-size: 28px;
        line-height: 1.25;
    }


    .properties-section-header p {
        padding: 0 8px;
        font-size: 13px;
        line-height: 1.65;
    }


    .properties-grid {
        grid-template-columns: 1fr;
        gap: 24px;
    }


    .property-image-wrapper {
        height: 235px;
    }


    .property-details {
        padding: 20px 18px 20px;
    }


    .property-title {
        min-height: auto;
        font-size: 19px;
    }


    .property-status-badge {
        top: 13px;
        left: 13px;
        padding: 6px 11px;
        gap: 6px;
    }


    .status-dot {
        width: 6px;
        height: 6px;
    }


    .status-text {
        font-size: 10.5px;
    }


    .property-overlay {
        opacity: 1;
        padding: 45px 14px 14px;
    }


    .stat-item {
        padding: 5px 10px;
        font-size: 11px;
    }


    .property-footer {
        align-items: flex-end;
    }


    .property-price strong {
        font-size: 15px;
    }


    .contact-btn {
        padding: 10px 16px;
        font-size: 11.5px;
    }


    .properties-view-all {
        margin-top: 40px;
    }


    .view-all-btn {
        padding: 13px 28px;
        font-size: 13px;
    }


    .spec-divider {
        margin: 0 10px;
    }


    .spec-label {
        font-size: 9px;
    }


    .spec-value {
        font-size: 12px;
    }

}


/* ==========================================
   SMALL MOBILE
========================================== */

@media (max-width: 480px) {

    .all-properties-section .container {
        padding: 0 20px;   /* ← increased side space (small mobile) */
    }


    .properties-section-header h2 {
        font-size: 24px;
    }


    .properties-section-header p {
        font-size: 12px;
    }


    .property-image-wrapper {
        height: 215px;
    }


    .property-details {
        padding: 18px 16px;
    }


    .property-footer {
        gap: 8px;
    }


    .property-price {
        max-width: 58%;
    }


    .property-price strong {
        font-size: 13.5px;
        white-space: normal;
    }


    .contact-btn span {
        display: none;
    }


    .contact-btn {
        width: 42px;
        height: 40px;
        padding: 0;
        border-radius: 10px;
    }


    .contact-btn i {
        font-size: 13px;
    }


    .spec-item {
        gap: 3px;
    }


    .spec-divider {
        margin: 0 8px;
        min-height: 28px;
    }


    .spec-label {
        font-size: 8.5px;
        letter-spacing: 0.4px;
    }


    .spec-value {
        font-size: 11px;
    }

}





