.financial-journey-section .finserv-trusted {
    font-size: 32px;
    line-height: 1.3;

    font-weight: 700;

    margin-top: 0;
    margin-bottom: 14px;
}


.financial-journey-section .section-header p {
    width: 100%;
    max-width: 850px;

    margin-left: auto;
    margin-right: auto;

    font-size: 15px;
    line-height: 1.7;

    color: #666666;
}


/* =========================================
   IMAGE AREA
========================================= */

.financial-journey-images {

    width: 100%;
    max-width: 900px;

    margin: 60px auto 65px;

    display: flex;

    align-items: center;
    justify-content: center;

    gap: 15px;

    position: relative;

    box-sizing: border-box;
}


/* =========================================
   IMAGE BOX
========================================= */

.journey-image {

    width: 285px;
    height: 215px;

    padding: 3px;

    background: #ffffff;

    box-sizing: border-box;

    overflow: hidden;

    flex-shrink: 0;
}


.journey-image img {

    width: 100%;
    height: 100%;

    display: block;

    object-fit: cover;

    object-position: center;
}


/* =========================================
   LEFT IMAGE
========================================= */

.journey-image-left {
    transform: translateY(20px);
}


/* =========================================
   CENTER IMAGE
========================================= */

.journey-image-center {

    width: 285px;
    height: 215px;

    transform: translateY(-20px);

    z-index: 2;
}


/* =========================================
   RIGHT IMAGE
========================================= */

.journey-image-right {
    transform: translateY(20px);
}


/* =========================================
   STATISTICS
========================================= */

.journey-statistics {

    width: 100%;
    max-width: 1140px;

    margin-left: auto;
    margin-right: auto;

    display: grid;

    grid-template-columns: repeat(4, 1fr);

    gap: 18px;

    box-sizing: border-box;
}


/* =========================================
   STATISTICS CARD
========================================= */

.journey-stat {

    width: 100%;

    min-height: 110px;

    padding: 22px 25px;

    background: #ffffff;

    border-radius: 13px;

    box-shadow: 0 6px 22px rgba(0, 0, 0, 0.09);

    display: flex;

    flex-direction: column;

    justify-content: center;

    box-sizing: border-box;
}


.journey-stat h3 {

    margin: 0 0 5px;

    font-size: 24px;

    line-height: 1.2;

    font-weight: 700;

    color: #295cab;
}


.journey-stat h3 span {
    color: #00abeb;
}


.journey-stat p {

    margin: 0;

    font-size: 14px;

    line-height: 1.5;

    color: #666666;
}


/* =========================================
   LARGE DESKTOP
========================================= */

@media (min-width: 1200px) {

    .financial-journey-section > .container {

        max-width: 1280px;

        padding-left: 40px;
        padding-right: 40px;
    }


    .financial-journey-images {

        max-width: 920px;

        gap: 18px;

        margin-top: 65px;

        margin-bottom: 70px;
    }


    .journey-image,
    .journey-image-center {

        width: 290px;
        height: 220px;
    }


    .journey-statistics {

        max-width: 1200px;

        gap: 20px;
    }

}


/* =========================================
   TABLET
========================================= */

@media (max-width: 992px) {

    .financial-journey-section {

        padding: 50px 0 60px;
    }


    .financial-journey-section > .container {

        max-width: 100%;

        padding-left: 25px;
        padding-right: 25px;
    }


    .financial-journey-section .finserv-trusted {

        font-size: 29px;
    }


    .financial-journey-section .section-header p {

        font-size: 14px;
    }


    /* Images */

    .financial-journey-images {

        width: 100%;

        max-width: 850px;

        gap: 10px;

        margin-top: 50px;

        margin-bottom: 55px;
    }


    .journey-image,
    .journey-image-center {

        width: calc((100% - 20px) / 3);

        height: 180px;
    }


    /* Statistics */

    .journey-statistics {

        width: 100%;

        max-width: 850px;

        grid-template-columns: repeat(2, 1fr);

        gap: 14px;
    }


    .journey-stat {

        min-height: 100px;

        padding: 20px;
    }

}


/* =========================================
   MOBILE
========================================= */

@media (max-width: 768px) {

    .financial-journey-section {

        padding: 45px 0 55px;
    }


    .financial-journey-section > .container {

        width: 100%;

        padding-left: 18px;
        padding-right: 18px;
    }


    .financial-journey-section .finserv-eyebrow {

        font-size: 15px;
    }


    .financial-journey-section .finserv-trusted {

        font-size: 26px;

        line-height: 1.35;
    }


    .financial-journey-section .section-header p {

        font-size: 13px;

        line-height: 1.6;
    }


    /* =================================
       MOBILE IMAGE AREA
    ================================= */

    .financial-journey-images {

        width: 100%;

        max-width: 100%;

        margin-top: 45px;

        margin-bottom: 50px;

        gap: 6px;
    }


    .journey-image,
    .journey-image-center {

        width: calc((100% - 12px) / 3);

        height: 150px;
    }


    .journey-image-left {

        transform: translateY(12px);
    }


    .journey-image-center {

        transform: translateY(-12px);
    }


    .journey-image-right {

        transform: translateY(12px);
    }


    /* =================================
       MOBILE STATISTICS
    ================================= */

    .journey-statistics {

        width: 100%;

        max-width: 100%;

        grid-template-columns: repeat(2, 1fr);

        gap: 12px;
    }


    .journey-stat {

        min-height: 95px;

        padding: 18px 20px;

        border-radius: 11px;
    }


    .journey-stat h3 {

        font-size: 21px;
    }


    .journey-stat p {

        font-size: 13px;
    }

}


/* =========================================
   SMALL MOBILE
========================================= */

@media (max-width: 480px) {

    .financial-journey-section {

        padding: 40px 0 50px;
    }


    .financial-journey-section > .container {

        padding-left: 12px;
        padding-right: 12px;
    }


    .financial-journey-section .finserv-eyebrow {

        font-size: 14px;
    }


    .financial-journey-section .finserv-trusted {

        font-size: 23px;

        line-height: 1.35;
    }


    .financial-journey-section .section-header p {

        font-size: 12.5px;

        line-height: 1.6;
    }


    /* Images */

    .financial-journey-images {

        margin-top: 40px;

        margin-bottom: 45px;

        gap: 5px;
    }


    .journey-image,
    .journey-image-center {

        width: calc((100% - 10px) / 3);

        height: 120px;

        padding: 2px;
    }


    .journey-image-left {

        transform: translateY(9px);
    }


    .journey-image-center {

        transform: translateY(-9px);
    }


    .journey-image-right {

        transform: translateY(9px);
    }


    /* Statistics */

    .journey-statistics {

        grid-template-columns: repeat(2, 1fr);

        gap: 9px;
    }


    .journey-stat {

        min-height: 85px;

        padding: 15px 13px;

        border-radius: 9px;
    }


    .journey-stat h3 {

        font-size: 19px;

        margin-bottom: 3px;
    }


    .journey-stat p {

        font-size: 11.5px;

        line-height: 1.4;
    }

}

    .journey-stat h3 {

        font-size: 19px;

        margin-bottom: 3px;
    }


    .journey-stat p {

        font-size: 11.5px;

        line-height: 1.4;
    }

}
