/* =========================================
   PROPERTY FINANCING SECTION
   ========================================= */

.property-financing-section {
    width: 100%;
    background: #ffffff;

    padding: 55px 20px 65px;

    overflow: hidden;
}


.property-financing-container {
    width: 100%;
    max-width: 1050px;

    margin: 0 auto;
}


/* =========================================
   HEADING
   ========================================= */

.property-financing-heading {
    width: 100%;

    text-align: center;

    margin-bottom: 45px;
}


.property-financing-heading h2 {
    margin: 0;
    padding: 0;

    font-family: Arial, sans-serif;

    font-size: 23px;
    line-height: 1.4;

    font-weight: 500;

    color: #333333;
}


/* =========================================
   MAIN CONTENT
   ========================================= */

.property-financing-content {

    display: grid;

    grid-template-columns: 1fr 270px 1fr;

    align-items: center;

    column-gap: 38px;

    width: 100%;
}


/* =========================================
   LEFT / RIGHT COLUMNS
   ========================================= */

.property-financing-left,
.property-financing-right {

    display: flex;

    flex-direction: column;

    justify-content: space-between;

    height: 215px;
}


/* =========================================
   FINANCING ITEM
   ========================================= */

.financing-item {

    display: flex;

    align-items: center;

    gap: 11px;

    min-height: 48px;

    width: 100%;
}


/* =========================================
   ICON
   ========================================= */

.financing-icon {

    width: 34px;
    height: 34px;

    min-width: 34px;

    display: flex;

    align-items: center;

    justify-content: center;

    background: #eaf2ff;

    border-radius: 7px;

    color: #1467d9;

    font-size: 15px;

    flex-shrink: 0;
}


/* =========================================
   TEXT
   ========================================= */

.financing-text {

    font-family: Arial, sans-serif;

    font-size: 14px;

    line-height: 1.4;

    font-weight: 400;

    color: #222222;

    max-width: 245px;
}


/* =========================================
   CENTER IMAGE
   ========================================= */

.property-financing-image {

    width: 252px;

    height: 170px;

    margin: 0 auto;

    position: relative;

    display: flex;

    align-items: center;

    justify-content: center;

    background: #ffffff;

    /* border: 2px solid #7183a9; */

    box-sizing: border-box;

    overflow: hidden;
}


/* Image */

.property-financing-image img {

    display: block;

    width: 100%;

    height: 100%;

    object-fit: contain;

    object-position: center;

    padding: 0;

    margin: 0;
}


/* =========================================
   DESKTOP ALIGNMENT
   ========================================= */

.property-financing-left .financing-item {

    justify-content: flex-start;
}


.property-financing-right .financing-item {

    justify-content: flex-start;
}


/* =========================================
   TABLET
   ========================================= */

@media (max-width: 900px) {

    .property-financing-section {

        padding-left: 15px;
        padding-right: 15px;

    }


    .property-financing-content {

        grid-template-columns: 1fr 240px 1fr;

        column-gap: 22px;

    }


    .property-financing-image {

        width: 225px;

        height: 155px;

    }


    .financing-text {

        font-size: 13px;

        max-width: 220px;

    }


    .financing-icon {

        width: 33px;

        height: 33px;

        min-width: 33px;

        font-size: 14px;

    }

}


/* =========================================
   MOBILE
   ========================================= */

@media (max-width: 700px) {

    .property-financing-section {

        padding: 40px 15px 50px;

    }


    .property-financing-heading {

        margin-bottom: 30px;

    }


    .property-financing-heading h2 {

        font-size: 20px;

        line-height: 1.4;

    }


    .property-financing-content {

        display: flex;

        flex-direction: column;

        gap: 25px;

    }


    /* Center Image */

    .property-financing-image {

        order: 1;

        width: 280px;

        height: 180px;

        margin: 0 auto;

    }


    /* Left */

    .property-financing-left {

        order: 2;

    }


    /* Right */

    .property-financing-right {

        order: 3;

    }


    .property-financing-left,
    .property-financing-right {

        width: 100%;

        height: auto;

        gap: 18px;

    }


    .financing-item {

        width: 100%;

        min-height: 45px;

    }


    .financing-icon {

        width: 34px;

        height: 34px;

        min-width: 34px;

        font-size: 14px;

    }


    .financing-text {

        max-width: none;

        font-size: 14px;

        line-height: 1.4;

    }

}


/* =========================================
   SMALL MOBILE
   ========================================= */

@media (max-width: 480px) {

    .property-financing-section {

        padding: 35px 14px 45px;

    }


    .property-financing-heading h2 {

        font-size: 19px;

    }


    .property-financing-image {

        width: 270px;

        height: 175px;

    }


    .financing-text {

        font-size: 13px;

    }


    .financing-icon {

        width: 32px;

        height: 32px;

        min-width: 32px;

    }

}


/* ==========================================
   MISSION / VALUES / VISION
========================================== */

.mission-values-section {
    width: 100%;
    padding: 30px 0 70px;
    background: #fff;
}

.mission-values-section .container {
    max-width: 1100px;
    margin: 0 auto;
    padding: 0 20px;
}


/* ==========================================
   THREE COLUMN ROW
========================================== */

.mission-values-row {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 38px;
    align-items: start;
}


/* ==========================================
   ITEM
========================================== */

.mission-values-item {
    width: 100%;
}


/* ==========================================
   IMAGE
========================================== */

.mission-values-image {
    width: 100%;
    height: 155px;
    overflow: hidden;
    border-radius: 9px;
    margin-bottom: 20px;
}

.mission-values-image img {
    width: 100%;
    height: 100%;
    display: block;
    object-fit: cover;
}


/* ==========================================
   CONTENT
========================================== */

.mission-values-content h3 {
    margin: 0 0 8px;
    font-size: 16px;
    line-height: 1.3;
    font-weight: 600;
    color: #333;
}

.mission-values-content p {
    margin: 0;
    font-size: 14px;
    line-height: 1.4;
    color: #666;
    font-weight: 400;
}


/* ==========================================
   TABLET
========================================== */

@media (max-width: 991px) {

    .mission-values-section {
        padding: 25px 0 60px;
    }

    .mission-values-row {
        gap: 25px;
    }

    .mission-values-image {
        height: 145px;
    }

}


/* ==========================================
   MOBILE
========================================== */

@media (max-width: 767px) {

    .mission-values-section {
        padding: 25px 15px 50px;
    }

    .mission-values-section .container {
        padding: 0;
    }

    .mission-values-row {
        grid-template-columns: 1fr;
        gap: 35px;
    }

    .mission-values-image {
        height: 190px;
        margin-bottom: 16px;
    }

    .mission-values-content h3 {
        font-size: 18px;
        margin-bottom: 7px;
    }

    .mission-values-content p {
        font-size: 12px;
        line-height: 1.5;
    }

}


/* ==========================================
   SMALL MOBILE
========================================== */

@media (max-width: 480px) {

    .mission-values-section {
        padding: 20px 12px 40px;
    }

    .mission-values-row {
        gap: 30px;
    }

    .mission-values-image {
        height: 175px;
        border-radius: 8px;
    }

}


