/* ==========================================
   AWARDS SECTION
========================================== */

.awards-section {
    width: 100% !important;
    padding: 25px 0 50px !important;
    background: #dce9fe !important;
}

.awards-section .container-tab {
    width: 100% !important;
    max-width: 1040px !important;
    margin: 0 auto !important;
    padding: 0 20px !important;
    box-sizing: border-box !important;
}


/* ==========================================
   HEADING
========================================== */

.awards-section .awards-header {
    width: 100% !important;
    text-align: center !important;
    margin-bottom: 20px !important;
}

.awards-section .awards-header h4 {
    margin: 0 0 5px !important;
    padding: 0 !important;

    color: #295cab !important;

    font-size: 13px !important;
    line-height: 1.3 !important;
    font-weight: 600 !important;
}

.awards-section .awards-header h2 {
    margin: 0 !important;
    padding: 0 !important;

    color: #333333 !important;

    font-size: 21px !important;
    line-height: 1.3 !important;
    font-weight: 700 !important;
}


/* ==========================================
   AWARDS GRID
========================================== */

.awards-section .awards-grid {
    width: 100% !important;

    display: grid !important;

    grid-template-columns: repeat(3, minmax(0, 1fr)) !important;

    gap: 10px 12px !important;

    align-items: stretch !important;
}


/* ==========================================
   AWARD CARD
========================================== */

.awards-section .award-card {
    width: 100% !important;

    min-height: 102px !important;

    background: #ffffff !important;

    border-radius: 10px !important;

    box-shadow: 0 3px 12px rgba(0, 0, 0, 0.08) !important;

    display: flex !important;

    /*
       IMPORTANT FIX
       Force trophy and content into one row
    */
    flex-direction: row !important;

    align-items: center !important;
    justify-content: flex-start !important;

    padding: 12px 15px !important;

    box-sizing: border-box !important;

    overflow: visible !important;

    transition: transform 0.2s ease,
                box-shadow 0.2s ease !important;
}

.awards-section .award-card:hover {
    transform: translateY(-2px) !important;

    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.10) !important;
}


/* ==========================================
   TROPHY
========================================== */

.awards-section .award-trophy {
    width: 58px !important;
    min-width: 58px !important;

    height: 72px !important;

    flex: 0 0 58px !important;

    display: flex !important;

    align-items: center !important;
    justify-content: center !important;

    margin: 0 7px 0 0 !important;

    padding: 0 !important;
}

.awards-section .award-trophy img {
    width: 72px !important;
    height: 65px !important;

    max-width: none !important;

    object-fit: contain !important;

    display: block !important;

    margin: 0 !important;
}


/* ==========================================
   AWARD INFORMATION
========================================== */

.awards-section .award-info {
    flex: 1 1 auto !important;

    min-width: 0 !important;

    width: auto !important;

    display: flex !important;

    flex-direction: column !important;

    align-items: flex-start !important;

    justify-content: center !important;

    text-align: left !important;

    padding: 0 !important;

    margin: 0 !important;
}


/* ==========================================
   BANK LOGO
========================================== */

.awards-section .bank-logo {
    width: 100% !important;

    height: 22px !important;

    display: flex !important;

    align-items: center !important;
    justify-content: flex-start !important;

    margin: 0 0 4px 0 !important;

    padding: 0 !important;
}

.awards-section .bank-logo img {
    display: block !important;

    width: auto !important;
    height: auto !important;

    max-width: 78px !important;
    max-height: 32px !important;

    object-fit: contain !important;

    object-position: left center !important;

    margin: 0 !important;
}


/* ==========================================
   AWARD NAME
========================================== */

.awards-section .award-name {
    width: 100% !important;

    color: #333333 !important;

    font-size: 18px !important;

    line-height: 1.2 !important;

    font-weight: 600 !important;

    text-align: left !important;

    word-break: normal !important;

    overflow-wrap: break-word !important;

    white-space: normal !important;

    margin: 0 !important;

    padding: 0 !important;
}


/* ==========================================
   AWARD BOTTOM / RANK / YEAR
========================================== */

.awards-section .award-bottom {
    width: 100% !important;

    color: #333333 !important;

    font-size: 17px !important;

    line-height: 1.2 !important;

    font-weight: 600 !important;

    text-align: left !important;

    margin: 1px 0 0 0 !important;

    padding: 0 !important;
}

.awards-section .award-bottom sup {
    font-size: 7px !important;

    position: relative !important;

    top: -3px !important;
}

.awards-section .award-bottom span {
    font-size: 14px !important;

    font-weight: 400 !important;

    margin-left: 3px !important;

    color: #444444 !important;
}


/* ==========================================
   TABLET
========================================== */

@media (max-width: 991px) {

    .awards-section .container-tab {
        padding: 0 15px !important;
    }

    .awards-section .awards-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
    }

    .awards-section .award-card {
        min-height: 105px !important;
    }

}


/* ==========================================
   MOBILE
========================================== */

@media (max-width: 600px) {

    .awards-section {
        padding: 20px 0 40px !important;
    }

    .awards-section .awards-header {
        margin-bottom: 18px !important;
    }

    .awards-section .awards-header h4 {
        font-size: 12px !important;
    }

    .awards-section .awards-header h2 {
        font-size: 19px !important;
    }

    .awards-section .awards-grid {
        grid-template-columns: 1fr !important;

        gap: 10px !important;
    }

    .awards-section .award-card {
        min-height: 100px !important;

        /*
           Keep row layout on mobile too
        */
        flex-direction: row !important;

        padding: 12px 15px !important;
    }

    .awards-section .award-trophy {
        width: 60px !important;
        min-width: 60px !important;

        flex-basis: 60px !important;

        height: 70px !important;

        margin-right: 6px !important;
    }

    .awards-section .award-trophy img {
        width: 48px !important;
        height: 64px !important;
    }

    .awards-section .award-info {
        text-align: left !important;
        align-items: flex-start !important;
    }

    .awards-section .award-name {
        font-size: 13px !important;

        text-align: left !important;
    }

    .awards-section .award-bottom {
        font-size: 12px !important;

        text-align: left !important;
    }

    .awards-section .award-bottom span {
        font-size: 10px !important;
    }

}


/* ==========================================
   SMALL MOBILE
========================================== */

@media (max-width: 400px) {

    .awards-section .container-tab {
        padding: 0 10px !important;
    }

    .awards-section .award-card {
        padding: 10px 12px !important;

        flex-direction: row !important;
    }

    .awards-section .award-trophy {
        width: 55px !important;
        min-width: 55px !important;

        flex-basis: 55px !important;
    }

    .awards-section .award-trophy img {
        width: 45px !important;
        height: 60px !important;
    }

    .awards-section .award-name {
        font-size: 12px !important;
    }

    .awards-section .award-bottom {
        font-size: 11px !important;
    }

    .awards-section .award-bottom span {
        font-size: 9px !important;
    }

}

    /* ============================================================
   OUR TEAM SECTION – MOBILE RESPONSIVE (UI unchanged)
   Only adds responsive behavior, preserves all existing styles
   ============================================================ */

/* ----- force images to be responsive & maintain aspect ratio ----- */
.about-page-team-image img {
  width: 100%;
  height: auto;
  display: block;
}

/* ----- mobile first: ensure grid stacks properly on small screens ----- */
.about-page-team-grid {
  display: grid;
  grid-template-columns: 1fr; /* single column on mobile */
  gap: 1.5rem;
  justify-items: center;
}

/* ----- cards take full width on mobile, but keep max-width for readability ----- */
.about-page-team-card {
  width: 100%;
  max-width: 320px; /* prevents cards from becoming too wide on mobile */
  margin: 0 auto;
}

/* ----- tablet (portrait) – 2 columns ----- */
@media (min-width: 600px) {
  .about-page-team-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 2rem;
  }
  .about-page-team-card {
    max-width: 340px;
  }
}

/* ----- desktop – 3 columns ----- */
@media (min-width: 1024px) {
  .about-page-team-grid {
    grid-template-columns: repeat(3, 1fr);
    gap: 2.5rem;
  }
  .about-page-team-card {
    max-width: 360px;
  }
}

/* ----- large screens – 4 columns (optional, but matches your grid) ----- */
@media (min-width: 1280px) {
  .about-page-team-grid {
    grid-template-columns: repeat(4, 1fr);
  }
  .about-page-team-card {
    max-width: 100%;
  }
}

/* ----- extra small devices (below 380px) – prevent overflow ----- */
@media (max-width: 380px) {
  .about-page-team-grid {
    gap: 1.2rem;
  }
  .about-page-team-card {
    max-width: 100%;
  }
  .about-page-team-info {
    padding: 0.8rem 0.5rem 1.2rem;
  }
  .about-page-team-name {
    font-size: 1rem;
  }
  .about-page-team-designation {
    font-size: 0.8rem;
  }
}

/* ----- preserve all existing styles: no UI changes ----- */
/* The following ensures that your existing styles (colors, fonts, shadows, etc.)
   remain untouched. Only layout & spacing are adjusted for responsiveness. */

.about-page-team-section {
  /* your existing styles remain */
}

.about-page-section-container {
  /* your existing styles remain */
}

.about-page-section-header {
  /* your existing styles remain */
}

.about-page-section-label {
  /* your existing styles remain */
}

.about-page-team-overlay {
  /* your existing styles remain */
}

.about-page-team-social {
  /* your existing styles remain */
}

.about-page-social-icon {
  /* your existing styles remain */
}

/* ====== END – NO UI CHANGES, ONLY RESPONSIVE BEHAVIOR ====== */



