   FEATURES WRAPPER
========================================================= */

.home-loan-features-wrapper {
    width: 100%;

    display: grid;

    grid-template-columns: 1fr 330px 1fr;

    column-gap: 40px;

    align-items: center;
}


/* =========================================================
   FEATURE COLUMNS
========================================================= */

.home-loan-feature-column {
    width: 100%;

    display: flex;

    flex-direction: column;

    justify-content: space-between;

    gap: 65px;
}


/* =========================================================
   FEATURE ITEM
========================================================= */

.home-loan-feature-item {
    width: 100%;

    display: flex;

    align-items: center;

    gap: 12px;
}


/* =========================================================
   ICON BOX
========================================================= */

.home-loan-feature-icon {
    flex: 0 0 36px;

    width: 36px;

    height: 36px;

    display: flex;

    align-items: center;

    justify-content: center;

    background: #eaf3ff;

    border-radius: 7px;

    color: #2878e5;

    font-size: 17px;
}


/* =========================================================
   FEATURE TEXT
========================================================= */

.home-loan-feature-text {
    flex: 1;

    min-width: 0;
}


.home-loan-feature-text h4 {
    margin: 0;

    color: #222222;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 14px;

    font-weight: 400;

    line-height: 1.3;
}


/* =========================================================
   CENTER
========================================================= */

.home-loan-center {
    width: 100%;

    display: flex;

    flex-direction: column;

    align-items: center;

    justify-content: center;
}


/* =========================================================
   HOUSE IMAGE
========================================================= */

.home-loan-house {
    width: 100%;

    display: flex;

    align-items: center;

    justify-content: center;

    margin-bottom: 30px;
}


.home-loan-house img {
    display: block;

    width: 100%;

    max-width: 340px;

    height: auto;

    object-fit: contain;
}


/* =========================================================
   APPLY BUTTON
========================================================= */

.home-loan-feature-btn {
    display: inline-flex;

    align-items: center;

    justify-content: center;

    width: 157px;

    height: 46px;

    background: #2878e5;

    color: #ffffff !important;

    border-radius: 6px;

    text-decoration: none !important;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 14px;

    font-weight: 600;

    transition: all 0.3s ease;
}


.home-loan-feature-btn:hover {
    background: #1265d2;

    color: #ffffff !important;

    transform: translateY(-2px);

    box-shadow: 0 5px 15px rgba(40, 120, 229, 0.25);
}


