/* =========================================================
   MAIN SECTION
========================================================= */

.property-benefits-section {

    width: 100%;

    background: #f8fafc;

    padding: 25px 15px 70px;

    overflow: hidden;

    box-sizing: border-box;
}


/* =========================================================
   CONTAINER
========================================================= */

.property-benefits-container {

    width: 100%;

    max-width: 1250px;

    margin: 0 auto;
}


/* =========================================================
   HEADING
========================================================= */

.property-benefits-heading {

    text-align: center;

    margin-bottom: 48px;
}


.property-benefits-heading h2 {

    margin: 0 0 5px;

    color: #333333;

    font-size: 26px;

    line-height: 1.3;

    font-weight: 600;
}


.property-benefits-heading p {

    margin: 0;

    color: #707070;

    font-size: 15px;

    line-height: 1.4;

    font-weight: 400;
}


/* =========================================================
   GRID
========================================================= */

.property-benefits-grid {

    display: grid;

    grid-template-columns: repeat(3, 1fr);

    column-gap: 32px;

    row-gap: 50px;

    width: 100%;
}


/* =========================================================
   CARD
========================================================= */

.property-benefit-card {

    width: 100%;

    min-height: 220px;

    box-sizing: border-box;

    padding: 32px 24px 25px;

    background: #ffffff;

    border: 1px solid #4d7ff0;

    border-radius: 16px;

    box-shadow: 0 7px 20px rgba(40, 117, 223, 0.10);

    transition: all 0.3s ease;
}


/* =========================================================
   ICON BOX
========================================================= */

.property-benefit-icon {

    width: 42px;

    height: 42px;

    display: flex;

    align-items: center;

    justify-content: center;

    background: #e5efff;

    border-radius: 5px;

    margin-bottom: 26px;
}


.property-benefit-icon i {

    color: #2875df;

    font-size: 19px;

    line-height: 1;
}


/* =========================================================
   CARD TITLE
========================================================= */

.property-benefit-card h3 {

    margin: 0 0 8px;

    color: #3b3b3b;

    font-size: 22px;

    line-height: 1.25;

    font-weight: 600;
}


/* =========================================================
   CARD TEXT
========================================================= */

.property-benefit-card p {

    margin: 0;

    color: #555555;

    font-size: 15px;

    line-height: 1.25;

    font-weight: 400;
}


/* =========================================================
   HOVER
========================================================= */

.property-benefit-card:hover {

    transform: translateY(-3px);

    box-shadow: 0 12px 28px rgba(40, 117, 223, 0.16);
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 991px) {

    .property-benefits-section {

        padding: 30px 20px 55px;
    }

    .property-benefits-grid {

        grid-template-columns: repeat(2, 1fr);

        gap: 25px;
    }

    .property-benefit-card {

        min-height: 220px;
    }

    .property-benefit-card h3 {

        font-size: 20px;
    }

}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 767px) {

    .property-benefits-section {

        padding: 28px 15px 45px;
    }


    /* HEADING */

    .property-benefits-heading {

        margin-bottom: 30px;
    }


    .property-benefits-heading h2 {

        font-size: 22px;

        line-height: 1.3;
    }


    .property-benefits-heading p {

        font-size: 14px;
    }


    /* ONE CARD PER ROW */

    .property-benefits-grid {

        display: flex;

        flex-direction: column;

        gap: 20px;
    }


    /* CARD */

    .property-benefit-card {

        width: 100%;

        min-height: auto;

        padding: 25px 20px;

        border-radius: 14px;
    }


    /* ICON */

    .property-benefit-icon {

        width: 42px;

        height: 42px;

        margin-bottom: 22px;
    }


    /* TITLE */

    .property-benefit-card h3 {

        font-size: 20px;

        line-height: 1.3;

        margin-bottom: 8px;
    }


    /* TEXT */

    .property-benefit-card p {

        font-size: 14px;

        line-height: 1.45;
    }

}


