/* =========================================================
   MAIN SECTION
========================================================= */

.property-eligibility-section {
    width: 100%;
    padding: 30px 15px 70px;
    background: #f8fafc;
    box-sizing: border-box;
    overflow: hidden;
}

.property-eligibility-container {
    width: 100%;
    max-width: 1250px;
    margin: 0 auto;
}


/* =========================================================
   TABS
========================================================= */

.property-eligibility-tabs {

    width: 100%;

    display: grid;

    grid-template-columns:
        1fr
        1fr
        1.25fr
        1.25fr
        1.2fr;

    gap: 0;

    padding: 4px;

    background: #eaf2fc;

    border-radius: 10px;

    box-sizing: border-box;

    margin-bottom: 48px;
}


/* TAB */

.property-eligibility-tab {

    border: 0;

    background: transparent;

    color: #333;

    min-height: 64px;

    padding: 8px 12px;

    border-radius: 8px;

    font-size: 15px;

    line-height: 1.15;

    font-weight: 500;

    cursor: pointer;

    transition: all 0.25s ease;

    font-family: inherit;
}


/* ACTIVE TAB */

.property-eligibility-tab.active {

    background: #2875df;

    color: #ffffff;

    box-shadow: 0 3px 8px rgba(40,117,223,0.20);
}


/* HOVER */

.property-eligibility-tab:not(.active):hover {

    background: rgba(40,117,223,0.08);

    color: #2875df;
}


/* =========================================================
   TAB CONTENT
========================================================= */

.property-eligibility-tab-content {

    display: none;

    width: 100%;
}

.property-eligibility-tab-content.active {

    display: block;
}


/* =========================================================
   TWO COLUMNS
========================================================= */

.property-eligibility-grid {

    display: grid;

    grid-template-columns: 1fr 1fr;

    gap: 48px;

    align-items: start;
}


/* =========================================================
   COLUMN TITLE
========================================================= */

.property-column-title {

    margin: 0 0 20px;

    color: #333333;

    font-size: 20px;

    line-height: 1.3;

    font-weight: 500;
}


/* =========================================================
   CRITERIA LIST
========================================================= */

.property-criteria-list {

    display: flex;

    flex-direction: column;

    gap: 24px;
}


/* =========================================================
   CRITERIA CARD
========================================================= */

.property-criteria-card {

    width: 100%;

    min-height: 74px;

    display: flex;

    align-items: center;

    gap: 20px;

    padding: 14px 16px;

    box-sizing: border-box;

    background: #ffffff;

    border: 1px solid #4d7ff0;

    border-radius: 14px;

    box-shadow:
        0 6px 18px rgba(40,117,223,0.10);

}


/* =========================================================
   CHECK ICON
========================================================= */

.property-card-icon {

    width: 42px;

    height: 42px;

    min-width: 42px;

    display: flex;

    align-items: center;

    justify-content: center;

    background: #e5efff;

    border-radius: 5px;

    color: #2875df;
}

.property-card-icon i {

    font-size: 21px;

    color: #2875df;
}


/* =========================================================
   CARD TEXT
========================================================= */

.property-card-text {

    color: #3d3d3d;

    font-size: 16px;

    line-height: 1.25;

    font-weight: 400;
}


/* =========================================================
   DOCUMENT LIST
========================================================= */

.property-document-list {

    display: flex;

    flex-direction: column;

    gap: 24px;
}


/* =========================================================
   DOCUMENT CARD
========================================================= */

.property-document-card {

    width: 100%;

    min-height: 74px;

    display: flex;

    align-items: center;

    gap: 24px;

    padding: 14px 24px;

    box-sizing: border-box;

    background: #ffffff;

    border: 1px solid #4d7ff0;

    border-radius: 14px;

    box-shadow:
        0 6px 18px rgba(40,117,223,0.10);

    color: #3d3d3d;

    font-size: 16px;

    line-height: 1.25;

    font-weight: 400;
}


/* =========================================================
   DOCUMENT ICON
========================================================= */

.property-document-icon {

    width: 42px;

    height: 42px;

    min-width: 42px;

    display: flex;

    align-items: center;

    justify-content: center;

    background: #e5efff;

    border-radius: 5px;
}

.property-document-icon i {

    color: #2875df;

    font-size: 19px;
}


/* =========================================================
   CARD HOVER
========================================================= */

.property-criteria-card,
.property-document-card {

    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease;
}

.property-criteria-card:hover,
.property-document-card:hover {

    transform: translateY(-2px);

    box-shadow:
        0 10px 24px rgba(40,117,223,0.15);
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 991px) {

    .property-eligibility-section {

        padding: 25px 20px 55px;
    }


    .property-eligibility-tabs {

        grid-template-columns: repeat(3, 1fr);

        row-gap: 4px;

        margin-bottom: 35px;
    }


    .property-eligibility-grid {

        grid-template-columns: 1fr;

        gap: 35px;
    }


    .property-eligibility-tab {

        font-size: 14px;

        min-height: 58px;
    }

}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 767px) {

    .property-eligibility-section {

        padding: 22px 12px 45px !important;
    }


    .property-eligibility-container {

        width: 100% !important;
    }


    /* =====================================================
       TABS
    ===================================================== */

    .property-eligibility-tabs {

        display: flex !important;

        width: 100% !important;

        overflow-x: auto !important;

        overflow-y: hidden !important;

        gap: 5px !important;

        padding: 4px !important;

        margin-bottom: 30px !important;

        border-radius: 9px !important;

        scrollbar-width: none;
    }

    .property-eligibility-tabs::-webkit-scrollbar {
        display: none;
    }


    .property-eligibility-tab {

        flex: 0 0 145px !important;

        width: 145px !important;

        min-width: 145px !important;

        min-height: 58px !important;

        padding: 7px 8px !important;

        font-size: 13px !important;

        line-height: 1.15 !important;

        border-radius: 7px !important;

        white-space: normal !important;
    }


    /* =====================================================
       CONTENT
    ===================================================== */

    .property-eligibility-grid {

        display: flex !important;

        flex-direction: column !important;

        gap: 30px !important;

        width: 100% !important;
    }


    .property-eligibility-column {

        width: 100% !important;
    }


    /* =====================================================
       TITLES
    ===================================================== */

    .property-column-title {

        margin-bottom: 15px !important;

        font-size: 18px !important;

        line-height: 1.3 !important;
    }


    /* =====================================================
       CARDS
    ===================================================== */

    .property-criteria-list,
    .property-document-list {

        gap: 14px !important;
    }


    .property-criteria-card,
    .property-document-card {

        width: 100% !important;

        min-height: 64px !important;

        padding: 12px !important;

        gap: 12px !important;

        border-radius: 11px !important;
    }


    /* =====================================================
       ICON
    ===================================================== */

    .property-card-icon,
    .property-document-icon {

        width: 40px !important;

        height: 40px !important;

        min-width: 40px !important;
    }


    .property-card-icon i {

        font-size: 19px !important;
    }


    .property-document-icon i {

        font-size: 17px !important;
    }


    /* =====================================================
       TEXT
    ===================================================== */

    .property-card-text,
    .property-document-card {

        font-size: 14px !important;

        line-height: 1.35 !important;
    }

}


/* =========================================================
   SMALL MOBILE
========================================================= */

@media (max-width: 480px) {

    .property-eligibility-section {

        padding-left: 10px !important;

        padding-right: 10px !important;
    }


    .property-eligibility-tab {

        flex-basis: 135px !important;

        width: 135px !important;

        min-width: 135px !important;

        font-size: 12px !important;
    }


    .property-column-title {

        font-size: 17px !important;
    }


    .property-criteria-card,
    .property-document-card {

        padding: 11px !important;

        gap: 11px !important;
    }


    .property-card-icon,
    .property-document-icon {

        width: 38px !important;

        height: 38px !important;

        min-width: 38px !important;
    }


    .property-card-text,
    .property-document-card {

        font-size: 13px !important;

        line-height: 1.35 !important;
    }

}




/* =========================================================
   PROPERTY OVERVIEW SECTION
========================================================= */

.property-overview-section {
    width: 100%;
    background: #f8fafc;
    padding: 35px 20px 55px;
    overflow: hidden;
}


/* MAIN CONTAINER */

.property-overview-container {
    width: 100%;
    max-width: 1100px;
    margin: 0 auto;
}


/* =========================================================
   HEADING
========================================================= */

.property-overview-heading {
    text-align: center;
    margin-bottom: 45px;
}

.property-overview-label {
    color: #2875df;
    font-size: 15px;
    font-weight: 500;
    margin-bottom: 8px;
}

.property-overview-heading h2 {
    margin: 0 0 8px;
    color: #333333;
    font-size: 24px;
    line-height: 1.3;
    font-weight: 600;
}

.property-overview-heading p {
    margin: 0;
    color: #727272;
    font-size: 15px;
    line-height: 1.4;
    font-weight: 400;
}


/* =========================================================
   MAIN 3 COLUMN AREA
========================================================= */

.property-overview-content {
    display: grid;
    grid-template-columns: 1fr 340px 1fr;
    align-items: center;
    column-gap: 25px;
}


/* =========================================================
   FEATURES
========================================================= */

.property-features {
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    height: 350px;
}

.property-features-left {
    align-items: flex-start;
}

.property-features-right {
    align-items: flex-start;
}


/* FEATURE */

.property-feature {
    display: flex;
    align-items: center;
    gap: 12px;
    min-height: 65px;
}


/* =========================================================
   ICON BOX
========================================================= */

.property-feature-icon {
    width: 41px;
    height: 41px;
    min-width: 41px;

    display: flex;
    align-items: center;
    justify-content: center;

    background: #e5efff;
    border-radius: 6px;

    color: #2875df;

    font-size: 19px;
}


/* ICON */

.property-feature-icon i {
    color: #2875df;
}


/* =========================================================
   FEATURE TEXT
========================================================= */

.property-feature-text {
    color: #252525;
    font-size: 14px;
    line-height: 1.3;
    font-weight: 500;
}


/* =========================================================
   CENTER IMAGE
========================================================= */

.property-overview-center {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
}


/* IMAGE WRAPPER */

.property-image-wrapper {
    width: 330px;
    height: 250px;

    display: flex;
    align-items: center;
    justify-content: center;
}


/* IMAGE */

.property-main-image {
    width: 100%;
    max-width: 330px;
    height: auto;
    object-fit: contain;
    display: block;
}


/* =========================================================
   APPLY BUTTON
========================================================= */

.property-apply-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;

    width: 168px;
    height: 50px;

    background: #2875df;
    color: #ffffff;

    border-radius: 8px;

    text-decoration: none;

    font-size: 15px;
    font-weight: 600;

    margin-top: 5px;

    transition: all 0.3s ease;
}

.property-apply-btn:hover {
    background: #1f64c5;
    color: #ffffff;
    transform: translateY(-2px);
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 991px) {

    .property-overview-section {
        padding: 35px 20px 50px;
    }

    .property-overview-content {
        grid-template-columns: 1fr 280px 1fr;
        column-gap: 12px;
    }

    .property-image-wrapper {
        width: 280px;
        height: 220px;
    }

    .property-main-image {
        max-width: 280px;
    }

    .property-feature-text {
        font-size: 13px;
    }

    .property-feature-icon {
        width: 38px;
        height: 38px;
        min-width: 38px;
        font-size: 17px;
    }

}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 767px) {

    .property-overview-section {
        padding: 35px 15px 45px;
    }

    .property-overview-heading {
        margin-bottom: 25px;
    }

    .property-overview-label {
        font-size: 14px;
    }

    .property-overview-heading h2 {
        font-size: 22px;
    }

    .property-overview-heading p {
        font-size: 14px;
        line-height: 1.5;
    }

    .desktop-break {
        display: none;
    }


    /* STACK EVERYTHING */

    .property-overview-content {
        display: flex;
        flex-direction: column;
        gap: 10px;
    }


    /* CENTER IMAGE FIRST */

    .property-overview-center {
        order: 1;
        width: 100%;
    }


    .property-features-left {
        order: 2;
    }

    .property-features-right {
        order: 3;
    }


    /* FEATURES */

    .property-features {
        width: 100%;
        height: auto;
        gap: 15px;
    }


    .property-feature {
        width: 100%;
        min-height: auto;
        gap: 12px;
    }


    .property-feature-text {
        font-size: 14px;
    }


    /* IMAGE */

    .property-image-wrapper {
        width: 100%;
        max-width: 320px;
        height: 220px;
    }

    .property-main-image {
        width: 100%;
        max-width: 320px;
    }


    /* BUTTON */

    .property-apply-btn {
        margin-bottom: 15px;
    }

}


/* =========================================================
   SMALL MOBILE
========================================================= */

@media (max-width: 480px) {

    .property-overview-heading h2 {
        font-size: 20px;
    }

    .property-overview-heading p {
        font-size: 13px;
    }

    .property-image-wrapper {
        max-width: 290px;
        height: 200px;
    }

    .property-main-image {
        max-width: 290px;
    }

}



/* =========================================================
   MAIN SECTION
========================================================= */

.home-loan-emi-section {

    width: 100%;

    background: #edf4fd;

    padding: 45px 25px 60px;

    box-sizing: border-box;

    overflow: hidden;
}


/* =========================================================
   MAIN WRAPPER
========================================================= */

.home-loan-emi-wrapper {

    width: 100%;

    max-width: 1120px;

    margin: 0 auto;

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 70px;

    box-sizing: border-box;
}


/* =========================================================
   LEFT SIDE
========================================================= */

.home-loan-emi-left {

    flex: 1;

    min-width: 0;
}


.home-loan-emi-left h2 {

    margin: 0 0 12px;

    color: #333333;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 34px;

    font-weight: 600;

    line-height: 1.15;

    letter-spacing: -0.5px;
}


.home-loan-emi-left p {

    margin: 0 0 22px;

    color: #707070;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 14px;

    line-height: 1.4;
}


/* =========================================================
   BUTTON
========================================================= */

.home-loan-emi-btn {

    display: inline-flex;

    align-items: center;

    justify-content: center;

    gap: 14px;

    min-width: 215px;

    height: 48px;

    padding: 0 22px;

    background: #2878e5;

    color: #ffffff !important;

    border-radius: 7px;

    text-decoration: none !important;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 14px;

    font-weight: 600;

    box-sizing: border-box;

    transition:
        all .25s ease;
}


.home-loan-emi-btn:hover {

    background: #1d66cc;

    color: #ffffff !important;

    transform: translateY(-1px);

    box-shadow:
        0 5px 14px rgba(40,120,229,.20);
}


.home-loan-emi-btn span {

    font-size: 23px;

    line-height: 1;
}


/* =========================================================
   RIGHT EMI CARD - LARGE
========================================================= */

.home-loan-emi-box {

    flex: 0 0 560px;

    width: 560px;

    min-height: 275px;

    padding: 36px 34px 30px;

    box-sizing: border-box;

    border-radius: 17px;

    background:
        linear-gradient(
            115deg,
            #2878e5 0%,
            #493ddd 48%,
            #b500d9 100%
        );

    color: #ffffff;

    box-shadow:
        0 7px 20px rgba(41,92,171,.13);
}


/* =========================================================
   CARD TITLE
========================================================= */

.emi-box-title {

    margin-bottom: 32px;

    color: #ffffff;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 15px;

    font-weight: 400;
}


/* =========================================================
   MAIN EMI
========================================================= */

.emi-amount {

    margin-bottom: 12px;

    color: #ffffff;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 38px;

    font-weight: 700;

    line-height: 1;
}


.emi-amount span {

    margin-left: 3px;

    font-size: 18px;

    font-weight: 400;
}


/* =========================================================
   LOAN DETAILS
========================================================= */

.emi-info {

    margin-bottom: 34px;

    color: rgba(255,255,255,.92);

    font-family: Arial, Helvetica, sans-serif;

    font-size: 12px;

    line-height: 1.4;
}


/* =========================================================
   BOTTOM VALUES
========================================================= */

.emi-bottom {

    width: 100%;

    display: grid;

    grid-template-columns:
        repeat(4, 1fr);

    gap: 25px;
}


.emi-value {

    display: flex;

    flex-direction: column;

    min-width: 0;
}


.emi-value strong {

    margin-bottom: 6px;

    color: #ffffff;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 24px;

    font-weight: 700;

    line-height: 1;
}


.emi-value small {

    color: rgba(255,255,255,.90);

    font-family: Arial, Helvetica, sans-serif;

    font-size: 12px;

    line-height: 1.2;
}


/* =========================================================
   LARGE DESKTOP
========================================================= */

@media (min-width: 1200px) {

    .home-loan-emi-wrapper {

        max-width: 1120px;

        gap: 75px;
    }


    .home-loan-emi-box {

        flex-basis: 580px;

        width: 580px;

        min-height: 285px;

        padding:
            38px
            36px
            32px;
    }


    .home-loan-emi-left h2 {

        font-size: 35px;
    }

}


/* =========================================================
   DESKTOP 992 - 1199
========================================================= */

@media (min-width: 992px) and (max-width: 1199px) {

    .home-loan-emi-wrapper {

        max-width: 1000px;

        gap: 45px;
    }


    .home-loan-emi-box {

        flex-basis: 520px;

