        min-height: 265px;

        padding:
            32px
            30px
            28px;
    }


    .home-loan-emi-left h2 {

        font-size: 31px;
    }


    .emi-amount {

        font-size: 35px;
    }

}


/* =========================================================
   TABLET
========================================================= */

@media (min-width: 768px) and (max-width: 991px) {

    .home-loan-emi-section {

        padding:
            40px
            25px
            55px;
    }


    .home-loan-emi-wrapper {

        gap: 30px;

        max-width: 900px;
    }


    .home-loan-emi-left h2 {

        font-size: 28px;
    }


