    }


    .emi-bottom {

        gap: 12px;
    }


    .emi-value strong {

        font-size: 19px;
    }


    .emi-value small {

        font-size: 10px;
    }

}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 767px) {

    .home-loan-emi-section {

        padding:
            38px
            15px
            48px;
    }


    .home-loan-emi-wrapper {

