    }


    .emi-amount {

        font-size: 30px;
    }


    .emi-amount span {

        font-size: 15px;
    }


    .emi-info {

        font-size: 10px;

        margin-bottom: 29px;
    }


    .emi-bottom {

        gap: 10px;
    }


    .emi-value strong {

        font-size: 18px;
    }


    .emi-value small {

        font-size: 10px;
    }

}


