/* =========================================================
   MAIN SECTION
========================================================= */

.property-loan-why {
    width: 100%;
    background: #f8fafc;
    padding: 25px 20px 60px;
    overflow: hidden;
}


/* =========================================================
   CONTAINER
========================================================= */

.property-loan-container {
    width: 100%;
    max-width: 1250px;
    margin: 0 auto;
}


/* =========================================================
   HEADING
========================================================= */

.property-loan-heading {
    text-align: center;
    margin-bottom: 48px;
}

.property-loan-heading h2 {
    margin: 0 0 4px;

    font-size: 26px;
    line-height: 1.3;

    font-weight: 600;
    color: #333333;
}


/* FIRST PARAGRAPH */

.property-loan-intro {
    margin: 0 auto 14px;

    font-size: 15px;
    line-height: 1.25;

    font-weight: 400;
}


/* BLUE TEXT */

.blue-text {
    color: #2875df;
}


/* SECOND PARAGRAPH */

.property-loan-description {
    margin: 0 auto;

    color: #777777;

    font-size: 15px;
    line-height: 1.35;

    font-weight: 400;
}


/* =========================================================
   CARDS GRID
========================================================= */

.property-loan-cards {
    display: grid;

    grid-template-columns: repeat(6, 1fr);

    column-gap: 32px;
    row-gap: 34px;

    align-items: start;
}


/* =========================================================
   CARD
========================================================= */

.property-loan-card {

    grid-column: span 2;

    min-height: 218px;

    padding: 32px 24px 25px;

    background: #ffffff;

    border: 1px solid #4d7ff0;

    border-radius: 16px;

    box-shadow: 0 8px 22px rgba(38, 102, 220, 0.12);

    box-sizing: border-box;

    transition: all 0.3s ease;
}


/* =========================================================
   BOTTOM CARDS
========================================================= */

/*
   4th card starts around 18%
   5th card starts around 50%
   This creates the centered 2-card row
*/

.property-loan-card:nth-child(4) {
    grid-column: 2 / span 2;
}

.property-loan-card:nth-child(5) {
    grid-column: 4 / span 2;
}


/* =========================================================
   ICON BOX
========================================================= */

.property-loan-icon {

    width: 42px;
    height: 42px;

    display: flex;
    align-items: center;
    justify-content: center;

    background: #e6efff;

    border-radius: 5px;

    margin-bottom: 25px;
}


/* ICON */

.property-loan-icon i {

    font-size: 19px;

    color: #2875df;
}


/* =========================================================
   CARD TITLE
========================================================= */

.property-loan-card h3 {

    margin: 0 0 8px;

    color: #3b3b3b;

    font-size: 22px;

    line-height: 1.2;

    font-weight: 600;
}


/* =========================================================
   CARD DESCRIPTION
========================================================= */

.property-loan-card p {

    margin: 0;

    color: #707070;

    font-size: 15px;

    line-height: 1.25;

    font-weight: 400;
}


/* =========================================================
   HOVER
========================================================= */

.property-loan-card:hover {

    transform: translateY(-3px);

    box-shadow: 0 12px 28px rgba(38, 102, 220, 0.17);

}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 991px) {

    .property-loan-cards {

        grid-template-columns: repeat(2, 1fr);

        gap: 25px;

    }

    .property-loan-card,
    .property-loan-card:nth-child(4),
    .property-loan-card:nth-child(5) {

        grid-column: auto;

    }

    .property-loan-card:last-child {

        grid-column: 1 / -1;

        max-width: calc(50% - 12px);

        margin: 0 auto;

    }

}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 767px) {

    .property-loan-why {

        padding: 30px 15px 45px;

    }


    .property-loan-heading {

        margin-bottom: 30px;

    }


    .property-loan-heading h2 {

        font-size: 23px;

    }


    .property-loan-intro {

        font-size: 14px;

        line-height: 1.45;

    }


    .property-loan-description {

        font-size: 14px;

        line-height: 1.45;

    }


    .desktop-only {

        display: none;

    }


    .property-loan-cards {

        display: flex;

        flex-direction: column;

        gap: 20px;

    }


    .property-loan-card,
    .property-loan-card:nth-child(4),
    .property-loan-card:nth-child(5) {

        width: 100%;

        max-width: 100%;

        min-height: auto;

        margin: 0;

        padding: 25px 20px;

    }


    .property-loan-card h3 {

        font-size: 20px;

    }


    .property-loan-card p {

        font-size: 14px;

    }

}


/* =========================================================
   SMALL MOBILE
========================================================= */

@media (max-width: 480px) {

    .property-loan-heading h2 {

        font-size: 21px;

    }


    .property-loan-card {

        border-radius: 14px;

    }


    .property-loan-card h3 {

        font-size: 19px;

    }

}

    /* =========================================================
   PROPERTY OVERVIEW - RESPONSIVE CSS
========================================================= */

.property-overview-section {
    width: 100%;
    padding: 35px 20px 55px;
    background: #f8fafc;
    overflow: hidden;
    box-sizing: border-box;
}

.property-overview-container {
    width: 100%;
    max-width: 1200px;
    margin: 0 auto;
}


/* =========================================================
   HEADING
========================================================= */

.property-overview-heading {
    text-align: center;
    margin-bottom: 45px;
}

.property-overview-heading h4 {
    margin-bottom: 8px;
}

.property-overview-heading h2 {
    margin-bottom: 10px;
}

.property-overview-heading p {
    margin: 0 auto;
    max-width: 1100px;
    color: #777;
    font-size: 15px;
    line-height: 1.45;
}


/* =========================================================
   MAIN CONTENT
========================================================= */

.property-overview-content {
    display: grid;
    grid-template-columns: 1fr 340px 1fr;
    align-items: center;
    gap: 25px;
}


/* =========================================================
   FEATURES
========================================================= */

.property-features {
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    height: 350px;
}

.property-feature {
    display: flex;
    align-items: center;
    gap: 12px;
}

.property-feature-icon {
    width: 42px;
    height: 42px;
    min-width: 42px;

    display: flex;
    align-items: center;
    justify-content: center;

    background: #e5efff;
    border-radius: 6px;

    color: #2875df;
}

.property-feature-icon i {
    font-size: 18px;
    color: #2875df;
}

.property-feature-text {
    color: #252525;
    font-size: 14px;
    line-height: 1.35;
    font-weight: 500;
}


/* =========================================================
   CENTER IMAGE
========================================================= */

.property-overview-center {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
}

.property-image-wrapper {
    width: 340px;
    height: 250px;

    display: flex;
    align-items: center;
    justify-content: center;
}

.property-main-image {
    display: block;
    width: 100%;
    max-width: 340px;
    height: auto;
    object-fit: contain;
}


/* =========================================================
   APPLY BUTTON
========================================================= */

.property-apply-btn {
    display: flex;
    align-items: center;
    justify-content: center;

    width: 168px;
    height: 50px;

    margin-top: 5px;

    background: #2875df;
    color: #fff;

    border-radius: 8px;

    text-decoration: none;

    font-size: 15px;
    font-weight: 600;

    transition: 0.3s ease;
}

.property-apply-btn:hover {
    background: #1f64c5;
    color: #fff;
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 991px) {

    .property-overview-section {
        padding: 35px 20px 50px;
    }

    .property-overview-content {
        grid-template-columns: 1fr 280px 1fr;
        gap: 15px;
    }

    .property-features {
        height: 320px;
    }

    .property-image-wrapper {
        width: 280px;
        height: 220px;
    }

    .property-main-image {
        max-width: 280px;
    }

    .property-feature-text {
        font-size: 13px;
    }

    .property-feature-icon {
        width: 40px;
        height: 40px;
        min-width: 40px;
    }

