/* 2nd design css */
/* =========================================
   OVERDRAFT FACILITY SECTION
========================================= */

.overdraft-section {
    width: 100%;
    background: #ffffff;
    padding: 65px 20px 80px;
    font-family: Arial, Helvetica, sans-serif;
}

.overdraft-section .container {
    max-width: 1050px;
    margin: 0 auto;
}


/* =========================================
   HEADING
========================================= */

.overdraft-heading {
    text-align: center;
    margin-bottom: 68px;
}

.overdraft-heading h2 {
    margin: 0;
    font-size: 23px;
    line-height: 1.35;
    font-weight: 500;
    color: #333333;
}

.overdraft-heading span {
    display: block;
    margin-top: 6px;
    font-size: 14px;
    font-weight: 400;
    color: #2875e5;
}

.overdraft-heading p {
    max-width: 930px;
    margin: 7px auto 0;
    font-size: 14px;
    line-height: 1.35;
    color: #6c6c6c;
}


/* =========================================
   MAIN CONTENT
========================================= */

.overdraft-content {
    display: grid;
    grid-template-columns: 1fr 300px 1fr;
    align-items: center;
    column-gap: 35px;
}


/* =========================================
   FEATURES
========================================= */

.overdraft-features {
    display: flex;
    flex-direction: column;
    gap: 68px;
}

.feature-item {
    display: flex;
    align-items: flex-start;
    gap: 12px;
}

.feature-icon {
    flex: 0 0 39px;
    width: 39px;
    height: 39px;
    background: #e8f1ff;
    border-radius: 4px;

    display: flex;
    align-items: center;
    justify-content: center;
}

.feature-icon i {
    color: #2875e5;
    font-size: 19px;
}

.feature-text {
    padding-top: 3px;
    color: #2f2f2f;
    font-size: 14px;
    line-height: 1.25;
    font-weight: 400;
}


/* =========================================
   CENTER
========================================= */

.overdraft-center {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
}

.overdraft-image {
    width: 230px;
    height: 220px;

    display: flex;
    align-items: center;
    justify-content: center;
}

.overdraft-image img {
    width: 100%;
    max-width: 230px;
    height: auto;
    display: block;
    object-fit: contain;
}


/* =========================================
   BUTTON
========================================= */

.overdraft-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;

    width: 156px;
    height: 47px;

    margin-top: 18px;

    background: #2875e5;
    color: #ffffff;

    text-decoration: none;

    border-radius: 8px;

    font-size: 14px;
    font-weight: 500;

    transition: all 0.3s ease;
}

.overdraft-btn:hover {
    background: #1762d0;
    color: #ffffff;
    transform: translateY(-2px);
}


/* =========================================
   BOOTSTRAP ICONS
========================================= */

@import url("https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css");


/* =========================================
   TABLET
========================================= */

@media (max-width: 991px) {

    .overdraft-section {
        padding: 55px 20px 65px;
    }

    .overdraft-content {
        grid-template-columns: 1fr 240px 1fr;
        column-gap: 20px;
    }

    .overdraft-features {
        gap: 50px;
    }

    .feature-text {
        font-size: 13px;
    }

    .overdraft-image {
        width: 200px;
        height: 200px;
    }

    .overdraft-heading {
        margin-bottom: 50px;
    }
}


/* =========================================
   MOBILE
========================================= */

@media (max-width: 767px) {

    .overdraft-section {
        padding: 45px 18px 55px;
    }

    .overdraft-heading {
        margin-bottom: 35px;
    }

    .overdraft-heading h2 {
        font-size: 21px;
    }

    .overdraft-heading span {
        font-size: 13px;
        margin-top: 7px;
    }

    .overdraft-heading p {
        font-size: 13px;
        line-height: 1.5;
        margin-top: 10px;
    }

    .overdraft-content {
        display: flex;
        flex-direction: column;
        gap: 30px;
    }

    /* Center image first */
    .overdraft-center {
        order: 1;
    }

    /* Left features */
    .left-features {
        order: 2;
    }

    /* Right features */
    .right-features {
        order: 3;
    }

    .overdraft-features {
        width: 100%;
        gap: 25px;
    }

    .feature-item {
        width: 100%;
    }

    .feature-text {
        font-size: 14px;
    }

    .overdraft-image {
        width: 220px;
        height: 190px;
    }

    .overdraft-image img {
        max-width: 220px;
    }

    .overdraft-btn {
        width: 150px;
        height: 45px;
        margin-top: 10px;
    }
}


/* =========================================
   SMALL MOBILE
========================================= */

@media (max-width: 480px) {

    .overdraft-section {
        padding: 35px 15px 45px;
    }

    .overdraft-heading h2 {
        font-size: 19px;
    }

    .overdraft-heading p {
        font-size: 12px;
    }

    .feature-icon {
        width: 36px;
        height: 36px;
        flex-basis: 36px;
    }

    .feature-icon i {
        font-size: 17px;
    }

    .feature-text {
        font-size: 13px;
    }

    .overdraft-image {
        width: 190px;
        height: 170px;
    }

    .overdraft-image img {
        max-width: 190px;
    }
}

/* 3rd section */
/* =========================================
   WHY CHOOSE OVERDRAFT
========================================= */

.why-overdraft-section {
    width: 100%;
    background: #ffffff;
    padding: 28px 20px 38px;
    font-family: Arial, Helvetica, sans-serif;
}

.why-overdraft-container {
    max-width: 1200px;
    margin: 0 auto;
}


/* =========================================
   HEADING
========================================= */

.why-overdraft-heading {
    text-align: center;
    margin-bottom: 43px;
}

.why-overdraft-heading h2 {
    margin: 0;

    font-size: 24px;
    line-height: 1.3;
    font-weight: 600;

    color: #333333;
}

.why-overdraft-subtitle {
    margin-top: 4px;

    font-size: 14px;
    line-height: 1.4;

    color: #2875e5;
}

.why-overdraft-heading p {
    max-width: 950px;

    margin: 12px auto 0;

    font-size: 14px;
    line-height: 1.25;

    color: #707070;
}


/* =========================================
   CARD GRID
========================================= */

.why-overdraft-grid {
    display: grid;

    grid-template-columns:
        repeat(6, 1fr);

    column-gap: 30px;
    row-gap: 30px;

    justify-items: stretch;
}


/* First 3 cards */

.why-overdraft-card:nth-child(1) {
    grid-column: span 2;
}

.why-overdraft-card:nth-child(2) {
    grid-column: span 2;
}

.why-overdraft-card:nth-child(3) {
    grid-column: span 2;
}


/* Bottom 2 cards */

.why-overdraft-card:nth-child(4) {
    grid-column: 2 / span 2;
}

.why-overdraft-card:nth-child(5) {
    grid-column: 4 / span 2;
}


/* =========================================
   CARD
========================================= */

.why-overdraft-card {
    min-height: 204px;

    padding: 29px 22px;

    border: 1.5px solid #2875e5;

    border-radius: 15px;

    background: #ffffff;

    box-shadow:
        0 5px 12px rgba(40, 117, 229, 0.12);

    transition:
        transform 0.3s ease,
        box-shadow 0.3s ease;
}

.why-overdraft-card:hover {
    transform: translateY(-3px);

    box-shadow:
        0 8px 20px rgba(40, 117, 229, 0.18);
}


/* =========================================
   ICON
========================================= */

.why-overdraft-icon {
    width: 39px;
    height: 39px;

    display: flex;
    align-items: center;
    justify-content: center;

    background: #e7f0ff;

    border-radius: 4px;

    margin-bottom: 22px;
}

.why-overdraft-icon i {
    font-size: 19px;

    color: #2875e5;

    line-height: 1;
}


/* =========================================
   CARD TITLE
========================================= */

.why-overdraft-card h3 {
    margin: 0 0 7px;

    font-size: 21px;

    line-height: 1.25;

    font-weight: 600;

    color: #363636;
}


/* =========================================
   CARD DESCRIPTION
========================================= */

.why-overdraft-card p {
    margin: 0;

    font-size: 14px;

    line-height: 1.25;

    color: #707070;
}


/* =========================================
   TABLET
========================================= */

@media (max-width: 991px) {

    .why-overdraft-section {
        padding: 35px 20px 50px;
    }

    .why-overdraft-heading h2 {
        font-size: 22px;
    }

    .why-overdraft-heading p {
        font-size: 13px;
    }

    .why-overdraft-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 25px;
    }

    .why-overdraft-card:nth-child(1),
    .why-overdraft-card:nth-child(2),
    .why-overdraft-card:nth-child(3),
    .why-overdraft-card:nth-child(4),
    .why-overdraft-card:nth-child(5) {
        grid-column: auto;
    }

    .why-overdraft-card {
        min-height: 200px;
    }
}


/* =========================================
   MOBILE
========================================= */

@media (max-width: 767px) {

    .why-overdraft-section {
        padding: 35px 15px 45px;
    }

    .why-overdraft-heading {
        margin-bottom: 30px;
    }

    .why-overdraft-heading h2 {
        font-size: 20px;
    }

    .why-overdraft-subtitle {
        font-size: 13px;
    }

    .why-overdraft-heading p {
        font-size: 13px;
        line-height: 1.45;
    }

    .why-overdraft-grid {
        display: grid;

        grid-template-columns: 1fr;

        gap: 20px;
    }

    .why-overdraft-card:nth-child(1),
    .why-overdraft-card:nth-child(2),
    .why-overdraft-card:nth-child(3),
    .why-overdraft-card:nth-child(4),
    .why-overdraft-card:nth-child(5) {
        grid-column: auto;
    }

    .why-overdraft-card {
        min-height: auto;

        padding: 23px 20px;

        border-radius: 13px;
    }

    .why-overdraft-icon {
        margin-bottom: 17px;
    }

    .why-overdraft-card h3 {
        font-size: 19px;
    }

    .why-overdraft-card p {
        font-size: 13px;
    }

    .desktop-break {
        display: none;
    }
}


/* =========================================
   SMALL MOBILE
========================================= */

@media (max-width: 480px) {

    .why-overdraft-heading h2 {
        font-size: 19px;
    }

    .why-overdraft-heading p {
        font-size: 12px;
    }

    .why-overdraft-card h3 {
        font-size: 18px;
    }

    .why-overdraft-card p {
        font-size: 12px;
    }
}

