/* =========================================
   TABLET
========================================= */

@media (max-width: 991px) {

    .loan-benefits-section {
        padding: 35px 20px 60px;
    }

    .loan-benefits-grid {
        grid-template-columns: repeat(2, 1fr);

        gap: 25px;
    }

    .loan-benefit-card {
        min-height: 190px;
    }
}


/* =========================================
   MOBILE
========================================= */

@media (max-width: 767px) {

    .loan-benefits-section {
        padding: 35px 15px 50px;
    }

    .loan-benefits-heading {
        margin-bottom: 30px;
    }

    .loan-benefits-heading h2 {
        font-size: 21px;
    }

    .loan-benefits-heading p {
        font-size: 13px;
    }

    .loan-benefits-grid {
        grid-template-columns: 1fr;

        gap: 20px;
    }

    .loan-benefit-card {
        min-height: auto;

        padding: 23px 20px;

        border-radius: 13px;
    }

    .loan-benefit-icon {
        margin-bottom: 18px;
    }

    .loan-benefit-card h3 {
        font-size: 19px;
    }

    .loan-benefit-card p {
        font-size: 13px;
        line-height: 1.4;
    }
}


/* =========================================
   SMALL MOBILE
========================================= */

@media (max-width: 480px) {

    .loan-benefits-heading h2 {
        font-size: 19px;
    }

    .loan-benefits-heading p {
        font-size: 12px;
    }

    .loan-benefit-card h3 {
        font-size: 18px;
    }

    .loan-benefit-card p {
        font-size: 12px;
    }
}

/* 5th secton */

/* =========================================
   ELIGIBILITY & DOCUMENTS
========================================= */

#home-eligibility {
    width: 100%;
    background: #fff;
    padding: 10px 0 55px;
}

#home-eligibility .container-tab {
    width: 100%;
    max-width: 1140px;
    margin: 0 auto;
}


/* =========================================
   TABS
========================================= */

#home-eligibility .home-tabs {
    width: 80%;
    margin: 0 auto 44px;

    display: grid;
    grid-template-columns: repeat(5, 1fr);

    background: #edf4fc;

    border: 1px solid #2490ff;

    padding: 3px;

    min-height: 64px;
}


#home-eligibility .home-tab {
    border: none;
    outline: none;

    background: transparent;

    color: #303030;

    font-size: 14px;
    font-weight: 400;

    line-height: 1.2;

    padding: 10px 12px;

    cursor: pointer;

    display: flex;
    align-items: center;
    justify-content: center;

    flex-direction: column;

    transition: all 0.25s ease;
}


#home-eligibility .home-tab span {
    display: block;
}


#home-eligibility .home-tab.active {
    background: #2875df;

    color: #fff;

    border-radius: 7px;

    font-weight: 500;
}


#home-eligibility .home-tab:hover:not(.active) {
    color: #2875df;
}


/* =========================================
   TAB CONTENT
========================================= */

#home-eligibility .home-tab-content {
    display: none;
}

#home-eligibility .home-tab-content.active {
    display: block;
}


/* =========================================
   TWO COLUMN LAYOUT
========================================= */

#home-eligibility .home-eligibility-grid {
    display: grid;

    grid-template-columns: 1fr 1fr;

    column-gap: 45px;

    align-items: start;
}


/* =========================================
   SECTION HEADINGS
========================================= */

#home-eligibility .home-eligibility-section h3,
#home-eligibility .home-documents-section h3 {

    margin: 0 0 20px;

    font-size: 18px;

    line-height: 1.2;

    font-weight: 400;

    color: #333;
}


/* =========================================
   LIST RESET
========================================= */

#home-eligibility .home-checklist,
#home-eligibility .home-document-list {

    list-style: none;

    padding: 0;
    margin: 0;

    display: flex;

    flex-direction: column;

    gap: 22px;
}


/* =========================================
   ELIGIBILITY CARD
========================================= */

#home-eligibility .home-checklist-item {

    min-height: 68px;

    box-sizing: border-box;

    padding: 12px 15px;

    display: flex;

    align-items: center;

    gap: 20px;

    background: #fff;

    border: 1.5px solid #2875e5;

    border-radius: 12px;

    box-shadow: 0 5px 12px rgba(40, 117, 229, 0.12);

    color: #333;

    font-size: 15px;

    line-height: 1.35;
}


/* =========================================
   CHECK ICON
========================================= */

#home-eligibility .home-checklist-icon {

    width: 38px;
    height: 38px;

    min-width: 38px;

    background: #e6f0ff;

    border-radius: 4px;

    display: flex;

    align-items: center;

    justify-content: center;
}


#home-eligibility .home-checklist-icon i {

    font-size: 21px;

    color: #2875e5;

    line-height: 1;
}


/* =========================================
   DOCUMENT CARD
========================================= */

#home-eligibility .home-document-item {

    min-height: 68px;

    box-sizing: border-box;

    padding: 12px 15px;

    display: flex;

    align-items: center;

    gap: 20px;

    background: #fff;

    border: 1.5px solid #2875e5;

    border-radius: 12px;

    box-shadow: 0 5px 12px rgba(40, 117, 229, 0.12);

    color: #333;

    font-size: 15px;

    line-height: 1.35;
}


/* =========================================
   DOCUMENT ICON
========================================= */

#home-eligibility .home-document-icon {

    width: 38px;
    height: 38px;

    min-width: 38px;

    background: #e6f0ff;

    border-radius: 4px;

    display: flex;

    align-items: center;

    justify-content: center;
}


#home-eligibility .home-document-icon i {

    font-size: 19px;

    color: #2875e5;

    line-height: 1;
}


/* =========================================
   HOVER
========================================= */

#home-eligibility .home-checklist-item,
#home-eligibility .home-document-item {

    transition: all 0.25s ease;
}


#home-eligibility .home-checklist-item:hover,
#home-eligibility .home-document-item:hover {

    transform: translateY(-2px);

    box-shadow: 0 8px 18px rgba(40, 117, 229, 0.16);
}


/* =========================================
   TABLET
========================================= */

@media (max-width: 991px) {

    #home-eligibility .container-tab {
        padding: 0 20px;
    }

    #home-eligibility .home-tabs {
        width: 100%;
    }

    #home-eligibility .home-eligibility-grid {
        column-gap: 25px;
    }

    #home-eligibility .home-checklist-item,
    #home-eligibility .home-document-item {
        font-size: 14px;
    }

}


/* =========================================
   MOBILE
========================================= */

@media (max-width: 767px) {

    #home-eligibility {
        padding: 10px 0 45px;
    }

    #home-eligibility .container-tab {
        padding: 0 15px;
    }


    /* Tabs become horizontally scrollable */

    #home-eligibility .home-tabs {

        width: 100%;

        display: flex;

        overflow-x: auto;

        margin-bottom: 30px;

        scrollbar-width: none;

        min-height: 58px;
    }

    #home-eligibility .home-tabs::-webkit-scrollbar {
        display: none;
    }


    #home-eligibility .home-tab {

        min-width: 145px;

        flex-shrink: 0;

        font-size: 13px;

        padding: 9px 10px;
    }


    /* One column */

    #home-eligibility .home-eligibility-grid {

        grid-template-columns: 1fr;

        gap: 30px;
    }


    #home-eligibility .home-eligibility-section h3,
    #home-eligibility .home-documents-section h3 {

        font-size: 17px;

        margin-bottom: 15px;
    }


    #home-eligibility .home-checklist,
    #home-eligibility .home-document-list {

        gap: 16px;
    }


    #home-eligibility .home-checklist-item,
    #home-eligibility .home-document-item {

        min-height: 64px;

        padding: 11px 12px;

        gap: 14px;

        font-size: 13px;

        border-radius: 10px;
    }


    #home-eligibility .home-checklist-icon,
    #home-eligibility .home-document-icon {

        width: 36px;

        min-width: 36px;

        height: 36px;
    }

}


/* =========================================
   SMALL MOBILE
========================================= */

@media (max-width: 480px) {

    #home-eligibility .home-tab {
        min-width: 130px;

        font-size: 12px;
    }

    #home-eligibility .home-checklist-item,
    #home-eligibility .home-document-item {

        font-size: 12.5px;

        line-height: 1.35;
    }

}

/* emi */


/* =========================================================
   MAIN SECTION
========================================================= */

.home-loan-emi-section {

    width: 100%;

    background: #edf4fd;

    padding: 45px 25px 60px;

    box-sizing: border-box;

    overflow: hidden;
}


/* =========================================================
   MAIN WRAPPER
========================================================= */

.home-loan-emi-wrapper {

    width: 100%;

    max-width: 1120px;

    margin: 0 auto;

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 70px;

    box-sizing: border-box;
}


/* =========================================================
   LEFT SIDE
========================================================= */

.home-loan-emi-left {

    flex: 1;

    min-width: 0;
}


.home-loan-emi-left h2 {

    margin: 0 0 12px;

    color: #333333;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 34px;

    font-weight: 600;

    line-height: 1.15;

    letter-spacing: -0.5px;
}


.home-loan-emi-left p {

    margin: 0 0 22px;

    color: #707070;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 14px;

    line-height: 1.4;
}


/* =========================================================
   BUTTON
========================================================= */

.home-loan-emi-btn {

    display: inline-flex;

    align-items: center;

    justify-content: center;

    gap: 14px;

    min-width: 215px;

    height: 48px;

    padding: 0 22px;

    background: #2878e5;

    color: #ffffff !important;

    border-radius: 7px;

    text-decoration: none !important;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 14px;

    font-weight: 600;

    box-sizing: border-box;

    transition:
        all .25s ease;
}


.home-loan-emi-btn:hover {

    background: #1d66cc;

    color: #ffffff !important;

    transform: translateY(-1px);

    box-shadow:
        0 5px 14px rgba(40,120,229,.20);
}


.home-loan-emi-btn span {

    font-size: 23px;

    line-height: 1;
}


/* =========================================================
   RIGHT EMI CARD - LARGE
========================================================= */

.home-loan-emi-box {

    flex: 0 0 560px;

    width: 560px;

    min-height: 275px;

    padding: 36px 34px 30px;

    box-sizing: border-box;

    border-radius: 17px;

    background:
        linear-gradient(
            115deg,
            #2878e5 0%,
            #493ddd 48%,
            #b500d9 100%
        );

    color: #ffffff;

    box-shadow:
        0 7px 20px rgba(41,92,171,.13);
}


/* =========================================================
   CARD TITLE
========================================================= */

.emi-box-title {

    margin-bottom: 32px;

    color: #ffffff;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 15px;

    font-weight: 400;
}


/* =========================================================
   MAIN EMI
========================================================= */

.emi-amount {

    margin-bottom: 12px;

    color: #ffffff;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 38px;

    font-weight: 700;

    line-height: 1;
}


.emi-amount span {

    margin-left: 3px;

    font-size: 18px;

    font-weight: 400;
}


/* =========================================================
   LOAN DETAILS
========================================================= */

.emi-info {

    margin-bottom: 34px;

    color: rgba(255,255,255,.92);

    font-family: Arial, Helvetica, sans-serif;

    font-size: 12px;

    line-height: 1.4;
}


/* =========================================================
   BOTTOM VALUES
========================================================= */

.emi-bottom {

    width: 100%;

    display: grid;

    grid-template-columns:
        repeat(4, 1fr);

    gap: 25px;
}


.emi-value {

    display: flex;

    flex-direction: column;

    min-width: 0;
}


.emi-value strong {

    margin-bottom: 6px;

    color: #ffffff;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 24px;

    font-weight: 700;

    line-height: 1;
}


.emi-value small {

    color: rgba(255,255,255,.90);

    font-family: Arial, Helvetica, sans-serif;

    font-size: 12px;

    line-height: 1.2;
}


/* =========================================================
   LARGE DESKTOP
========================================================= */

@media (min-width: 1200px) {

    .home-loan-emi-wrapper {

        max-width: 1120px;

        gap: 75px;
    }


    .home-loan-emi-box {

        flex-basis: 580px;

        width: 580px;

        min-height: 285px;

        padding:
            38px
            36px
            32px;
    }


    .home-loan-emi-left h2 {

        font-size: 35px;
    }

}


/* =========================================================
   DESKTOP 992 - 1199
========================================================= */

@media (min-width: 992px) and (max-width: 1199px) {

    .home-loan-emi-wrapper {

        max-width: 1000px;

        gap: 45px;
    }


    .home-loan-emi-box {

        flex-basis: 520px;

        width: 520px;

        min-height: 265px;

        padding:
            32px
            30px
            28px;
    }


    .home-loan-emi-left h2 {

        font-size: 31px;
    }


    .emi-amount {

        font-size: 35px;
    }

}


/* =========================================================
   TABLET
========================================================= */

@media (min-width: 768px) and (max-width: 991px) {

    .home-loan-emi-section {

        padding:
            40px
            25px
            55px;
    }


    .home-loan-emi-wrapper {

        gap: 30px;

        max-width: 900px;
    }


    .home-loan-emi-left h2 {

        font-size: 28px;
    }


