/* =========================================================
   MAIN SECTION
========================================================= */

.property-benefits-section {

    width: 100%;

    background: #f8fafc;

    padding: 25px 15px 70px;

    overflow: hidden;

    box-sizing: border-box;
}


/* =========================================================
   CONTAINER
========================================================= */

.property-benefits-container {

    width: 100%;

    max-width: 1250px;

    margin: 0 auto;
}


/* =========================================================
   HEADING
========================================================= */

.property-benefits-heading {

    text-align: center;

    margin-bottom: 48px;
}


.property-benefits-heading h2 {

    margin: 0 0 5px;

    color: #333333;

    font-size: 26px;

    line-height: 1.3;

    font-weight: 600;
}


.property-benefits-heading p {

    margin: 0;

    color: #707070;

    font-size: 15px;

    line-height: 1.4;

    font-weight: 400;
}


/* =========================================================
   GRID
========================================================= */

.property-benefits-grid {

    display: grid;

    grid-template-columns: repeat(3, 1fr);

    column-gap: 32px;

    row-gap: 50px;

    width: 100%;
}


/* =========================================================
   CARD
========================================================= */

.property-benefit-card {

    width: 100%;

    min-height: 220px;

    box-sizing: border-box;

    padding: 32px 24px 25px;

    background: #ffffff;

    border: 1px solid #4d7ff0;

    border-radius: 16px;

    box-shadow: 0 7px 20px rgba(40, 117, 223, 0.10);

    transition: all 0.3s ease;
}


/* =========================================================
   ICON BOX
========================================================= */

.property-benefit-icon {

    width: 42px;

    height: 42px;

    display: flex;

    align-items: center;

    justify-content: center;

    background: #e5efff;

    border-radius: 5px;

    margin-bottom: 26px;
}


.property-benefit-icon i {

    color: #2875df;

    font-size: 19px;

    line-height: 1;
}


/* =========================================================
   CARD TITLE
========================================================= */

.property-benefit-card h3 {

    margin: 0 0 8px;

    color: #3b3b3b;

    font-size: 22px;

    line-height: 1.25;

    font-weight: 600;
}


/* =========================================================
   CARD TEXT
========================================================= */

.property-benefit-card p {

    margin: 0;

    color: #555555;

    font-size: 15px;

    line-height: 1.25;

    font-weight: 400;
}


/* =========================================================
   HOVER
========================================================= */

.property-benefit-card:hover {

    transform: translateY(-3px);

    box-shadow: 0 12px 28px rgba(40, 117, 223, 0.16);
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 991px) {

    .property-benefits-section {

        padding: 30px 20px 55px;
    }

    .property-benefits-grid {

        grid-template-columns: repeat(2, 1fr);

        gap: 25px;
    }

    .property-benefit-card {

        min-height: 220px;
    }

    .property-benefit-card h3 {

        font-size: 20px;
    }

}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 767px) {

    .property-benefits-section {

        padding: 28px 15px 45px;
    }


    /* HEADING */

    .property-benefits-heading {

        margin-bottom: 30px;
    }


    .property-benefits-heading h2 {

        font-size: 22px;

        line-height: 1.3;
    }


    .property-benefits-heading p {

        font-size: 14px;
    }


    /* ONE CARD PER ROW */

    .property-benefits-grid {

        display: flex;

        flex-direction: column;

        gap: 20px;
    }


    /* CARD */

    .property-benefit-card {

        width: 100%;

        min-height: auto;

        padding: 25px 20px;

        border-radius: 14px;
    }


    /* ICON */

    .property-benefit-icon {

        width: 42px;

        height: 42px;

        margin-bottom: 22px;
    }


    /* TITLE */

    .property-benefit-card h3 {

        font-size: 20px;

        line-height: 1.3;

        margin-bottom: 8px;
    }


    /* TEXT */

    .property-benefit-card p {

        font-size: 14px;

        line-height: 1.45;
    }

}


/* =========================================================
   SMALL MOBILE
========================================================= */

@media (max-width: 480px) {

    .property-benefits-section {

        padding: 25px 12px 40px;
    }


    .property-benefits-heading h2 {

        font-size: 20px;
    }


    .property-benefits-heading p {

        font-size: 13px;
    }


    .property-benefit-card {

        padding: 23px 18px;

        border-radius: 13px;
    }


    .property-benefit-icon {

        width: 40px;

        height: 40px;

        margin-bottom: 20px;
    }


    .property-benefit-icon i {

        font-size: 18px;
    }


    .property-benefit-card h3 {

        font-size: 19px;
    }


    .property-benefit-card p {

        font-size: 13.5px;

        line-height: 1.45;
    }

}





/* =========================================================
   MAIN SECTION
========================================================= */

.property-eligibility-section {
    width: 100%;
    padding: 30px 15px 70px;
    background: #f8fafc;
    box-sizing: border-box;
    overflow: hidden;
}

.property-eligibility-container {
    width: 100%;
    max-width: 1250px;
    margin: 0 auto;
}


/* =========================================================
   TABS
========================================================= */

.property-eligibility-tabs {

    width: 100%;

    display: grid;

    grid-template-columns:
        1fr
        1fr
        1.25fr
        1.25fr
        1.2fr;

    gap: 0;

    padding: 4px;

    background: #eaf2fc;

    border-radius: 10px;

    box-sizing: border-box;

    margin-bottom: 48px;
}


/* TAB */

.property-eligibility-tab {

    border: 0;

    background: transparent;

    color: #333;

    min-height: 64px;

    padding: 8px 12px;

    border-radius: 8px;

    font-size: 15px;

    line-height: 1.15;

    font-weight: 500;

    cursor: pointer;

    transition: all 0.25s ease;

    font-family: inherit;
}


/* ACTIVE TAB */

.property-eligibility-tab.active {

    background: #2875df;

    color: #ffffff;

    box-shadow: 0 3px 8px rgba(40,117,223,0.20);
}


/* HOVER */

.property-eligibility-tab:not(.active):hover {

    background: rgba(40,117,223,0.08);

    color: #2875df;
}


/* =========================================================
   TAB CONTENT
========================================================= */

.property-eligibility-tab-content {

    display: none;

    width: 100%;
}

.property-eligibility-tab-content.active {

    display: block;
}


/* =========================================================
   TWO COLUMNS
========================================================= */

.property-eligibility-grid {

    display: grid;

    grid-template-columns: 1fr 1fr;

    gap: 48px;

    align-items: start;
}


/* =========================================================
   COLUMN TITLE
========================================================= */

.property-column-title {

    margin: 0 0 20px;

    color: #333333;

    font-size: 20px;

    line-height: 1.3;

    font-weight: 500;
}


/* =========================================================
   CRITERIA LIST
========================================================= */

.property-criteria-list {

    display: flex;

    flex-direction: column;

    gap: 24px;
}


/* =========================================================
   CRITERIA CARD
========================================================= */

.property-criteria-card {

    width: 100%;

    min-height: 74px;

    display: flex;

    align-items: center;

    gap: 20px;

    padding: 14px 16px;

    box-sizing: border-box;

    background: #ffffff;

    border: 1px solid #4d7ff0;

    border-radius: 14px;

    box-shadow:
        0 6px 18px rgba(40,117,223,0.10);

}


/* =========================================================
   CHECK ICON
========================================================= */

.property-card-icon {

    width: 42px;

    height: 42px;

    min-width: 42px;

    display: flex;

    align-items: center;

    justify-content: center;

    background: #e5efff;

    border-radius: 5px;

    color: #2875df;
}

.property-card-icon i {

    font-size: 21px;

    color: #2875df;
}


/* =========================================================
   CARD TEXT
========================================================= */

.property-card-text {

    color: #3d3d3d;

    font-size: 16px;

    line-height: 1.25;

    font-weight: 400;
}


/* =========================================================
   DOCUMENT LIST
========================================================= */

.property-document-list {

    display: flex;

    flex-direction: column;

    gap: 24px;
}


/* =========================================================
   DOCUMENT CARD
========================================================= */

.property-document-card {

    width: 100%;

    min-height: 74px;

    display: flex;

    align-items: center;

    gap: 24px;

    padding: 14px 24px;

    box-sizing: border-box;

    background: #ffffff;

    border: 1px solid #4d7ff0;

    border-radius: 14px;

    box-shadow:
        0 6px 18px rgba(40,117,223,0.10);

    color: #3d3d3d;

    font-size: 16px;

    line-height: 1.25;

    font-weight: 400;
}


/* =========================================================
   DOCUMENT ICON
========================================================= */

.property-document-icon {

    width: 42px;

    height: 42px;

    min-width: 42px;

    display: flex;

    align-items: center;

    justify-content: center;

    background: #e5efff;

    border-radius: 5px;
}

.property-document-icon i {

    color: #2875df;

    font-size: 19px;
}


/* =========================================================
   CARD HOVER
========================================================= */

.property-criteria-card,
.property-document-card {

    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease;
}

.property-criteria-card:hover,
.property-document-card:hover {

    transform: translateY(-2px);

    box-shadow:
        0 10px 24px rgba(40,117,223,0.15);
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 991px) {

    .property-eligibility-section {

        padding: 25px 20px 55px;
    }


    .property-eligibility-tabs {

        grid-template-columns: repeat(3, 1fr);

        row-gap: 4px;

        margin-bottom: 35px;
    }


    .property-eligibility-grid {

        grid-template-columns: 1fr;

        gap: 35px;
    }


    .property-eligibility-tab {

        font-size: 14px;

        min-height: 58px;
    }

}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 767px) {

    .property-eligibility-section {

        padding: 22px 12px 45px !important;
    }


    .property-eligibility-container {

        width: 100% !important;
    }


    /* =====================================================
       TABS
    ===================================================== */

    .property-eligibility-tabs {

        display: flex !important;

        width: 100% !important;

        overflow-x: auto !important;

        overflow-y: hidden !important;

        gap: 5px !important;

        padding: 4px !important;

        margin-bottom: 30px !important;

        border-radius: 9px !important;

        scrollbar-width: none;
    }

    .property-eligibility-tabs::-webkit-scrollbar {
        display: none;
    }


    .property-eligibility-tab {

        flex: 0 0 145px !important;

        width: 145px !important;

        min-width: 145px !important;

        min-height: 58px !important;

        padding: 7px 8px !important;

        font-size: 13px !important;

        line-height: 1.15 !important;

        border-radius: 7px !important;

        white-space: normal !important;
    }


    /* =====================================================
       CONTENT
    ===================================================== */

    .property-eligibility-grid {

        display: flex !important;

        flex-direction: column !important;

        gap: 30px !important;

        width: 100% !important;
    }


    .property-eligibility-column {

        width: 100% !important;
    }


    /* =====================================================
       TITLES
    ===================================================== */

    .property-column-title {

        margin-bottom: 15px !important;

        font-size: 18px !important;

        line-height: 1.3 !important;
    }


    /* =====================================================
       CARDS
    ===================================================== */

    .property-criteria-list,
    .property-document-list {

        gap: 14px !important;
    }


    .property-criteria-card,
    .property-document-card {

        width: 100% !important;

        min-height: 64px !important;

        padding: 12px !important;

        gap: 12px !important;

        border-radius: 11px !important;
    }


    /* =====================================================
       ICON
    ===================================================== */

    .property-card-icon,
    .property-document-icon {

        width: 40px !important;

        height: 40px !important;

        min-width: 40px !important;
    }


    .property-card-icon i {

        font-size: 19px !important;
    }


    .property-document-icon i {

        font-size: 17px !important;
    }


    /* =====================================================
       TEXT
    ===================================================== */

    .property-card-text,
    .property-document-card {

        font-size: 14px !important;

        line-height: 1.35 !important;
    }

}


/* =========================================================
   SMALL MOBILE
========================================================= */

@media (max-width: 480px) {

