/* =========================================================
   PROPERTY OVERVIEW SECTION
========================================================= */

.property-overview-section {
    width: 100%;
    background: #f8fafc;
    padding: 35px 20px 55px;
    overflow: hidden;
}


/* MAIN CONTAINER */

.property-overview-container {
    width: 100%;
    max-width: 1100px;
    margin: 0 auto;
}


/* =========================================================
   HEADING
========================================================= */

.property-overview-heading {
    text-align: center;
    margin-bottom: 45px;
}

.property-overview-label {
    color: #2875df;
    font-size: 15px;
    font-weight: 500;
    margin-bottom: 8px;
}

.property-overview-heading h2 {
    margin: 0 0 8px;
    color: #333333;
    font-size: 24px;
    line-height: 1.3;
    font-weight: 600;
}

.property-overview-heading p {
    margin: 0;
    color: #727272;
    font-size: 15px;
    line-height: 1.4;
    font-weight: 400;
}


/* =========================================================
   MAIN 3 COLUMN AREA
========================================================= */

.property-overview-content {
    display: grid;
    grid-template-columns: 1fr 340px 1fr;
    align-items: center;
    column-gap: 25px;
}


/* =========================================================
   FEATURES
========================================================= */

.property-features {
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    height: 350px;
}

.property-features-left {
    align-items: flex-start;
}

.property-features-right {
    align-items: flex-start;
}


/* FEATURE */

.property-feature {
    display: flex;
    align-items: center;
    gap: 12px;
    min-height: 65px;
}


/* =========================================================
   ICON BOX
========================================================= */

.property-feature-icon {
    width: 41px;
    height: 41px;
    min-width: 41px;

    display: flex;
    align-items: center;
    justify-content: center;

    background: #e5efff;
    border-radius: 6px;

    color: #2875df;

    font-size: 19px;
}


/* ICON */

.property-feature-icon i {
    color: #2875df;
}


/* =========================================================
   FEATURE TEXT
========================================================= */

.property-feature-text {
    color: #252525;
    font-size: 14px;
    line-height: 1.3;
    font-weight: 500;
}


/* =========================================================
   CENTER IMAGE
========================================================= */

.property-overview-center {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
}


/* IMAGE WRAPPER */

.property-image-wrapper {
    width: 330px;
    height: 250px;

    display: flex;
    align-items: center;
    justify-content: center;
}


/* IMAGE */

.property-main-image {
    width: 100%;
    max-width: 330px;
    height: auto;
    object-fit: contain;
    display: block;
}


/* =========================================================
   APPLY BUTTON
========================================================= */

.property-apply-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;

    width: 168px;
    height: 50px;

    background: #2875df;
    color: #ffffff;

    border-radius: 8px;

    text-decoration: none;

    font-size: 15px;
    font-weight: 600;

    margin-top: 5px;

    transition: all 0.3s ease;
}

.property-apply-btn:hover {
    background: #1f64c5;
    color: #ffffff;
    transform: translateY(-2px);
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 991px) {

    .property-overview-section {
        padding: 35px 20px 50px;
    }

    .property-overview-content {
        grid-template-columns: 1fr 280px 1fr;
        column-gap: 12px;
    }

    .property-image-wrapper {
        width: 280px;
        height: 220px;
    }

    .property-main-image {
        max-width: 280px;
    }

    .property-feature-text {
        font-size: 13px;
    }

    .property-feature-icon {
        width: 38px;
        height: 38px;
        min-width: 38px;
        font-size: 17px;
    }

}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 767px) {

    .property-overview-section {
        padding: 35px 15px 45px;
    }

    .property-overview-heading {
        margin-bottom: 25px;
    }

    .property-overview-label {
        font-size: 14px;
    }

    .property-overview-heading h2 {
        font-size: 22px;
    }

    .property-overview-heading p {
        font-size: 14px;
        line-height: 1.5;
    }

    .desktop-break {
        display: none;
    }


    /* STACK EVERYTHING */

    .property-overview-content {
        display: flex;
        flex-direction: column;
        gap: 10px;
    }


    /* CENTER IMAGE FIRST */

    .property-overview-center {
        order: 1;
        width: 100%;
    }


    .property-features-left {
        order: 2;
    }

    .property-features-right {
        order: 3;
    }


    /* FEATURES */

    .property-features {
        width: 100%;
        height: auto;
        gap: 15px;
    }


    .property-feature {
        width: 100%;
        min-height: auto;
        gap: 12px;
    }


    .property-feature-text {
        font-size: 14px;
    }


    /* IMAGE */

    .property-image-wrapper {
        width: 100%;
        max-width: 320px;
        height: 220px;
    }

    .property-main-image {
        width: 100%;
        max-width: 320px;
    }


    /* BUTTON */

    .property-apply-btn {
        margin-bottom: 15px;
    }

}


/* =========================================================
   SMALL MOBILE
========================================================= */

@media (max-width: 480px) {

    .property-overview-heading h2 {
        font-size: 20px;
    }

    .property-overview-heading p {
        font-size: 13px;
    }

    .property-image-wrapper {
        max-width: 290px;
        height: 200px;
    }

    .property-main-image {
        max-width: 290px;
    }

}



