/* 3nd section css */
/* 3rd section */
/* =========================================
   WHY CHOOSE OVERDRAFT
========================================= */

/* =========================================
   CARD GRID
========================================= */

.why-overdraft-grid {
    display: grid;

    grid-template-columns: repeat(6, minmax(0, 1fr));

    column-gap: 30px;
    row-gap: 30px;

    width: 100%;
}


/* =========================================
   FIRST ROW - 3 EQUAL CARDS
========================================= */

.why-overdraft-card:nth-child(1) {
    grid-column: 1 / span 2;
}

.why-overdraft-card:nth-child(2) {
    grid-column: 3 / span 2;
}

.why-overdraft-card:nth-child(3) {
    grid-column: 5 / span 2;
}


/* =========================================
   SECOND ROW - 3 EQUAL CARDS
========================================= */

.why-overdraft-card:nth-child(4) {
    grid-column: 1 / span 2;
}

.why-overdraft-card:nth-child(5) {
    grid-column: 3 / span 2;
}

.why-overdraft-card:nth-child(6) {
    grid-column: 5 / span 2;
}


/* =========================================
   CARD
========================================= */

.why-overdraft-card {
    width: 100%;
    min-width: 0;
    min-height: 260px;

    padding: 36px 28px;

    box-sizing: border-box;

    border: 1px solid #2f80ff;
    border-radius: 18px;

    background: #ffffff;

    display: flex;
    flex-direction: column;
    align-items: flex-start;
}
/* =====================================================
   FINAL FIX - LRD 6 BENEFIT CARDS
===================================================== */

.why-overdraft-grid {
    width: 100% !important;
    max-width: 1200px !important;
    margin: 0 auto !important;

    display: grid !important;

    grid-template-columns: repeat(3, minmax(0, 1fr)) !important;

    gap: 30px !important;

    box-sizing: border-box !important;
}


/* ALL 6 CARDS SAME WIDTH */

.why-overdraft-card,
.why-overdraft-card:nth-child(1),
.why-overdraft-card:nth-child(2),
.why-overdraft-card:nth-child(3),
.why-overdraft-card:nth-child(4),
.why-overdraft-card:nth-child(5),
.why-overdraft-card:nth-child(6) {

    grid-column: auto !important;

    width: 100% !important;
    min-width: 0 !important;

    min-height: 204px !important;

    box-sizing: border-box !important;
}


/* =====================================================
   TABLET
===================================================== */

@media (max-width: 991px) {

    .why-overdraft-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
        gap: 25px !important;
    }

    .why-overdraft-card,
    .why-overdraft-card:nth-child(1),
    .why-overdraft-card:nth-child(2),
    .why-overdraft-card:nth-child(3),
    .why-overdraft-card:nth-child(4),
    .why-overdraft-card:nth-child(5),
    .why-overdraft-card:nth-child(6) {

        grid-column: auto !important;
        width: 100% !important;
    }
}


/* =====================================================
   MOBILE
===================================================== */

@media (max-width: 767px) {

    .why-overdraft-grid {
        display: grid !important;
        grid-template-columns: 1fr !important;
        gap: 20px !important;
    }

    .why-overdraft-card,
    .why-overdraft-card:nth-child(1),
    .why-overdraft-card:nth-child(2),
    .why-overdraft-card:nth-child(3),
    .why-overdraft-card:nth-child(4),
    .why-overdraft-card:nth-child(5),
    .why-overdraft-card:nth-child(6) {

        grid-column: auto !important;

        width: 100% !important;

        min-height: auto !important;
    }
}

.why-overdraft-section {
    width: 100%;
    background: #ffffff;
    padding: 28px 20px 38px;
    font-family: Arial, Helvetica, sans-serif;
}

.why-overdraft-container {
    max-width: 1200px;
    margin: 0 auto;
}


/* =========================================
   HEADING
========================================= */

.why-overdraft-heading {
    text-align: center;
    margin-bottom: 43px;
}

.why-overdraft-heading h2 {
    margin: 0;

    font-size: 24px;
    line-height: 1.3;
    font-weight: 600;

    color: #333333;
}

.why-overdraft-subtitle {
    margin-top: 4px;

    font-size: 14px;
    line-height: 1.4;

    color: #2875e5;
}

.why-overdraft-heading p {
    max-width: 950px;

    margin: 12px auto 0;

    font-size: 14px;
    line-height: 1.25;

    color: #707070;
}


/* =========================================
   CARD GRID
========================================= */

.why-overdraft-grid {
    display: grid;

    grid-template-columns:
        repeat(6, 1fr);

    column-gap: 30px;
    row-gap: 30px;

    justify-items: stretch;
}


/* First 3 cards */

.why-overdraft-card:nth-child(1) {
    grid-column: span 2;
}

.why-overdraft-card:nth-child(2) {
    grid-column: span 2;
}

.why-overdraft-card:nth-child(3) {
    grid-column: span 2;
}


/* Bottom 2 cards */

.why-overdraft-card:nth-child(4) {
    grid-column: 2 / span 2;
}

.why-overdraft-card:nth-child(5) {
    grid-column: 4 / span 2;
}


/* =========================================
   CARD
========================================= */

.why-overdraft-card {
    min-height: 204px;

    padding: 29px 22px;

    border: 1.5px solid #2875e5;

    border-radius: 15px;

    background: #ffffff;

    box-shadow:
        0 5px 12px rgba(40, 117, 229, 0.12);

    transition:
        transform 0.3s ease,
        box-shadow 0.3s ease;
}

.why-overdraft-card:hover {
    transform: translateY(-3px);

    box-shadow:
        0 8px 20px rgba(40, 117, 229, 0.18);
}


/* =========================================
   ICON
========================================= */

.why-overdraft-icon {
    width: 39px;
    height: 39px;

    display: flex;
    align-items: center;
    justify-content: center;

    background: #e7f0ff;

    border-radius: 4px;

    margin-bottom: 22px;
}

.why-overdraft-icon i {
    font-size: 19px;

    color: #2875e5;

    line-height: 1;
}


