========================================= */

@media (max-width: 991px) {

    .why-overdraft-section {
        padding: 35px 20px 50px;
    }

    .why-overdraft-heading h2 {
        font-size: 22px;
    }

    .why-overdraft-heading p {
        font-size: 13px;
    }

    .why-overdraft-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 25px;
    }

    .why-overdraft-card:nth-child(1),
    .why-overdraft-card:nth-child(2),
    .why-overdraft-card:nth-child(3),
    .why-overdraft-card:nth-child(4),
    .why-overdraft-card:nth-child(5) {
