/* our feature section */



/* =========================================================
   MAIN SECTION
========================================================= */

.home-loan-features {
    width: 100%;

    background: #ffffff;

    padding: 75px 20px 80px;

    overflow: hidden;
}


/* =========================================================
   CONTAINER
========================================================= */

.home-loan-features-container {
    width: 100%;

    max-width: 1200px;

    margin: 0 auto;
}


/* =========================================================
   HEADER
========================================================= */

.home-loan-features-header {
    width: 100%;

    text-align: center;

    margin: 0 auto 45px;
}


/* SMALL TITLE */

.home-loan-eyebrow {
    margin-bottom: 8px;

    color: #2878e5;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 16px;

    font-weight: 500;

    line-height: 1.4;
}


/* MAIN TITLE */

.home-loan-features-header h2 {
    margin: 0 0 24px;

    color: #333333;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 32px;

    font-weight: 600;

    line-height: 1.25;
}


/* BLUE DREAM */

.home-loan-features-header h2 span {
    color: #00a9e8;

    font-weight: 700;
}


/* DESCRIPTION */

.home-loan-features-header p {
    max-width: 1100px;

    margin: 0 auto;

    color: #666666;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 15px;

    font-weight: 400;

    line-height: 1.55;

    text-align: center;
}


/* =========================================================
   FEATURES WRAPPER
========================================================= */

.home-loan-features-wrapper {
    width: 100%;

    display: grid;

    grid-template-columns: 1fr 330px 1fr;

    column-gap: 40px;

    align-items: center;
}


/* =========================================================
   FEATURE COLUMNS
========================================================= */

.home-loan-feature-column {
    width: 100%;

    display: flex;

    flex-direction: column;

    justify-content: space-between;

    gap: 65px;
}


/* =========================================================
   FEATURE ITEM
========================================================= */

.home-loan-feature-item {
    width: 100%;

    display: flex;

    align-items: center;

    gap: 12px;
}


/* =========================================================
   ICON BOX
========================================================= */

.home-loan-feature-icon {
    flex: 0 0 36px;

    width: 36px;

    height: 36px;

    display: flex;

    align-items: center;

    justify-content: center;

    background: #eaf3ff;

    border-radius: 7px;

    color: #2878e5;

    font-size: 17px;
}


/* =========================================================
   FEATURE TEXT
========================================================= */

.home-loan-feature-text {
    flex: 1;

    min-width: 0;
}


.home-loan-feature-text h4 {
    margin: 0;

    color: #222222;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 14px;

    font-weight: 400;

    line-height: 1.3;
}


/* =========================================================
   CENTER
========================================================= */

.home-loan-center {
    width: 100%;

    display: flex;

    flex-direction: column;

    align-items: center;

    justify-content: center;
}


/* =========================================================
   HOUSE IMAGE
========================================================= */

.home-loan-house {
    width: 100%;

    display: flex;

    align-items: center;

    justify-content: center;

    margin-bottom: 30px;
}


.home-loan-house img {
    display: block;

    width: 100%;

    max-width: 340px;

    height: auto;

    object-fit: contain;
}


/* =========================================================
   APPLY BUTTON
========================================================= */

.home-loan-feature-btn {
    display: inline-flex;

    align-items: center;

    justify-content: center;

    width: 157px;

    height: 46px;

    background: #2878e5;

    color: #ffffff !important;

    border-radius: 6px;

    text-decoration: none !important;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 14px;

    font-weight: 600;

    transition: all 0.3s ease;
}


.home-loan-feature-btn:hover {
    background: #1265d2;

    color: #ffffff !important;

    transform: translateY(-2px);

    box-shadow: 0 5px 15px rgba(40, 120, 229, 0.25);
}


/* =========================================================
   LARGE DESKTOP
========================================================= */

@media (min-width: 1400px) {

    .home-loan-features {
        padding-top: 80px;

        padding-bottom: 90px;
    }


    .home-loan-features-container {
        max-width: 1250px;
    }


    .home-loan-features-header h2 {
        font-size: 34px;
    }


    .home-loan-features-header p {
        font-size: 15px;

        max-width: 1120px;
    }


    .home-loan-features-wrapper {
        grid-template-columns: 1fr 350px 1fr;

        column-gap: 45px;
    }

}


/* =========================================================
   LAPTOP
========================================================= */

