/* =========================================================
   MAIN SECTION
========================================================= */

.jfin-home-benefits-section {

    width: 100%;

    background: #ffffff;

    padding: 30px 24px 60px;

    overflow: hidden;
}


/* =========================================================
   MAIN CONTAINER
========================================================= */

.jfin-home-benefits-container {

    width: 100%;

    max-width: 1200px;

    margin: 0 auto;
}


/* =========================================================
   HEADER
========================================================= */

.jfin-home-benefits-header {

    width: 100%;

    text-align: center;

    margin-bottom: 42px;
}


/* =========================================================
   HEADING
========================================================= */

.jfin-home-benefits-header h2 {

    margin: 0 0 7px;

    color: #295cab;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 25px;

    font-weight: 600;

    line-height: 1.25;
}


/* CYAN PART */

.jfin-home-benefits-header h2 strong {

    color: #00abeb;

    font-weight: 700;
}


/* =========================================================
   SUBTEXT
========================================================= */

.jfin-home-benefits-header p {

    margin: 0;

    color: #666666;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 13px;

    font-weight: 400;

    line-height: 1.4;
}


/* =========================================================
   CARD GRID
========================================================= */

.jfin-home-benefits-grid {

    width: 100%;

    display: grid;

    grid-template-columns: repeat(3, 1fr);

    column-gap: 30px;

    row-gap: 30px;
}


/* =========================================================
   CARD
========================================================= */

.jfin-benefit-card {

    width: 100%;

    min-height: 205px;

    padding: 29px 22px 24px;

    background: #ffffff;

    border: 1px solid #286fff;

    border-radius: 15px;

    box-sizing: border-box;

    box-shadow:
        0 5px 15px rgba(41, 92, 171, 0.04);

    transition: all 0.25s ease;
}


/* =========================================================
   CARD HOVER
========================================================= */

.jfin-benefit-card:hover {

    transform: translateY(-3px);

    box-shadow:
        0 9px 22px rgba(41, 92, 171, 0.10);
}


/* =========================================================
   ICON BOX
========================================================= */

.jfin-benefit-icon {

    width: 39px;

    height: 39px;

    margin-bottom: 22px;

    display: flex;

    align-items: center;

    justify-content: center;

    background: #e6f0ff;

    border-radius: 4px;

    color: #2878e5;

    font-size: 18px;
}


/* =========================================================
   CARD TITLE
========================================================= */

.jfin-benefit-card h3 {

    margin: 0 0 7px;

    color: #363636;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 21px;

    font-weight: 600;

    line-height: 1.25;
}


/* =========================================================
   CARD DESCRIPTION
========================================================= */

.jfin-benefit-card p {

    margin: 0;

    color: #666666;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 14px;

    font-weight: 400;

    line-height: 1.3;
}


