.jfin-eligibility-section {

    width: 100%;

    background: #ffffff;

    padding: 35px 25px 75px;

    box-sizing: border-box;

    overflow: hidden;
}


/* =========================================================
   CONTAINER
========================================================= */

.jfin-eligibility-container {

    width: 100%;

    max-width: 1200px;

    margin: 0 auto;
}


/* =========================================================
   HEADER
========================================================= */

.jfin-eligibility-header {

    text-align: center;

    margin-bottom: 28px;
}


.jfin-eligibility-header h2 {

    margin: 0 0 5px;

    color: #295cab;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 25px;

    font-weight: 600;

    line-height: 1.3;
}


.jfin-eligibility-header h2 strong {

    color: #00abeb;

    font-weight: 700;
}


.jfin-eligibility-header p {

    margin: 0;

    color: #666666;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 13px;

    line-height: 1.5;
}


/* =========================================================
   TABS OUTER
========================================================= */

.jfin-eligibility-tabs {

    width: 525px;

    max-width: 100%;

    margin: 0 auto 46px;

    padding: 4px;

    display: grid;

    grid-template-columns: repeat(3, 1fr);

    background: #eaf2fc;

    border-radius: 8px;

    box-sizing: border-box;
}


/* =========================================================
   TAB BUTTON
========================================================= */

.jfin-eligibility-tab {

    min-height: 40px;

    padding: 9px 12px;

    border: none;

    outline: none;

    background: transparent;

    border-radius: 7px;

    color: #333333;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 13px;

    font-weight: 500;

    cursor: pointer;

    transition: all 0.25s ease;
}


/* ACTIVE TAB */

.jfin-eligibility-tab.active {

    background: #2878e5;

    color: #ffffff;

    box-shadow:
        0 2px 5px rgba(40, 120, 229, 0.15);
}


/* =========================================================
   TAB CONTENT
========================================================= */

.jfin-eligibility-tab-content {

    display: none;

    animation: jfinEligibilityFade 0.25s ease;
}


.jfin-eligibility-tab-content.active {

    display: block;
}


@keyframes jfinEligibilityFade {

    from {
        opacity: 0;
        transform: translateY(5px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }

}


/* =========================================================
   MAIN TWO COLUMN GRID
========================================================= */

.jfin-eligibility-grid {

    width: 100%;

    display: grid;

    grid-template-columns: 1fr 1fr;

    gap: 45px;

    align-items: start;
}


/* =========================================================
   COLUMN TITLE
========================================================= */

.jfin-column-title {

    margin: 0 0 20px;

    color: #333333;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 18px;

    font-weight: 500;

    line-height: 1.3;
}


/* =========================================================
   CHECKLIST
========================================================= */

.jfin-checklist {

    width: 100%;

    display: flex;

    flex-direction: column;

    gap: 22px;
}


/* =========================================================
   CHECK ITEM
========================================================= */

.jfin-check-item {

    width: 100%;

    min-height: 69px;

    padding: 13px 16px;

    display: flex;

    align-items: center;

    gap: 23px;

    background: #ffffff;

    border: 1px solid #477cff;

    border-radius: 11px;

    box-sizing: border-box;

    color: #333333;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 15px;

    line-height: 1.4;

    box-shadow:
        0 4px 12px rgba(41, 92, 171, 0.04);
}


/* =========================================================
   CHECK ICON BOX
========================================================= */

.jfin-check-icon {

    flex: 0 0 38px;

    width: 38px;

    height: 38px;

    display: flex;

    align-items: center;

    justify-content: center;

    background: #e8f1ff;

    border-radius: 4px;

    color: #2878e5;

    font-size: 19px;
}


/* =========================================================
   DOCUMENT COLUMN
========================================================= */

.jfin-documents-column {

    width: 100%;
}


/* =========================================================
   DOCUMENT ACCORDION
========================================================= */

.jfin-document-accordion {

    width: 100%;

    display: flex;

    flex-direction: column;

    gap: 22px;
}


/* =========================================================
   DETAILS
========================================================= */

.jfin-document-accordion details {

    width: 100%;

    background: #ffffff;

    border: 1px solid #477cff;

    border-radius: 11px;

    overflow: hidden;

    box-sizing: border-box;

    box-shadow:
        0 4px 12px rgba(41, 92, 171, 0.04);
}


/* =========================================================
   SUMMARY
========================================================= */

.jfin-document-accordion summary {

    min-height: 67px;

    padding: 18px 21px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 15px;

    color: #333333;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 15px;

    font-weight: 600;

    line-height: 1.35;

    cursor: pointer;

    list-style: none;

    box-sizing: border-box;
}


/* REMOVE DEFAULT MARKER */

.jfin-document-accordion summary::-webkit-details-marker {

    display: none;
}


/* =========================================================
   CHEVRON
========================================================= */

.jfin-document-accordion summary i {

    flex-shrink: 0;

    color: #444444;

    font-size: 11px;

    transition: transform 0.25s ease;
}


/* ROTATE WHEN OPEN */

.jfin-document-accordion details[open] summary i {

    transform: rotate(180deg);
}


/* =========================================================
   DOCUMENT CONTENT
========================================================= */

.jfin-document-content {

    padding:
        0
        21px
        18px;
}


/* =========================================================
   DOCUMENT LIST
========================================================= */

.jfin-document-content ul {

    margin: 0;

    padding-left: 20px;
}


.jfin-document-content li {

    margin-bottom: 13px;

    padding-left: 1px;

    color: #555555;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 14px;

    line-height: 1.45;
}


.jfin-document-content li:last-child {

    margin-bottom: 0;
}


/* =========================================================
   TABLET
========================================================= */

@media (min-width: 768px) and (max-width: 991px) {

    .jfin-eligibility-section {

        padding:
            35px
            20px
            60px;
    }


    .jfin-eligibility-grid {

        gap: 25px;
    }


    .jfin-eligibility-tabs {

        margin-bottom: 38px;
    }


    .jfin-column-title {

        font-size: 17px;
    }


    .jfin-check-item {

        font-size: 13px;

        gap: 15px;

        padding-left: 12px;

        padding-right: 12px;
    }


    .jfin-check-icon {

        flex-basis: 36px;

        width: 36px;

        height: 36px;

        font-size: 17px;
    }


    .jfin-document-accordion summary {

        font-size: 13px;

        padding-left: 16px;

        padding-right: 16px;
    }


    .jfin-document-content {

        padding-left: 16px;

        padding-right: 16px;
    }


    .jfin-document-content li {

        font-size: 12px;
    }

}


