/* =========================================================
   DARK OVERLAY
========================================================= */

.home-loan-overlay {
    position: absolute;
    inset: 0;

    background: linear-gradient(
        90deg,
        rgba(0, 0, 0, 0.65) 0%,
        rgba(0, 0, 0, 0.45) 30%,
        rgba(0, 0, 0, 0.08) 65%,
        rgba(0, 0, 0, 0) 100%
