    }


    .home-loan-btn {

        height: 29px;

        min-width: 72px;

        font-size: 8px;
    }
}

/* emi-calculator */


/* =========================================================
   MAIN SECTION
========================================================= */

.home-loan-emi-section {

    width: 100%;

    background: #edf4fd;

    padding: 45px 25px 60px;

    box-sizing: border-box;

    overflow: hidden;
}


/* =========================================================
   MAIN WRAPPER
========================================================= */

.home-loan-emi-wrapper {

    width: 100%;

    max-width: 1120px;

    margin: 0 auto;

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 70px;

    box-sizing: border-box;
}


/* =========================================================
   LEFT SIDE
========================================================= */

.home-loan-emi-left {

    flex: 1;

    min-width: 0;
}


.home-loan-emi-left h2 {

    margin: 0 0 12px;

    color: #333333;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 34px;

    font-weight: 600;

    line-height: 1.15;

    letter-spacing: -0.5px;
}


.home-loan-emi-left p {

    margin: 0 0 22px;

    color: #707070;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 14px;

    line-height: 1.4;
}


/* =========================================================
   BUTTON
========================================================= */

.home-loan-emi-btn {

    display: inline-flex;

    align-items: center;

    justify-content: center;

    gap: 14px;

    min-width: 215px;

    height: 48px;

    padding: 0 22px;

    background: #2878e5;

    color: #ffffff !important;

    border-radius: 7px;

    text-decoration: none !important;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 14px;

    font-weight: 600;

    box-sizing: border-box;

    transition:
        all .25s ease;
}


.home-loan-emi-btn:hover {

    background: #1d66cc;

    color: #ffffff !important;

    transform: translateY(-1px);

    box-shadow:
        0 5px 14px rgba(40,120,229,.20);
}


.home-loan-emi-btn span {

    font-size: 23px;

    line-height: 1;
}


/* =========================================================
   RIGHT EMI CARD - LARGE
========================================================= */

.home-loan-emi-box {

    flex: 0 0 560px;

    width: 560px;

    min-height: 275px;

    padding: 36px 34px 30px;

    box-sizing: border-box;

    border-radius: 17px;

    background:
        linear-gradient(
            115deg,
            #2878e5 0%,
            #493ddd 48%,
            #b500d9 100%
        );

    color: #ffffff;

    box-shadow:
        0 7px 20px rgba(41,92,171,.13);
}


/* =========================================================
   CARD TITLE
========================================================= */

.emi-box-title {

    margin-bottom: 32px;

    color: #ffffff;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 15px;

    font-weight: 400;
}


/* =========================================================
   MAIN EMI
========================================================= */

.emi-amount {

    margin-bottom: 12px;

    color: #ffffff;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 38px;

    font-weight: 700;

    line-height: 1;
}


.emi-amount span {

    margin-left: 3px;

    font-size: 18px;

    font-weight: 400;
}


/* =========================================================
   LOAN DETAILS
========================================================= */

.emi-info {

    margin-bottom: 34px;

    color: rgba(255,255,255,.92);

    font-family: Arial, Helvetica, sans-serif;

    font-size: 12px;

    line-height: 1.4;
}


/* =========================================================
   BOTTOM VALUES
========================================================= */

.emi-bottom {

    width: 100%;

    display: grid;

    grid-template-columns:
        repeat(4, 1fr);

    gap: 25px;
}


.emi-value {

    display: flex;

    flex-direction: column;

    min-width: 0;
}


.emi-value strong {

    margin-bottom: 6px;

    color: #ffffff;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 24px;

    font-weight: 700;

    line-height: 1;
}


.emi-value small {

    color: rgba(255,255,255,.90);

    font-family: Arial, Helvetica, sans-serif;

    font-size: 12px;

    line-height: 1.2;
}


/* =========================================================
   LARGE DESKTOP
========================================================= */

@media (min-width: 1200px) {

    .home-loan-emi-wrapper {

        max-width: 1120px;

        gap: 75px;
    }


    .home-loan-emi-box {

        flex-basis: 580px;

        width: 580px;

        min-height: 285px;

        padding:
            38px
            36px
            32px;
    }


    .home-loan-emi-left h2 {

        font-size: 35px;
    }

}


/* =========================================================
   DESKTOP 992 - 1199
========================================================= */

@media (min-width: 992px) and (max-width: 1199px) {

    .home-loan-emi-wrapper {

        max-width: 1000px;

        gap: 45px;
    }


    .home-loan-emi-box {

        flex-basis: 520px;

        width: 520px;

        min-height: 265px;

        padding:
            32px
            30px
            28px;
    }


    .home-loan-emi-left h2 {

        font-size: 31px;
    }


    .emi-amount {

        font-size: 35px;
    }

}


/* =========================================================
   TABLET
========================================================= */

@media (min-width: 768px) and (max-width: 991px) {

    .home-loan-emi-section {

        padding:
            40px
            25px
            55px;
    }


    .home-loan-emi-wrapper {

        gap: 30px;

        max-width: 900px;
    }


    .home-loan-emi-left h2 {

        font-size: 28px;
    }


    .home-loan-emi-left p {

        font-size: 13px;
    }


    .home-loan-emi-box {

        flex-basis: 450px;

        width: 450px;

        min-height: 250px;

        padding:
            29px
            25px
            26px;
    }


    .emi-box-title {

        font-size: 13px;

        margin-bottom: 27px;
    }


    .emi-amount {

        font-size: 30px;
    }


    .emi-amount span {

        font-size: 15px;
    }


    .emi-info {

        font-size: 10px;

        margin-bottom: 28px;
    }


    .emi-bottom {

        gap: 12px;
    }


    .emi-value strong {

        font-size: 19px;
    }


    .emi-value small {

        font-size: 10px;
    }

}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 767px) {

    .home-loan-emi-section {

        padding:
            38px
            15px
            48px;
    }


    .home-loan-emi-wrapper {

        flex-direction: column;

        align-items: stretch;

        gap: 30px;
    }


    .home-loan-emi-left {

        width: 100%;

        text-align: center;
    }


    .home-loan-emi-left h2 {

        font-size: 27px;

