    .home-loan-emi-box {

        width: 100%;

        min-width: 0;

        flex: none;

        min-height: 260px;

        padding:
            29px
            23px
            27px;

        border-radius: 15px;
    }


    .emi-box-title {

        font-size: 13px;

        margin-bottom: 27px;
    }


    .emi-amount {

        font-size: 30px;
    }


    .emi-amount span {

        font-size: 15px;
    }


    .emi-info {

        font-size: 10px;

        margin-bottom: 29px;
    }


    .emi-bottom {

        gap: 10px;
    }


    .emi-value strong {

        font-size: 18px;
    }


    .emi-value small {

        font-size: 10px;
    }

}


/* =========================================================
   IPHONE 376 - 575
========================================================= */

@media (min-width: 376px) and (max-width: 575px) {

    .home-loan-emi-section {

