/* property details */
  
   /* =========================================================
   JFINSERV PROPERTIES PAGE
   COMPLETE NEW UI
   DATA / BLADE / LINKS NOT CHANGED
========================================================= */


/* =========================================================
   GLOBAL
========================================================= */

main {
    background: #f7faff;
}

main .container {
    max-width: 1380px;
}


/* =========================================================
   HERO
========================================================= */

.video-hero {
    position: relative;
    width: 100%;
    height: 520px;
    overflow: hidden;
    background: #0d2d5c;
}

.video-hero video {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.video-banner-overlay {
    position: absolute;
    inset: 0;

    display: flex;
    align-items: center;

    background:
        linear-gradient(
            90deg,
            rgba(5, 35, 82, .88) 0%,
            rgba(10, 65, 130, .60) 45%,
            rgba(10, 65, 130, .15) 100%
        );
}

.video-overlay-content {
    width: 100%;
    max-width: 1380px;
    margin: auto;
    padding: 0 35px;
}

.video-overlay-content h1 {
    max-width: 720px;

    margin: 0 0 18px;

    color: #ffffff;

    font-size: 48px;
    font-weight: 700;

    line-height: 1.15;
}

.video-overlay-content h1 span {
    color: #00abeb;
}

.video-overlay-content p {
    max-width: 620px;

    margin: 0;

    color: rgba(255,255,255,.90);

    font-size: 18px;
    line-height: 1.6;
}


/* =========================================================
   SEARCH AREA
========================================================= */

.hero-search-wrapper {
    position: relative;

    margin-top: -65px;

    z-index: 20;
}

.hero-search-box {
    position: relative;

    padding: 26px 28px;

    background: rgba(255,255,255,.97);

    border: 1px solid rgba(41,92,171,.12);

    border-radius: 18px;

    box-shadow:
        0 20px 55px rgba(20,57,100,.16);
}

.hero-search-top {
    display: flex;

    gap: 12px;

    margin-bottom: 16px;
}

.hero-search-top input {
    flex: 1;

    height: 50px;

    padding: 0 18px;

    background: #f7faff;

    border: 1px solid #e2e9f2;

    border-radius: 10px;

    color: #27364d;

    font-size: 14px;

    outline: none;

    transition: .3s ease;
}

.hero-search-top input:focus {
    background: #ffffff;

    border-color: #00abeb;

    box-shadow:
        0 0 0 4px rgba(0,171,235,.08);
}

.hero-search-top button {
    height: 50px;

    padding: 0 30px;

    background: linear-gradient(
        135deg,
        #295cab,
        #00abeb
    );

    color: #ffffff;

    border: 0;

    border-radius: 10px;

    font-weight: 600;

    cursor: pointer;

    transition: .3s ease;
}

.hero-search-top button:hover {
    transform: translateY(-2px);

    box-shadow:
        0 8px 20px rgba(41,92,171,.25);
}

.hero-search-filters {
    display: grid;

    grid-template-columns:
        repeat(4, 1fr);

    gap: 12px;
}

.hero-search-filters select,
.hero-search-filters .select2-container {
    width: 100% !important;
}

.hero-search-filters select {
    height: 46px;

    padding: 0 13px;

    background: #ffffff;

    border: 1px solid #e3e9f1;

    border-radius: 9px;

    color: #475569;

    font-size: 13px;

    outline: none;

    cursor: pointer;
}

.hero-search-filters select:focus {
    border-color: #00abeb;
}


/* =========================================================
   SELECT2
========================================================= */

.select2-container--default
.select2-selection--single {
    height: 46px !important;

    border: 1px solid #e3e9f1 !important;

    border-radius: 9px !important;

    background: #ffffff !important;
}

.select2-container--default
.select2-selection--single
.select2-selection__rendered {
    line-height: 44px !important;

    padding-left: 13px !important;

    color: #475569 !important;

    font-size: 13px;
}

.select2-container--default
.select2-selection--single
.select2-selection__arrow {
    height: 44px !important;
}


/* =========================================================
   SECTION HEADERS
========================================================= */

.section-header {
    position: relative;

    margin: 75px auto 38px;

    text-align: center;
}

.section-header::before {
    content: "";

    display: block;

    width: 45px;
    height: 4px;

    margin: 0 auto 14px;

    background: linear-gradient(
        90deg,
        #295cab,
        #00abeb
    );

    border-radius: 10px;
}

.section-header h2 {
    margin: 0 0 10px;

    color: #295cab;

    font-size: 34px;

    font-weight: 700;

    line-height: 1.25;
}

.section-header h2::first-letter {
    color: #295cab;
}

.section-header p {
    max-width: 650px;

    margin: 0 auto;

    color: #7a8798;

    font-size: 14px;

    line-height: 1.6;
}


/* =========================================================
   LOCALITIES SECTION
========================================================= */

.localities-grid {
    display: grid;

    grid-template-columns:
        repeat(3, 1fr);

    gap: 24px;

    margin-bottom: 65px;
}

.locality-card {
    position: relative;

    padding: 24px;

    background:
        linear-gradient(
            145deg,
            #ffffff,
            #f7fbff
        );

    border: 1px solid #e5edf6;

    border-radius: 18px;

    box-shadow:
        0 8px 28px rgba(31,64,104,.07);

    overflow: hidden;

    transition: .35s ease;
}



.localty-title,
.locality-title {
    position: relative;

    margin: 0 0 20px;

    padding-bottom: 14px;

    color: #295cab;

    font-size: 21px;

    font-weight: 700;

    text-align: left;

    border-bottom: 1px solid #e8eef5;
}

.localty-title::after,
.locality-title::after {
    content: "";

    position: absolute;

    left: 0;
    bottom: -1px;

    width: 55px;
    height: 3px;

    background: #00abeb;

    border-radius: 10px;
}


/* =========================================================
   MINI PROPERTY GRID
========================================================= */

.properties-mini-grid {
    display: grid;

    grid-template-columns:
        repeat(2, 1fr);

    gap: 15px;
}

.mini-property {
    position: relative;

    display: flex;

    flex-direction: column;

    gap: 7px;

    padding: 9px;

    background: #ffffff;

    border: 1px solid #edf1f6;

    border-radius: 12px;

    text-decoration: none !important;

    overflow: hidden;

    transition: .3s ease;
}

.mini-property:hover {
    transform: translateY(-4px);

    border-color: #cfe7f6;

    box-shadow:
        0 10px 25px rgba(30,65,100,.10);
}

.mini-property img {
    width: 100%;

    aspect-ratio: 16 / 10;

    object-fit: cover;

    border-radius: 8px;

    transition: .4s ease;
}

.mini-property:hover img {
    transform: scale(1.04);
}

.mini-developer {
    color: #295cab;

    font-size: 11px;

    font-weight: 600;

    overflow: hidden;

    text-overflow: ellipsis;

    white-space: nowrap;
}

.mini-name {
    color: #26364c;

    font-size: 13px;

    font-weight: 600;

    line-height: 1.35;
}

.mini-location {
    display: flex;

    align-items: center;

    gap: 4px;

    color: #8994a3;

    font-size: 10px;

    overflow: hidden;

    text-overflow: ellipsis;

    white-space: nowrap;
}


/* =========================================================
   PROPERTY GRID
========================================================= */

.properties-grid {
    display: grid;

    grid-template-columns:
        repeat(3, minmax(0,1fr));

    gap: 26px;

    margin-bottom: 55px;
}


/* =========================================================
   PROPERTY CARD
========================================================= */

.property-card {
    position: relative;

    background: #ffffff;

    border: 1px solid #e6edf5;

    border-radius: 17px;

    overflow: hidden;

    box-shadow:
        0 8px 28px rgba(25,62,100,.07);

    transition:
        transform .35s ease,
        box-shadow .35s ease,
        border-color .35s ease;
}

.property-card:hover {
    transform: translateY(-8px);

    border-color: rgba(0,171,235,.35);

    box-shadow:
        0 20px 48px rgba(25,62,100,.14);
}


/* =========================================================
   PROPERTY IMAGE
========================================================= */

.property-image-wrapper {
    position: relative;

    height: 255px;

    overflow: hidden;

    background: #edf2f7;
}

.property-image-wrapper img {
    width: 100%;
    height: 100%;

    object-fit: cover;

    transition: transform .55s ease;
}

.property-card:hover
.property-image-wrapper img {
    transform: scale(1.07);
}


/* =========================================================
   PROPERTY STATUS
========================================================= */

.property-badge {
    position: absolute;

    top: 14px;
    left: 14px;

    right: auto;

    display: inline-flex;

    align-items: center;

    gap: 7px;

    padding: 7px 13px;

    background: rgba(255,255,255,.95);

    color: #295cab;

    border: 1px solid rgba(255,255,255,.8);

    border-radius: 20px;

    font-size: 11px;

    font-weight: 700;

    box-shadow:
        0 5px 15px rgba(0,0,0,.12);

    backdrop-filter: blur(8px);

    z-index: 5;
}

.property-badge::before {
    content: "";

    width: 7px;
    height: 7px;

    background: #1dbb70;

    border-radius: 50%;

    box-shadow:
        0 0 0 3px rgba(29,187,112,.12);
}


/* =========================================================
   IMAGE OVERLAY
========================================================= */

.property-overlay {
    position: absolute;

    left: 0;
    right: 0;
    bottom: 0;

    padding: 45px 18px 15px;

    background:
        linear-gradient(
            to top,
            rgba(4,24,48,.82),
            transparent
        );

    opacity: 0;

    transition: .35s ease;
}

.property-card:hover
.property-overlay {
    opacity: 1;
}

.quick-stats {
    display: flex;

    gap: 18px;

    color: #ffffff;

    font-size: 12px;
}

.stat-item {
    display: flex;

    align-items: center;

    gap: 6px;
}

.stat-item i {
    color: #00abeb;
}


/* =========================================================
   PROPERTY DETAILS
========================================================= */

.property-details {
    padding: 20px;
}

.property-title {
    min-height: 48px;

    margin: 0 0 10px;

    color: #253858;

    font-size: 20px;

    font-weight: 700;

    line-height: 1.3;

    display: -webkit-box;

    -webkit-line-clamp: 2;

    -webkit-box-orient: vertical;

    overflow: hidden;
}

.property-developer {
    display: flex;

    align-items: center;

    gap: 7px;

    margin-bottom: 8px;

    color: #687588;

    font-size: 13px;
}

.property-developer i {
    color: #295cab;
}

.property-location {
    display: flex;

    align-items: flex-start;

    gap: 7px;

    min-height: 36px;

    margin-bottom: 16px;

    color: #8994a3;

    font-size: 12px;

    line-height: 1.5;
}

.property-location i {
    color: #00abeb;

    margin-top: 2px;
}


/* =========================================================
   SPECS
========================================================= */

.property-specs {
    display: grid;

    grid-template-columns: 1fr 1fr;

    gap: 0;

    margin-bottom: 17px;

    padding: 13px;

    background: #f7faff;

    border: 1px solid #edf2f7;

    border-radius: 10px;
}

.spec-item {
    display: flex;

    flex-direction: column;

    gap: 4px;
}

.spec-item + .spec-item {
    padding-left: 18px;

    border-left: 1px solid #e2e9f1;
}

.spec-label {
    color: #99a2ae;

    font-size: 9px;

    font-weight: 600;

    text-transform: uppercase;

    letter-spacing: .7px;
}

.spec-value {
    color: #314158;

    font-size: 13px;

    font-weight: 700;
}


/* =========================================================
   PROPERTY FOOTER
========================================================= */

.property-footer {
    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 12px;

    padding-top: 16px;

    border-top: 1px solid #edf1f5;
}

.property-price {
    display: flex;

    flex-direction: column;

    gap: 2px;

    color: #295cab;

    font-size: 16px;

    font-weight: 700;

    line-height: 1.3;
}

.property-price::before {
    content: "Starting Price";

    color: #98a2ae;

    font-size: 9px;

    font-weight: 500;

    text-transform: uppercase;

    letter-spacing: .5px;
}


/* =========================================================
   CONTACT BUTTON
========================================================= */

.contact-btn {
    display: inline-flex;

    align-items: center;

    justify-content: center;

    gap: 8px;

    padding: 10px 16px;

    background: #295cab;

    color: #ffffff !important;

    border: 0;

    border-radius: 7px;

    font-size: 12px;

    font-weight: 600;

    text-decoration: none !important;

    transition: .3s ease;
}

.contact-btn:hover {
    background: #00abeb;

    color: #ffffff !important;

    transform: translateX(3px);
}


/* =========================================================
   HIDDEN EXTRA PROPERTIES
========================================================= */

.extra-property {
    display: none;
}


/* =========================================================
   FEATURES
========================================================= */

.features-grid {
    display: grid;

    grid-template-columns:
        repeat(4, 1fr);

    gap: 20px;

    margin: 65px 0;
}

.feature-card {
    position: relative;

    padding: 28px 22px;

    background: #ffffff;

    border: 1px solid #e7edf5;

    border-radius: 16px;

    text-align: center;

    box-shadow:
        0 8px 25px rgba(30,65,100,.06);

    transition: .35s ease;

    overflow: hidden;
}

.feature-card::before {
    content: "";

    position: absolute;

    top: 0;
    left: 0;

    width: 100%;
    height: 3px;

    background:
        linear-gradient(
            90deg,
            #295cab,
            #00abeb
        );
}

.feature-card:hover {
    transform: translateY(-7px);

    box-shadow:
        0 18px 40px rgba(30,65,100,.12);
}

.feature-icon {
    width: 62px;
    height: 62px;

    margin: 0 auto 17px;

    display: flex;

    align-items: center;

    justify-content: center;

    background:
        linear-gradient(
            135deg,
            #e7f1ff,
            #e8faff
        );

    color: #295cab;

    border-radius: 15px;

    font-size: 26px;
}

.feature-card h3 {
    margin: 0 0 9px;

    color: #253858;

    font-size: 18px;

    font-weight: 700;
}

.feature-card p {
    margin: 0;

    color: #788493;

    font-size: 13px;

    line-height: 1.65;
}


/* =========================================================
   SERVICES
========================================================= */

.services-grid {
    display: grid;

    grid-template-columns:
        repeat(3, 1fr);

    gap: 25px;

    margin: 65px 0;
}

.service-card {
    background: #ffffff;

    border: 1px solid #e6edf5;

    border-radius: 17px;

    overflow: hidden;

    box-shadow:
        0 8px 28px rgba(25,62,100,.07);

    transition: .35s ease;
}

.service-card:hover {
    transform: translateY(-7px);

    box-shadow:
        0 18px 42px rgba(25,62,100,.13);
}

.service-image {
    width: 100%;

    height: 215px;

    object-fit: cover;
}

.service-content {
    padding: 21px;
}

.service-content h3 {
    margin: 0 0 9px;

    color: #295cab;

    font-size: 20px;

    font-weight: 700;
}

.service-content p {
    margin: 0;

    color: #788493;

    font-size: 13px;

    line-height: 1.7;
}


/* =========================================================
   TESTIMONIALS
========================================================= */

.testimonials {
    margin: 70px 0;

    padding: 50px 35px;

    background:
        linear-gradient(
            135deg,
            #f4f9ff,
            #ffffff
        );

    border: 1px solid #e5edf6;

    border-radius: 22px;

    box-shadow:
        0 10px 35px rgba(25,62,100,.06);
}

.testimonial-grid {
    display: grid;

    grid-template-columns:
        repeat(3, 1fr);

    gap: 22px;

    margin-top: 35px;
}

.testimonial-card {
    position: relative;

    padding: 25px;

    background: #ffffff;

    border: 1px solid #e8eef5;

    border-radius: 15px;

    box-shadow:
        0 6px 22px rgba(30,65,100,.05);

    border-left: 4px solid #295cab;
}

.testimonial-stars {
    margin-bottom: 12px;

    color: #f5b942;

    font-size: 16px;
}

.testimonial-card p {
    margin: 0;

    color: #687588;

    font-size: 13px;

    line-height: 1.7;
}

.testimonial-author {
    margin-top: 17px;

    color: #253858;

    font-size: 14px;

    font-weight: 700;
}

.testimonial-role {
    color: #929dab;

    font-size: 11px;
}


/* =========================================================
   VIEW ALL / LOAD MORE
========================================================= */

#loadMoreBtn,
#loadMoreFeatured {
    padding: 12px 25px;

    background: #295cab;

    color: #ffffff;

    border: 0;

    border-radius: 7px;

    font-size: 13px;

    font-weight: 600;

    cursor: pointer;

    transition: .3s ease;
}

#loadMoreBtn:hover,
#loadMoreFeatured:hover {
    background: #00abeb;

    transform: translateY(-2px);
}


/* =========================================================
   APPLY BUTTON
========================================================= */

.apply-btn {
    background: #295cab;

    color: #ffffff;

    border: 0;

    border-radius: 7px;

    transition: .3s ease;
}

.apply-btn:hover {
    background: #00abeb;
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 1100px) {

    .properties-grid {
        grid-template-columns:
            repeat(2, 1fr);
    }

    .localities-grid {
        grid-template-columns:
            repeat(2, 1fr);
    }

    .features-grid {
        grid-template-columns:
            repeat(2, 1fr);
    }

    .services-grid {
        grid-template-columns:
            repeat(2, 1fr);
    }

    .testimonial-grid {
        grid-template-columns:
            repeat(2, 1fr);
    }

    .hero-search-filters {
        grid-template-columns:
            repeat(2, 1fr);
    }
}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 768px) {

    .video-hero {
        height: 390px !important;
        min-height: 390px !important;
    }

    .video-overlay-content {
        padding: 0 20px !important;
    }

    .video-overlay-content h1 {
        max-width: 330px;

        font-size: 34px !important;
    }

    .video-overlay-content p {
        max-width: 320px;

        font-size: 14px !important;
    }


    /* SEARCH */

    .hero-search-wrapper {
        margin-top: -30px !important;

        padding: 0 15px;

        box-sizing: border-box;
    }

    .hero-search-box {
        padding: 17px;

        border-radius: 14px;
    }

    .hero-search-top {
        flex-direction: column;

        gap: 10px;
    }

    .hero-search-top input,
    .hero-search-top button {
        width: 100%;

        height: 44px;
    }

    .hero-search-filters {
        grid-template-columns: 1fr;

        gap: 9px;
    }


    /* HEADERS */

    .section-header {
        margin: 50px 0 27px;
    }

    .section-header h2 {
        font-size: 27px !important;
    }

    .section-header p {
        padding: 0 10px;

        font-size: 13px !important;
    }


    /* LOCALITIES */

    .localities-grid {
        grid-template-columns: 1fr;

        gap: 18px;
    }

    .locality-card {
        padding: 18px;
    }

    .properties-mini-grid {
        grid-template-columns:
            repeat(2, 1fr);

        gap: 10px;
    }


    /* PROPERTIES */

    .properties-grid {
        grid-template-columns: 1fr;

        gap: 20px;
    }

    .property-card:hover {
        transform: none;
    }

    .property-image-wrapper {
        height: 230px;
    }

    .property-overlay {
        opacity: 1;
    }

    .property-details {
        padding: 18px;
    }

    .property-title {
        font-size: 19px;
    }

    .property-specs {
        grid-template-columns: 1fr 1fr;
    }


    /* FEATURES */

    .features-grid {
        grid-template-columns:
            repeat(2, 1fr);

        gap: 14px;

        margin: 40px 0;
    }

    .feature-card {
        padding: 21px 15px;
    }

    .feature-card h3 {
        font-size: 16px;
    }

    .feature-card p {
        font-size: 12px;
    }


    /* SERVICES */

    .services-grid {
        grid-template-columns: 1fr;

        gap: 18px;

        margin: 40px 0;
    }


    /* TESTIMONIAL */

    .testimonials {
        margin: 45px 0;

        padding: 28px 15px;
    }

    .testimonial-grid {
        grid-template-columns: 1fr;

        gap: 15px;
    }

}


/* =========================================================
   SMALL MOBILE
========================================================= */

@media (max-width: 480px) {

    .video-hero {
        height: 320px !important;

        min-height: 320px !important;
    }

    .video-overlay-content h1 {
        max-width: 280px;

        font-size: 27px !important;
    }

    .video-overlay-content p {
        max-width: 270px;

        font-size: 12px !important;
    }


    .hero-search-wrapper {
        padding-left: 12px;

        padding-right: 12px;
    }

    .hero-search-box {
        padding: 14px;
    }


    .section-header h2 {
        font-size: 24px !important;
    }


    .locality-card {
        padding: 14px;
    }


    .properties-mini-grid {
        gap: 8px;
    }


    .property-image-wrapper {
        height: 210px;
    }


    .property-details {
        padding: 15px;
    }


    .property-title {
        font-size: 18px;
    }


    .property-developer,
    .property-location {
        font-size: 12px;
    }


    .property-price {
        font-size: 18px;
    }


    .contact-btn {
        padding: 9px 13px;

        font-size: 11px;
    }


    .features-grid {
        grid-template-columns: 1fr;
    }


    .feature-card {
        padding: 20px;
    }


    .service-image {
        height: 185px;
    }


    .service-content {
        padding: 18px;
    }

}


/* =========================================================
   EXTRA SMALL
========================================================= */

@media (max-width: 360px) {

    .video-hero {
        height: 290px !important;

        min-height: 290px !important;
    }

    .video-overlay-content h1 {
        max-width: 240px;

        font-size: 23px !important;
    }

    .video-overlay-content p {
        max-width: 230px;

        font-size: 11px !important;
    }


    .properties-mini-grid {
        grid-template-columns: 1fr;
    }


    .mini-property {
        display: grid;

        grid-template-columns: 90px 1fr;

        column-gap: 10px;

        align-items: center;
    }


    .mini-property img {
        width: 90px;

        height: 65px;

        grid-row: span 3;
    }


    .property-image-wrapper {
        height: 190px;
    }


    .property-title {
        font-size: 17px;
    }


    .property-price {
        font-size: 17px;
    }

}

/* =========================================================
   PROPERTIES SEARCH - MOBILE UI FIX ONLY
   Desktop / backend unchanged
   ========================================================= */

@media screen and (max-width: 767px) {

    /* SEARCH WRAPPER */
    .hero-search-wrapper {
        width: 100% !important;

        margin-top: -20px !important;

        padding-left: 12px !important;
        padding-right: 12px !important;

        box-sizing: border-box !important;
    }


    /* SEARCH BOX */
    .hero-search-box {
        width: 100% !important;

        padding: 14px !important;

        box-sizing: border-box !important;

        border-radius: 14px !important;

        overflow: visible !important;
    }


    /* SEARCH INPUT + BUTTON */
    .hero-search-top {
        display: flex !important;

        flex-direction: column !important;

        width: 100% !important;

        gap: 9px !important;

        margin-bottom: 12px !important;
    }


    .hero-search-top input {
        width: 100% !important;

        height: 46px !important;

        min-height: 46px !important;

        padding: 0 14px !important;

        box-sizing: border-box !important;

        border-radius: 9px !important;
    }


    .hero-search-top button {
        width: 100% !important;

        height: 44px !important;

        min-height: 44px !important;

        padding: 0 20px !important;

        box-sizing: border-box !important;

        border-radius: 9px !important;
    }


    /* FILTERS */
    .hero-search-filters {
        display: grid !important;

        grid-template-columns: repeat(2, minmax(0, 1fr)) !important;

        width: 100% !important;

        gap: 9px !important;

        box-sizing: border-box !important;
    }


    /* NORMAL SELECT */
    .hero-search-filters select {
        width: 100% !important;

        min-width: 0 !important;

        height: 44px !important;

        box-sizing: border-box !important;

        padding: 0 10px !important;

        border-radius: 8px !important;
    }


    /* SELECT2 */
    .hero-search-filters .select2-container {
        width: 100% !important;

        min-width: 0 !important;

        max-width: 100% !important;

        box-sizing: border-box !important;
    }


    .hero-search-filters
    .select2-selection--single {
        width: 100% !important;

        height: 44px !important;

        box-sizing: border-box !important;

        border-radius: 8px !important;
    }


    .hero-search-filters
    .select2-selection__rendered {
        line-height: 42px !important;

        padding-left: 10px !important;

        padding-right: 25px !important;

        white-space: nowrap !important;

        overflow: hidden !important;

        text-overflow: ellipsis !important;
    }


    .hero-search-filters
    .select2-selection__arrow {
        height: 42px !important;
    }
}


/* =========================================================
   SMALL MOBILE
   ========================================================= */

@media screen and (max-width: 480px) {

    .hero-search-wrapper {
        margin-top: -15px !important;

        padding-left: 10px !important;
        padding-right: 10px !important;
    }


    .hero-search-box {
        padding: 12px !important;

        border-radius: 12px !important;
    }


    .hero-search-top {
        gap: 8px !important;

        margin-bottom: 10px !important;
    }


    .hero-search-top input {
        height: 44px !important;
    }


    .hero-search-top button {
        height: 42px !important;
    }


    .hero-search-filters {
        grid-template-columns: 1fr 1fr !important;

        gap: 8px !important;
    }


    .hero-search-filters select,
    .hero-search-filters
    .select2-selection--single {
        height: 42px !important;
    }


    .hero-search-filters
    .select2-selection__rendered {
        line-height: 40px !important;

        padding-left: 9px !important;

        font-size: 12px !important;
    }


    .hero-search-filters
    .select2-selection__arrow {
        height: 40px !important;
    }
}


/* =========================================================
   VERY SMALL MOBILE
   ========================================================= */

@media screen and (max-width: 360px) {

    .hero-search-wrapper {
        padding-left: 8px !important;
        padding-right: 8px !important;
    }


    .hero-search-box {
        padding: 10px !important;
    }


    .hero-search-filters {
        gap: 7px !important;
    }


    .hero-search-filters
    .select2-selection__rendered {
        font-size: 11px !important;

        padding-left: 7px !important;
    }
}



    :root {
        --primary-color: #4c5fd7;
        --secondary-color: #295cab;
        --text-dark: #1a1a2e;
        --text-muted: #6b7280;
        --bg-light: #f8f9fc;
        --white: #ffffff;
        --shadow: 0 10px 30px rgba(0,0,0,0.05);
        --border-color: #e2e8f0;
    }

    /* Brochure Modal Styles */
#enquiryModal .modal-content-prop {
    background: #ffffff;
    width: 500px;
    padding: 0;
    border-radius: 20px;
    overflow: hidden;
    color: #1a1a2e;
    box-shadow: 0 25px 60px rgba(0,0,0,0.3);
    animation: slideUp 0.4s ease;
}

@keyframes slideUp {
    from {
        transform: translateY(30px);
        opacity: 0;
    }
    to {
        transform: translateY(0);
        opacity: 1;
    }
}

#enquiryModal .modal-header-prop {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    padding: 28px 30px 20px;
    background: linear-gradient(135deg, #4c5fd7 0%, #295cab 100%);
    color: #ffffff;
}

#enquiryModal .modal-header-title h2 {
    font-size: 24px;
    font-weight: 700;
    margin: 0 0 4px 0;
    color: #ffffff;
}

#enquiryModal .modal-header-title p {
    font-size: 14px;
    color: rgba(255,255,255,0.8);
    margin: 0;
}

#enquiryModal .modal-close-prop {
    margin-top: -4px;
}

#enquiryModal .close-btn {
    background: rgba(255,255,255,0.15);
    border: none;
    color: #ffffff;
    font-size: 18px;
    cursor: pointer;
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.3s;
}

#enquiryModal .close-btn:hover {
    background: rgba(255,255,255,0.3);
    transform: rotate(90deg);
}

#enquiryModal .modal-body {
    padding: 24px 30px 30px;
}

#enquiryModal .form-group {
    margin-bottom: 16px;
}

#enquiryModal .form-group label {
    display: block;
    font-size: 13px;
    font-weight: 600;
    color: #2c3e80;
    margin-bottom: 5px;
}

#enquiryModal .form-group .required {
    color: #ef4444;
}

#enquiryModal .brochure-input {
    width: 100%;
    padding: 12px 16px;
    border: 2px solid #e5e7eb;
    border-radius: 10px;
    font-size: 14px;
    transition: all 0.3s ease;
    background-color: #f9fafb;
    color: #1a1a2e;
    outline: none;
    box-sizing: border-box;
}

#enquiryModal .brochure-input:focus {
    border-color: #4c5fd7;
    background-color: #ffffff;
    box-shadow: 0 0 0 4px rgba(76, 95, 215, 0.1);
}

#enquiryModal .brochure-input::placeholder {
    color: #9ca3af;
}

#enquiryModal .brochure-info-box {
    display: flex;
    gap: 12px;
    margin: 18px 0 20px;
    padding: 12px 0;
    border-top: 1px solid #f1f3f9;
    border-bottom: 1px solid #f1f3f9;
}

#enquiryModal .brochure-info-item {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 13px;
    color: #4b5563;
}

#enquiryModal .brochure-info-item i {
    color: #4c5fd7;
    font-size: 16px;
}

#enquiryModal .brochure-submit-btn {
    width: 100%;
    padding: 14px 24px;
    background: linear-gradient(135deg, #4c5fd7 0%, #295cab 100%);
    color: #ffffff;
    border: none;
    border-radius: 12px;
    font-size: 16px;
    font-weight: 700;
    cursor: pointer;
    transition: all 0.3s ease;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

#enquiryModal .brochure-submit-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 25px rgba(76, 95, 215, 0.4);
}

#enquiryModal .brochure-submit-btn:active {
    transform: translateY(0);
}

#enquiryModal .brochure-submit-btn i {
    font-size: 18px;
}

/* Modal Backdrop */
.modal-backdrop {
    display: none;
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.6);
    backdrop-filter: blur(4px);
    z-index: 999;
    animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

/* Modal Container */
.modal {
    position: fixed;
    inset: 0;
    z-index: 1000;
    display: flex;
    align-items: center;
    justify-content: center;
    visibility: hidden;
}

#enquiryModal.modal.active {
    visibility: visible;
}

/* Responsive */
@media (max-width: 540px) {
    #enquiryModal .modal-content-prop {
        width: 92%;
        margin: 0 10px;
        border-radius: 16px;
    }
    
    #enquiryModal .modal-header-prop {
        padding: 20px 20px 16px;
    }
    
    #enquiryModal .modal-header-title h2 {
        font-size: 20px;
    }
    
    #enquiryModal .modal-body {
        padding: 20px;
    }
    
    #enquiryModal .brochure-info-box {
        flex-direction: column;
        gap: 6px;
    }
}

    * { box-sizing: border-box; }

    .custom-container {
        max-width: 1440px;
        margin: 8px auto;
        padding: 0 20px;
    }

    .main-wrapper {
        padding: 4rem 0;
        background: var(--bg-light);
    }

    .custom-row {
        display: flex;
        flex-wrap: wrap;
        margin: 0 -15px;
    }

    .content-main {
        flex: 0 0 66.666667%;
        max-width: 66.666667%;
        padding: 0 15px;
    }

    .content-sidebar {
        flex: 0 0 33.333333%;
        max-width: 33.333333%;
        padding: 0 15px;
    }

    @media (max-width: 992px) {
        .content-main, .content-sidebar {
            flex: 0 0 100%;
            max-width: 100%;
        }
        .content-sidebar { margin-top: 2rem; }
    }

    .property-hero {
        background: var(--white);
        padding: 2rem 0;
        margin-bottom: 2rem;
        box-shadow: var(--shadow);
    }

    .breadcrumb-nav {
        margin-bottom: 1.5rem;
        font-size: 0.9rem;
    }

    .breadcrumb-nav a {
        color: var(--primary-color);
        text-decoration: none;
    }

    .property-header {
        display: flex;
        justify-content: space-between;
        align-items: flex-start;
        margin-bottom: 1.5rem;
        flex-wrap: nowrap;
        gap: 2rem;
    }

    .property-main-info {
        flex: 1;
    }

    .property-main-info h1 {
        font-size: 2.2rem;
        font-weight: 800;
        color: var(--text-dark);
        margin-bottom: 0.25rem;
        display: flex;
        align-items: center;
        gap: 1rem;
    }

    .rera-badge {
        background: #e6fffa;
        color: #2d3748;
        font-size: 0.7rem;
        padding: 2px 8px;
        border-radius: 4px;
        border: 1px solid #cbd5e0;
        display: flex;
        align-items: center;
        gap: 4px;
        font-weight: 600;
    }

    .developer-link {
        color: var(--primary-color);
        text-decoration: none;
        font-weight: 700;
        font-size: 0.9rem;
        text-transform: uppercase;
    }

    .property-location {
        color: var(--text-muted);
        margin-top: 0.5rem;
        font-size: 1rem;
    }

    .property-price-box {
        text-align: right;
        min-width: 250px;
    }

    .price-value {
        font-size: 1.8rem;
        font-weight: 800;
        color: var(--text-dark);
        line-height: 1;
    }

    .emi-info {
        color: var(--primary-color);
        font-weight: 600;
        font-size: 0.9rem;
        margin-top: 4px;
    }

    .agreement-label {
        font-size: 0.8rem;
        color: var(--text-muted);
    }

    .btn-contact-top {
        background: var(--primary-color);
        color: white;
        border: none;
        padding: 0.75rem 1.5rem;
        border-radius: 8px;
        font-weight: 700;
        margin-top: 1rem;
        display: flex;
        align-items: center;
        gap: 0.5rem;
        transition: all 0.3s;
        width: 100%;
        justify-content: center;
        text-decoration: none;
        cursor: pointer;
    }

    /* Grid Gallery Layout */
    .grid-gallery {
        display: grid;
        grid-template-columns: 2fr 1fr;
        gap: 10px;
        margin-bottom: 2rem;
        border-radius: 12px;
        overflow: hidden;
    }
   /* =========================================
   PROPERTY GALLERY
   IMAGE SHOULD NEVER BE CROPPED
   ========================================= */

.gallery-wrapper {
    width: 100%;
    margin-bottom: 2rem;
}

/* Main gallery container */
.gallery-main {
    position: relative;
    width: 100%;
    background: #f7f8fa;
    border-radius: 12px;
    overflow: hidden;

    /* Important:
       Height will automatically follow image */
    height: auto;

    display: flex;
    align-items: center;
    justify-content: center;
}

/* Main image */
.gallery-main img {
    display: block;
    width: 100%;
    height: auto;

    /* IMPORTANT - don't crop */
    object-fit: contain;

    max-width: 100%;
    max-height: none;

    border-radius: 12px;
}

/* Navigation arrows */
.nav-arrow {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);

    width: 45px;
    height: 45px;

    background: rgba(0, 0, 0, 0.55);
    color: #fff;

    border: none;
    border-radius: 50%;

    font-size: 2rem;
    line-height: 1;

    cursor: pointer;
    z-index: 10;

    display: flex;
    align-items: center;
    justify-content: center;

    transition: all 0.3s ease;
}

.nav-arrow:hover {
    background: rgba(0, 0, 0, 0.8);
}

.nav-arrow.left {
    left: 15px;
}

.nav-arrow.right {
    right: 15px;
}


/* =========================================
   THUMBNAILS
   ========================================= */

.thumbnail-bar {
    display: flex;
    gap: 10px;

    margin-top: 12px;

    overflow-x: auto;

    padding-bottom: 5px;

    scrollbar-width: thin;
}

.thumbnail-bar::-webkit-scrollbar {
    height: 6px;
}

.thumbnail-bar::-webkit-scrollbar-thumb {
    background: #ccc;
    border-radius: 4px;
}

/* Thumbnail itself */
.thumbnail {
    width: 120px;
    height: 80px;

    flex: 0 0 120px;

    /* Keep complete image */
    object-fit: contain;

    background: #f7f7f7;

    border-radius: 8px;

    cursor: pointer;

    opacity: 0.6;

    border: 2px solid transparent;

    transition: 0.3s ease;
}

.thumbnail:hover,
.thumbnail.active {
    opacity: 1;
    border-color: #000;
}


/* =========================================
   MOBILE GALLERY
   ========================================= */

@media (max-width: 992px) {

    .gallery-wrapper {
        width: 100%;
    }

    .gallery-main {
        width: 100%;
        height: auto;
        min-height: 0;

        background: #f7f8fa;

        display: flex;
        align-items: center;
        justify-content: center;
    }

    .gallery-main img {
        width: 100%;
        height: auto;

        object-fit: contain;

        max-width: 100%;
        max-height: none;
    }

    .thumbnail {
        width: 100px;
        height: 70px;
        flex: 0 0 100px;
    }

    .nav-arrow {
        width: 38px;
        height: 38px;
        font-size: 1.5rem;
    }

    .nav-arrow.left {
        left: 8px;
    }

    .nav-arrow.right {
        right: 8px;
    }
}


/* =========================================
   SMALL MOBILE
   ========================================= */

@media (max-width: 576px) {

    .gallery-main {
        border-radius: 8px;
    }

    .gallery-main img {
        width: 100%;
