        object-fit: contain;
    }

    .thumbnail-bar {
        gap: 8px;
    }

    .thumbnail {
        width: 85px;
        height: 60px;
        flex: 0 0 85px;
    }

    .nav-arrow {
        width: 34px;
        height: 34px;
        font-size: 1.3rem;
    }
}

    .gallery-side {
