        z-index: 999;
    }
    .form-container {
            position: fixed;
            top:18%;
            right:50%;
            transform: translate(50%, -10%);
            z-index: 1000;
            background: white;
            border-radius: 16px;
            box-shadow: 0 20px 60px rgba(0, 0, 0, 0.2);
            padding: 40px;
            max-width: 530px;
            width: 100%;
            visibility: hidden;
        }
        .form-header{
            display: flex;
            justify-content: space-between;
        }
        .form-header-title {
            text-align: center;
            margin-bottom: 12px;
        }

        .form-header-title h1 {
            color: #2c3e80;
            font-size: 28px;
            margin-bottom: 8px;
        }

        .form-header-title p {
            color: #6b7280;
            font-size: 14px;
        }

        .form-group {
            margin-bottom: 1rem;
        }
        .visit-close{
            position:fixed;
            top:3%;
            right:5%;
            text-align:right;
            background:transparent;
            border:none;
            color:#000;
            font-size:26px;
            cursor:pointer;
        }
        label {
            display: block;
            color: #2c3e80;
            font-weight: 600;
            font-size: 14px;
        }

        input[type="text"],
        input[type="email"],
        input[type="tel"],
        select {
            width: 100%;
            padding: 12px 16px;
            border: 2px solid #e5e7eb;
            border-radius: 8px;
            font-size: 15px;
            /* transition: all 0.3s ease; */
            background-color: #f9fafb;
        }

        input[type="text"]:focus,
        input[type="email"]:focus,
        input[type="tel"]:focus,
        select:focus {
            outline: none;
            border-color: #667eea;
            background-color: white;
            box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.1);
        }

        .radio-group {
            display: grid;
            grid-template-columns: repeat(2,1fr);
            gap: 12px;
        }

        .radio-option {
            display: flex;
            align-items: center;
            padding: 7px 16px;
            border: 2px solid #e5e7eb;
            border-radius: 8px;
            cursor: pointer;
            /* transition: all 0.3s ease; */
            background-color: #f9fafb;
        }

        .radio-option:hover {
            border-color: #667eea;
            background-color: white;
        }

        .radio-option input[type="radio"] {
            width: 10px;
            height: 10px;
            border: 2px solid #d1d5db;
            border-radius: 50%;
            margin-right: 12px;
            cursor: pointer;
            position: relative;
            transition: all 0.3s ease;
            flex-shrink: 0;
        }

        .radio-option input[type="radio"]:checked {
            border-color: #667eea;
            border-width: 6px;
        }

        .radio-option input[type="radio"]:checked ~ .radio-label {
            color: #2c3e80;
            font-weight: 600;
        }

        .radio-option:has(input[type="radio"]:checked) {
            border-color: #667eea;
            background-color: #f0f4ff;
        }

        .radio-label {
            color: #4b5563;
            font-size: 15px;
            cursor: pointer;
            flex-grow: 1;
        }

        .submit-btn {
            width: 100%;
            padding: 14px 24px;
            background: linear-gradient(135deg, #667eea 0%, #5568d3 100%);
            color: white;
            border: none;
            border-radius: 8px;
            font-size: 16px;
            font-weight: 600;
            cursor: pointer;
            /* transition: all 0.3s ease; */
            margin-top: 8px;
        }

        .submit-btn:hover {
            transform: translateY(-2px);
            box-shadow: 0 8px 20px rgba(102, 126, 234, 0.4);
        }

        .submit-btn:active {
            transform: translateY(0);
        }

        .required {
            color: #ef4444;
            margin-left: 2px;
        }

        @media (max-width: 480px) {
            .form-container {
                padding: 28px 20px;
            }

            .form-header h1 {
                font-size: 24px;
            }
        }
        /* =========================================================
   MOBILE BROCHURE MODAL FIX
   Express Interest should stay behind brochure modal
   ========================================================= */

@media screen and (max-width: 767px) {

    /* Express Interest background madhe rahil */
    #mainwrapper .content-sidebar,
    #mainwrapper #enquire.sidebar-card {
        z-index: 1 !important;
    }

    /* Brochure dark background */
    #modalBackdrop {
        position: fixed !important;
        inset: 0 !important;
        z-index: 99998 !important;
    }

    /* Brochure modal always above Express Interest */
    #enquiryModal {
        position: fixed !important;
        inset: 0 !important;
        z-index: 99999 !important;
    }

    #enquiryModal .modal-content-prop {
        position: relative !important;
