/* =====================================
   PROPERTY GALLERY
===================================== */

.gallery-wrapper {
    width: 100%;
    padding: 14px 22px 16px;
    margin: 0;
    box-sizing: border-box;
    background: #fff;
}

/* Main Image */
.gallery-main {
    position: relative;
    width: 100%;
    height: 465px;
    overflow: hidden;
    border-radius: 10px;
    background: #f4f4f4;
}

.gallery-main #mainImage {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
    border-radius: 10px;
}

/* Navigation Arrows */
.gallery-main .nav-arrow {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    z-index: 5;
    width: 36px;
    height: 44px;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0;
    border: none;
    border-radius: 5px;
    background: rgba(0, 0, 0, 0.4);
    color: #fff;
    font-size: 28px;
    line-height: 1;
    cursor: pointer;
    opacity: 0;
    transition: opacity 0.2s ease;
}

.gallery-main:hover .nav-arrow {
    opacity: 1;
}

.gallery-main .nav-arrow.left {
    left: 10px;
}

.gallery-main .nav-arrow.right {
    right: 10px;
}

/* Thumbnail Row */
.thumbnail-bar {
    display: flex;
    align-items: center;
    gap: 5px;
    width: 100%;
    margin-top: 6px;
    padding: 0;
    overflow-x: auto;
    overflow-y: hidden;
    scrollbar-width: none;
    box-sizing: border-box;
}

.thumbnail-bar::-webkit-scrollbar {
    display: none;
}

/* Equal thumbnail sizes */
.thumbnail-bar .thumbnail {
    flex: 0 0 48px;
    width: 48px;
    min-width: 48px;
    height: 36px;
    display: block;
    padding: 0;
    object-fit: cover;
    object-position: center;
    border: 1px solid #e5e5e5;
    border-radius: 4px;
    box-sizing: border-box;
    cursor: pointer;
}

/* Active Thumbnail */
.thumbnail-bar .thumbnail.active {
    border: 2px solid #fff;
    outline: 1px solid #d5dce5;
}

/* =====================================
   TABLET
===================================== */

@media (max-width: 768px) {

    .gallery-wrapper {
        padding: 12px 16px;
    }

    .gallery-main {
        height: 250px;
    }

    .gallery-main .nav-arrow {
        opacity: 1;
    }

    .thumbnail-bar .thumbnail {
        flex: 0 0 58px;
        width: 58px;
        min-width: 58px;
        height: 40px;
    }
}

/* =====================================
   MOBILE
===================================== */

@media (max-width: 480px) {

    .gallery-wrapper {
        padding: 8px 10px 12px;
    }

    .gallery-main {
        height: 220px;
        border-radius: 9px;
    }

    .gallery-main #mainImage {
        border-radius: 9px;
    }

    .gallery-main .nav-arrow {
        width: 30px;
        height: 36px;
        font-size: 24px;
        opacity: 1;
    }

    .thumbnail-bar {
        gap: 5px;
        margin-top: 6px;
    }

    .thumbnail-bar .thumbnail {
        flex: 0 0 58px;
        width: 58px;
        min-width: 58px;
        height: 38px;
    }
}

/* =========================================
   PROPERTY SUMMARY HEADER
========================================= */

.property-summary-card {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 20px;
    width: 100%;
    padding: 21px 20px;
    margin: 0 0 18px;
    background: #fffafd;
    border-left: 3px solid #168cff;
    box-sizing: border-box;
}

/* Left Content */

.property-summary-left {
    flex: 1;
    min-width: 0;
}

.summary-property-title {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 7px;
    margin: 0 0 7px;
    color: #333333;
    font-size: 22px;
    font-weight: 700;
    line-height: 1.4;
}

.summary-property-title > i {
    font-size: 18px;
    color: #454545;
}

.summary-builder {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 14px;
    font-weight: 400;
    color: #777;
    white-space: nowrap;
}

.summary-builder span {
    font-weight: 600;
    color: #555;
}

/* Location */

.summary-property-location {
    display: flex;
    align-items: center;
    gap: 7px;
    margin-bottom: 14px;
    color: #777;
    font-size: 14px;
    line-height: 1.5;
}

.summary-property-location i {
    font-size: 13px;
    color: #666;
}

/* Actions Row */

.summary-actions {
    display: flex;
    align-items: center;
    gap: 156px;
    flex-wrap: wrap;
}

/* Book Visit Button */

.summary-book-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    width: 241px;
    min-height: 39px;
    padding: 8px 14px;
    border: none;
    border-radius: 5px;
    background: #286be5;
    color: #fff;
    font-size: 15px;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.2s ease;
}

.summary-book-btn:hover {
    background: #1857c5;
}

.summary-book-btn i {
    font-size: 10px;
}

/* RERA Badge */

.summary-rera-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    padding: 7px 10px;
    border-radius: 4px;
    background: #eef4ff;
    color: #2872e8;
    font-size: 16px;
    white-space: nowrap;
}

.summary-rera-badge i {
    color: #ff7043;
    font-size: 12px;
}

/* Right Price */

.property-summary-right {
    flex: 0 0 auto;
    text-align: right;
    padding-top: 0;
}

.summary-price {
    color: #454545;
    font-size: 19px;
    font-weight: 750;
    line-height: 1.35;
    white-space: nowrap;
}

.summary-price-star {
    font-size: 13px;
}

.summary-price-caption {
    margin-top: 3px;
    color: #777;
    font-size: 11px;
    white-space: nowrap;
}

/* =========================================
   TABLET
========================================= */

@media (max-width: 768px) {

    .property-summary-card {
        gap: 12px;
        padding: 14px;
    }

    .summary-property-title {
        font-size: 15px;
    }

    .summary-book-btn {
        width: 200px;
    }

    .summary-price {
        font-size: 17px;
    }
}

/* =========================================
   MOBILE
========================================= */

@media (max-width: 480px) {

    .property-summary-card {
        gap: 8px;
        padding: 12px 10px;
        margin-bottom: 14px;
    }

    .property-summary-left {
        flex: 1;
        min-width: 0;
    }

    .summary-property-title {
        gap: 5px;
        font-size: 14px;
    }

    .summary-builder {
        font-size: 7px;
    }

    .summary-property-location {
        align-items: flex-start;
        gap: 5px;
        font-size: 12px;
        margin-bottom: 12px;
    }

    .summary-actions {
        gap: 8px;
    }

    .summary-book-btn {
        width: 100%;
        max-width: 220px;
        min-height: 34px;
    }

    .summary-rera-badge {
        padding: 6px 7px;
        font-size: 9px;
    }

    .property-summary-right {
        max-width: 44%;
    }

    .summary-price {
        font-size: 14px;
    }

    .summary-price-caption {
        font-size: 10px;
    }
}


/* =========================================
   FLOOR PLAN MAIN SECTION
========================================= */

.dynamic-floor-plan {
    width: 100%;
    margin: 24px 0;
    padding: 24px;
    background: #ffffff;
    border: 1px solid #edf0f5;
    border-radius: 8px;
    box-sizing: border-box;
}

.floor-plan-heading {
    margin-bottom: 20px;
}

.floor-plan-heading h2 {
    margin: 0 0 8px;
    color: #163d78;
    font-size: 23px;
    font-weight: 700;
}

.floor-plan-heading p {
    margin: 0;
    color: #6b7280;
    font-size: 14px;
    line-height: 1.6;
}

/* =========================================
   BHK TABS
========================================= */

.floor-plan-tabs {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    margin-bottom: 24px;
}

.floor-plan-tab {
    padding: 10px 22px;
    color: #0645a4;
    background: #ffffff;
    border: 1px solid #cbd8ec;
    border-radius: 5px;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: background .2s ease, color .2s ease;
}

.floor-plan-tab:hover,
.floor-plan-tab.active {
    color: #ffffff;
    background: #0645a4;
    border-color: #0645a4;
}

/* =========================================
   FLOOR PLAN DRAWING
========================================= */

.auto-floor-plan {
    width: 100%;
    padding: 18px 0 8px;
    background: #ffffff;
    box-sizing: border-box;
}

.auto-floor-plan-title {
    margin-bottom: 10px;
    color: #333333;
    font-size: 16px;
    font-weight: 600;
}

.floor-drawing {
    width: 100%;
    max-width: 600px;
    margin: 0 auto;
}

.floor-plan-svg {
    display: block;
    width: 100%;
    height: auto;
}

.plan-wall {
    fill: #f5f4f1;
    stroke: #60666c;
    stroke-width: 3;
}

.plan-room {
    fill: #f5f4f1;
    stroke: #60666c;
    stroke-width: 3;
}

.plan-label {
    fill: #252525;
    font-family: Arial, sans-serif;
    font-size: 17px;
    font-weight: 700;
    text-anchor: middle;
    dominant-baseline: middle;
    pointer-events: none;
}

.floor-plan-note {
    margin: 12px 0 0;
    color: #777777;
    text-align: center;
    font-size: 12px;
    line-height: 1.6;
}

/* =========================================
   RESPONSIVE
========================================= */

@media (max-width: 768px) {
    .dynamic-floor-plan {
        padding: 18px;
    }

    .floor-plan-heading h2 {
        font-size: 21px;
    }
}

@media (max-width: 480px) {
    .dynamic-floor-plan {
        margin: 18px 0;
        padding: 14px;
    }

    .floor-plan-heading h2 {
        font-size: 20px;
    }

    .floor-plan-tabs {
        gap: 8px;
        margin-bottom: 16px;
    }

    .floor-plan-tab {
        padding: 9px 14px;
        font-size: 13px;
    }

    .auto-floor-plan {
        padding-top: 10px;
    }

    .plan-label {
        font-size: 15px;
    }
}

/* ==========================================
   QUICK PROPERTY INFO - SCREENSHOT UI
========================================== */

.info-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    width: 100%;
    margin: 18px 0 24px;
    padding: 0;
    background: #ffffff;
    border-radius: 5px;
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.05);
    box-sizing: border-box;
}

/* Individual Item */

.info-grid .info-card {
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    justify-content: center;
    min-width: 0;
    min-height: 88px;
    margin: 0;
    padding: 12px 26px;
    background: #ffffff;
    border: none;
    border-radius: 0;
    box-shadow: none;
    box-sizing: border-box;
}

/* Vertical Separator */

.info-grid .info-card:not(:last-child)::after {
    content: "";
    position: absolute;
    top: 18px;
    right: 0;
    width: 1px;
    height: 48px;
    background: #b8c9e5;
}

/* Icon */

.info-grid .info-icon {
    display: flex;
    align-items: center;
    justify-content: flex-start;
    width: 100%;
    margin: 0 0 8px;
    color: #0645a4;
    font-size: 17px;
    line-height: 1;
}

.info-grid .info-icon i {
    color: #0645a4;
}

/* Hide Labels - Match Screenshot */

.info-grid .info-label {
    display: none;
}

/* Dynamic Values */

.info-grid .info-details {
    display: flex;
    flex-direction: column;
    width: 100%;
    min-width: 0;
}

.info-grid .info-value {
    display: block;
    width: 100%;
    margin: 0;
    padding: 0;
    color: #003f9e;
    font-size: 14px;
    font-weight: 400;
    line-height: 1.4;
    overflow-wrap: anywhere;
}

/* ==========================================
   TABLET
========================================== */

@media (max-width: 768px) {
    .info-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .info-grid .info-card {
        min-height: 78px;
        padding: 12px 16px;
    }

    /* Remove separator at the end of each row */
    .info-grid .info-card:nth-child(2n)::after {
        display: none;
    }

    .info-grid .info-card:nth-child(-n+2) {
        border-bottom: 1px solid #edf1f8;
    }
}

/* ==========================================
   MOBILE
========================================== */

@media (max-width: 480px) {
    .info-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 0;
        margin: 14px 0 20px;
    }

    .info-grid .info-card {
        min-height: 76px;
        padding: 10px 12px;
    }

    .info-grid .info-card:not(:last-child)::after {
        top: 12px;
        height: 48px;
    }

    .info-grid .info-card:nth-child(2n)::after {
        display: none;
    }

    .info-grid .info-icon {
        margin-bottom: 7px;
        font-size: 16px;
    }

    .info-grid .info-value {
        font-size: 12px;
        line-height: 1.5;
    }
}


/* =========================================
   AMENITIES - REFERENCE SCREENSHOT UI
========================================= */

.amenities-section {
    width: 100%;
    margin: 0;
    padding: 20px;
    background: #fff;
    border: none;
    border-radius: 14px;
    box-shadow: 0 3px 12px rgba(35, 60, 110, 0.06);
    box-sizing: border-box;
}

.amenities-main-title,
.amenities-section .section-title {
    margin: 0 0 24px;
    padding: 0;
    color: #383838;
    font-size: 20px;
    font-weight: 600;
    line-height: 1.4;
}

/* Two-column category layout */

.amenities-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    column-gap: 34px;
    row-gap: 26px;
    width: 100%;
    align-items: start;
}

/* Category */

.amenity-category {
    min-width: 0;
    width: 100%;
}

.amenity-category-title {
    margin: 0 0 18px;
    padding: 0;
    color: #383838;
    font-size: 16px;
    font-weight: 600;
    line-height: 1.4;
}

/* Vertical list */

.amenity-category-list {
    display: flex;
    flex-direction: column;
    gap: 14px;
    width: 100%;
}

/* Each amenity must be a horizontal row, NOT a card */

.amenities-section .amenity-item {
    display: flex;
    flex-direction: row;
    align-items: center;
    justify-content: flex-start;
    gap: 11px;

    width: 100%;
    min-width: 0;
    min-height: 40px;

    margin: 0;
    padding: 0;

    background: transparent;
    border: none;
    border-radius: 0;
    box-shadow: none;

    box-sizing: border-box;
}

/* Small grey icon square */

.amenities-section .amenity-icon {
    display: flex;
    align-items: center;
    justify-content: center;

    flex: 0 0 40px;
    width: 40px;
    height: 40px;

    margin: 0;
    padding: 0;

    color: #383838;
    background: #f5f5f5;

    border: none;
    border-radius: 4px;
    box-shadow: none;

    font-size: 16px;
}

/* Icon */

.amenities-section .amenity-icon i {
    color: #383838;
    font-size: 16px;
    line-height: 1;
}

/* Text aligned beside icon */

.amenities-section .amenity-name {
    display: block;
    flex: 1;
    min-width: 0;

    margin: 0;
    padding: 0;

    color: #414141;
    font-size: 15px;
    font-weight: 400;
    line-height: 1.5;

    text-align: left;
    overflow-wrap: anywhere;
}

/* Remove inherited Bootstrap card styles */

.amenities-section .amenity-item::before,
.amenities-section .amenity-item::after {
    display: none;
    content: none;
}

/* Empty state */

.amenities-section .amenities-empty {
    margin: 0;
    color: #777;
    font-size: 14px;
}

/* =========================================
   TABLET
========================================= */

@media (max-width: 768px) {
    .amenities-section {
        padding: 18px;
    }

    .amenities-grid {
        column-gap: 22px;
        row-gap: 24px;
    }

    .amenities-section .amenity-name {
        font-size: 14px;
    }
}

/* =========================================
   MOBILE
========================================= */

@media (max-width: 520px) {
    .amenities-section {
        padding: 16px 14px;
        border-radius: 10px;
    }

    .amenities-grid {
        grid-template-columns: minmax(0, 1fr);
        row-gap: 24px;
    }

    .amenities-section .amenity-category-title {
