.nearby-section {
    width: 100%;
    margin: 20px 0;
    padding: 20px 15px;
    background: #ffffff;
    border: none;
    border-radius: 12px;
    box-shadow: 0 3px 12px rgba(35, 60, 110, 0.06);
    box-sizing: border-box;
}

/* Section heading */

.nearby-section .section-title {
    margin: 0 0 24px;
    color: #383838;
    font-size: 18px;
    font-weight: 600;
    line-height: 1.4;
}

.nearby-section .section-title i {
    margin-right: 6px;
}

/* Two-column layout */

.nearby-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    column-gap: 34px;
    row-gap: 25px;
    width: 100%;
    align-items: start;
}

/* Category */

.nearby-category {
    min-width: 0;
}

.nearby-category-title {
    margin: 0 0 15px;
    color: #171717;
    font-size: 16px;
    font-weight: 500;
    line-height: 1.4;
}

/* List of places */

.nearby-category-list {
    display: flex;
    flex-direction: column;
    gap: 13px;
}

/* Individual location row */

.nearby-section .nearby-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    width: 100%;
    min-width: 0;
    margin: 0;
    padding: 0;
    background: transparent;
    border: none;
    border-radius: 0;
    box-shadow: none;
}

/* Place name */

.nearby-place-name {
    flex: 1;
    min-width: 0;
    margin: 0;
    color: #414141;
    font-size: 15px;
    font-weight: 400;
    line-height: 1.6;
    overflow-wrap: anywhere;
}

/* Distance */

.nearby-distance {
    flex-shrink: 0;
    color: #414141;
    font-size: 15px;
    font-weight: 400;
    line-height: 1.6;
    white-space: nowrap;
}

/* Empty message */

.nearby-empty {
    margin: 0;
    color: #777777;
    font-size: 14px;
}

/* =========================================
   TABLET
========================================= */

@media (max-width: 768px) {
    .nearby-section {
        padding: 18px;
    }

    .nearby-grid {
        column-gap: 22px;
        row-gap: 24px;
    }

    .nearby-place-name,
    .nearby-distance {
        font-size: 14px;
    }
}

/* =========================================
   MOBILE
========================================= */

@media (max-width: 520px) {
    .nearby-section {
        padding: 16px 14px;
        border-radius: 10px;
    }

    .nearby-section .section-title {
        margin-bottom: 20px;
        font-size: 18px;
    }

    .nearby-grid {
        grid-template-columns: minmax(0, 1fr);
        row-gap: 23px;
    }

    .nearby-category-title {
        margin-bottom: 12px;
        font-size: 15px;
    }

    .nearby-category-list {
        gap: 11px;
    }

    .nearby-place-name,
    .nearby-distance {
        font-size: 14px;
    }
}


               


