/* =========================================
   DOWNLOAD BROCHURE MODAL - UI ONLY
   ========================================= */

#enquiryModal .modal-content-prop {
    max-width: 480px;
    width: 100%;
    background: #ffffff;
    border-radius: 18px;
    overflow: hidden;
    border: 1px solid #e7ecf4;
    box-shadow: 0 20px 60px rgba(20, 42, 75, 0.18);
}

/* Header */
#enquiryModal .modal-header-prop {
    padding: 25px 26px 22px;
    background: linear-gradient(135deg, #f0f5ff, #ffffff);
    border-bottom: 1px solid #edf0f5;
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 15px;
}

#enquiryModal .modal-header-title h2 {
    margin: 0 0 8px;
    color: #183153;
    font-size: 24px;
    font-weight: 700;
    letter-spacing: -0.5px;
}

#enquiryModal .modal-header-title p {
    margin: 0;
    color: #667085;
    font-size: 13px;
    line-height: 1.6;
}

#enquiryModal .modal-close-prop .close-btn {
    width: 35px;
    height: 35px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: #ffffff;
    border: 1px solid #e4e7ec;
    color: #475467;
    font-size: 22px;
    cursor: pointer;
    transition: 0.25s ease;
}

#enquiryModal .modal-close-prop .close-btn:hover {
    background: #295cab;
    border-color: #295cab;
    color: #ffffff;
}

/* Form body */
#enquiryModal .modal-body {
    padding: 25px 26px 28px;
    background: #ffffff;
}

#enquiryModal .enquiry-form .form-group {
    margin-bottom: 20px;
}

#enquiryModal .enquiry-form .form-group label {
    display: block;
    margin-bottom: 9px;
    color: #344054;
    font-size: 14px;
    font-weight: 600;
}

#enquiryModal .enquiry-form .required {
    color: #e53935;
}

#enquiryModal .enquiry-form .brochure-input {
    display: block;
    width: 100%;
    height: 49px;
    padding: 0 15px;
    border: 1px solid #dce2eb;
    border-radius: 9px;
    background: #ffffff;
    color: #1d2939;
    font-size: 14px;
    box-sizing: border-box;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

#enquiryModal .enquiry-form .brochure-input::placeholder {
    color: #98a2b3;
}

#enquiryModal .enquiry-form .brochure-input:focus {
    outline: none;
    border-color: #295cab;
    box-shadow: 0 0 0 3px rgba(41, 92, 171, 0.10);
}

/* Information box */
#enquiryModal .brochure-info-box {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    padding: 13px 14px;
    margin: 2px 0 22px;
    background: #f7f9fc;
    border: 1px solid #edf0f5;
    border-radius: 10px;
}

#enquiryModal .brochure-info-item {
    display: flex;
    align-items: center;
    gap: 8px;
    color: #52627a;
    font-size: 12px;
}

#enquiryModal .brochure-info-item i {
    color: #295cab;
    font-size: 15px;
}

/* Download button */
#enquiryModal .brochure-submit-btn {
    width: 100%;
    min-height: 51px;
    padding: 13px 18px;
    border: none;
    border-radius: 9px;
    background: #295cab;
    color: #ffffff;
    font-size: 15px;
    font-weight: 600;
    cursor: pointer;
    box-shadow: 0 5px 14px rgba(41, 92, 171, 0.18);
    transition: background 0.25s ease, transform 0.25s ease;
}

#enquiryModal .brochure-submit-btn i {
    margin-right: 7px;
}

#enquiryModal .brochure-submit-btn:hover {
    background: #1f4787;
    transform: translateY(-1px);
}

#enquiryModal .brochure-submit-btn:disabled {
    opacity: 0.65;
    cursor: not-allowed;
    transform: none;
}

/* Success and error messages */
#enquiryModal #brochureSuccess,
#enquiryModal #brochureError {
    padding: 14px 16px;
    margin-bottom: 20px;
    border-radius: 9px;
    font-size: 13px;
    line-height: 1.6;
}

/* Mobile UI */
@media (max-width: 576px) {
    #enquiryModal {
        padding: 14px;
    }

    #enquiryModal .modal-content-prop {
        max-width: 100%;
        border-radius: 14px;
    }

    #enquiryModal .modal-header-prop {
        padding: 20px 18px;
    }

    #enquiryModal .modal-header-title h2 {
        font-size: 21px;
    }

    #enquiryModal .modal-body {
        padding: 20px 18px 22px;
    }

    #enquiryModal .brochure-info-box {
        flex-direction: column;
        align-items: flex-start;
        gap: 12px;
    }

    #enquiryModal .enquiry-form .form-group {
        margin-bottom: 17px;
    }
}

/* Fix Download Brochure Header */
#enquiryModal .modal-header-prop {
    background: #f5f8ff !important;
    background-image: none !important;
}

#enquiryModal .modal-header-title {
    background: transparent !important;
    background-color: transparent !important;
    color: #183153 !important;
    width: 100%;
    flex: 1;
}

#enquiryModal .modal-header-title h2 {
    display: block !important;
    width: auto !important;
    background: transparent !important;
    background-color: transparent !important;
    color: #183153 !important;
    padding: 0 !important;
    margin: 0 0 8px !important;
    font-size: 24px !important;
    font-weight: 700 !important;
    line-height: 1.4 !important;
    text-transform: none !important;
}

#enquiryModal .modal-header-title p {
    display: block !important;
    width: auto !important;
    background: transparent !important;
    background-color: transparent !important;
    color: #667085 !important;
    padding: 0 !important;
    margin: 0 !important;
    font-size: 14px !important;
    line-height: 1.6 !important;
}

#enquiryModal .modal-close-prop {
    flex-shrink: 0;
    background: transparent !important;
}

#enquiryModal .modal-close-prop .close-btn {
    background: #ffffff !important;
    color: #475467 !important;
}

keyframes enquiryMessageFade {
    from {
        opacity: 0;
        transform: translateY(6px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Mobile responsive */



/* =========================================
   STICKY SIDEBAR
   ========================================= */

#mainwrapper {
    display: flex;
    flex-wrap: wrap;
    align-items: stretch;
    overflow: visible !important;
}

#mainwrapper .content-main {
    overflow: visible !important;
}

#mainwrapper .content-sidebar {
    position: relative !important;
    overflow: visible !important;
    align-self: stretch !important;
    min-width: 0;
}

#mainwrapper #enquire.sidebar-card {
    position: -webkit-sticky !important;
    position: sticky !important;
    top: 100px !important;
    width: 100% !important;
    height: max-content !important;
    align-self: flex-start !important;
    z-index: 10 !important;
    padding: 0 !important;
    background: transparent;
    border: none;
    box-shadow: none;
    border-radius: 0;
    box-sizing: border-box;
}


/* =========================================
   FORM CARD - SCREENSHOT STYLE
   ========================================= */

.sidebar-form-box,
.emi-calculator-box {
    width: 100%;
    padding: 20px;
    background: #ffffff;
    border: 1px solid #a5bfff;
    border-radius: 16px;
    box-sizing: border-box;
}

.sidebar-form-box {
    margin-bottom: 14px;
}

.sidebar-form-box h3 {
    margin: 0 0 16px !important;
    color: #383838;
    font-size: 16px;
    font-weight: 600;
    line-height: 1.4;
    text-align: center;
}

.sidebar-form-box .row {
    display: block;
    margin: 0;
}

.sidebar-form-box .form-group {
    width: 100%;
    margin: 0 0 12px;
}

.sidebar-form-box .form-group label {
    display: block;
    margin: 0 0 5px;
    color: #454545;
    font-size: 12px;
    font-weight: 400;
}

.sidebar-form-box .form-control {
    display: block;
    width: 100%;
    min-height: 35px;
    padding: 9px 11px;
    color: #333333;
    background: #ffffff;
    border: 1px solid #dedede;
    border-radius: 6px;
    box-shadow: none;
    font-size: 12px;
    line-height: 1.4;
    box-sizing: border-box;
}

.sidebar-form-box textarea.form-control {
    min-height: 75px;
    resize: vertical;
}

.sidebar-form-box .form-control:focus {
    border-color: #8db1ff;
    outline: none;
    box-shadow: 0 0 0 2px rgba(47, 111, 255, 0.08);
}

/* Preserve the existing Send Message button and classes */

.sidebar-form-box button.full-width {
    display: block;
    width: 100%;
    min-height: 38px;
    padding: 9px 12px;
    color: #1769ff;
    background: #ffffff;
    border: 1px solid #8db1ff;
    border-radius: 7px;
    box-shadow: none;
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
}

.sidebar-form-box button.full-width:hover {
    color: #ffffff;
    background: #1769ff;
}

.sidebar-form-box .project-status h4 {
    margin: 0 0 12px;
    font-size: 15px;
    font-weight: 600;
    color: #383838;
}

.sidebar-form-box .btn-brochure {
    display: block;
    width: 100%;
    padding: 10px 12px;
    color: #1769ff;
    background: #ffffff;
    border: 1px solid #8db1ff;
    border-radius: 7px;
    font-size: 13px;
    cursor: pointer;
}

.sidebar-form-box .btn-brochure:hover {
    color: #ffffff;
    background: #1769ff;
}


/* =========================================
   EMI CALCULATOR CARD
   ========================================= */

.emi-calculator-box {
    margin-bottom: 16px;
}

.emi-heading {
    margin: 0 0 20px;
    color: #383838;
    font-size: 16px;
    font-weight: 600;
    line-height: 1.4;
    text-align: center;
}

.emi-control {
    margin-bottom: 22px;
}

.emi-control-heading {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 5px;
    margin-bottom: 9px;
}

.emi-control-heading label {
    flex: 1;
    margin: 0;
    color: #333333;
    font-size: 12px;
    font-weight: 500;
}

.emi-control-heading input {
    width: 95px;
    min-width: 0;
    padding: 0;
    color: #333333;
    background: transparent;
    border: none;
    outline: none;
    box-shadow: none;
    font-family: inherit;
    font-size: 12px;
    font-weight: 500;
    text-align: right;
}

.emi-control-heading input[type="number"] {
    width: 45px;
    appearance: textfield;
    -moz-appearance: textfield;
}

.emi-control-heading input[type="number"]::-webkit-inner-spin-button,
.emi-control-heading input[type="number"]::-webkit-outer-spin-button {
    margin: 0;
    -webkit-appearance: none;
}

.emi-editable-value {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 3px;
    white-space: nowrap;
}

.emi-editable-value span {
    color: #333333;
    font-size: 12px;
}

/* Sliders */

.emi-slider {
    display: block;
    width: 100%;
    height: 4px;
    margin: 0;
    padding: 0;
    appearance: none;
    -webkit-appearance: none;
    background: #d5f1fa;
    border: none;
    border-radius: 5px;
    outline: none;
    cursor: pointer;
}

.emi-slider::-webkit-slider-thumb {
    width: 11px;
    height: 11px;
    appearance: none;
    -webkit-appearance: none;
    background: #2879ed;
    border: none;
    border-radius: 50%;
    cursor: pointer;
}

.emi-slider::-moz-range-thumb {
    width: 11px;
    height: 11px;
    background: #2879ed;
    border: none;
    border-radius: 50%;
    cursor: pointer;
}

.emi-limits {
    display: flex;
    justify-content: space-between;
    margin-top: 9px;
    color: #555555;
    font-size: 10px;
}

/* Monthly EMI */

.emi-output {
    margin: 2px 0 24px;
}

.emi-output-label {
    margin-bottom: 7px;
    color: #1769ff;
    font-size: 13px;
}

.emi-output-box {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 4px;
    min-height: 42px;
    padding: 8px;
    color: #1769ff;
    background: #ffffff;
    border: 1px solid #a5bfff;
    border-radius: 7px;
    box-sizing: border-box;
    font-size: 15px;
    font-weight: 600;
    text-align: center;
}

.emi-month-text {
    font-weight: 400;
}

/* Breakdown bar */

.emi-breakdown-bar {
    display: flex;
    width: 100%;
    height: 5px;
    margin-bottom: 11px;
    overflow: hidden;
    background: #eeeeee;
}

.emi-principal-bar {
    width: 50%;
    background: #5076f6;
    transition: width 0.2s ease;
}

.emi-interest-bar {
    width: 50%;
    background: #8a43ed;
    transition: width 0.2s ease;
}

.emi-breakdown-row {
    display: flex;
    justify-content: space-between;
    gap: 10px;
}

.emi-breakdown-column {
    min-width: 0;
}

.emi-align-right {
    text-align: right;
}

.emi-breakdown-label {
    display: block;
    margin-bottom: 2px;
    color: #777777;
    font-size: 11px;
    line-height: 1.4;
}

.emi-breakdown-column strong {
    color: #5076f6;
    font-size: 13px;
    font-weight: 600;
    overflow-wrap: anywhere;
}

.emi-align-right strong {
    color: #8a43ed;
}

.emi-breakdown-column small {
    color: #5076f6;
    font-size: 10px;
}

.emi-align-right small {
    color: #8a43ed;
}


/* =========================================
   RESPONSIVE
   ========================================= */

@media (min-width: 993px) {
    #mainwrapper {
        align-items: stretch !important;
        overflow: visible !important;
    }

    #mainwrapper .content-main,
    #mainwrapper .content-sidebar {
        overflow: visible !important;
    }

    #mainwrapper #enquire.sidebar-card {
        position: -webkit-sticky !important;
        position: sticky !important;
        top: 100px !important;
    }
}

@media (max-width: 992px) {
    #mainwrapper {
        display: flex !important;
        flex-direction: column !important;
        align-items: stretch !important;
        overflow: visible !important;
    }

    #mainwrapper .content-main,
    #mainwrapper .content-sidebar {
        width: 100% !important;
        max-width: 100% !important;
        overflow: visible !important;
    }

    #mainwrapper .content-sidebar {
        position: relative !important;
        align-self: stretch !important;
    }

    #mainwrapper #enquire.sidebar-card {
        position: relative !important;
        top: auto !important;
        width: 100% !important;
        height: max-content !important;
    }
}

@media (max-width: 520px) {
    .sidebar-form-box,
    .emi-calculator-box {
        padding: 18px;
        border-radius: 14px;
    }

    .emi-breakdown-row {
        gap: 7px;
    }

    .emi-breakdown-column strong {
        font-size: 12px;
    }
}

/* Remove background blur when Book a Visit opens */
#mainwrapper.blur,
#mainwrapper.blur * {
    filter: none !important;
    -webkit-filter: none !important;
}

/* Keep the page readable behind the form */
.form-container-overlay {
    background: rgba(0, 0, 0, 0.35) !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
}
        

#map {
    width: 100%;
    height: 400px;
    min-height: 400px;
    display: block;
    position: relative;
    z-index: 1;
}
.nearby-section {
    width: 100%;
    margin: 20px 0;
    padding: 20px 15px;
    background: #ffffff;
    border: none;
    border-radius: 12px;
    box-shadow: 0 3px 12px rgba(35, 60, 110, 0.06);
    box-sizing: border-box;
}

/* Section heading */

.nearby-section .section-title {
    margin: 0 0 24px;
    color: #383838;
    font-size: 18px;
    font-weight: 600;
    line-height: 1.4;
}

.nearby-section .section-title i {
    margin-right: 6px;
}

/* Two-column layout */

.nearby-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    column-gap: 34px;
    row-gap: 25px;
    width: 100%;
    align-items: start;
}

/* Category */

.nearby-category {
    min-width: 0;
}

.nearby-category-title {
    margin: 0 0 15px;
    color: #171717;
    font-size: 16px;
    font-weight: 500;
    line-height: 1.4;
}

/* List of places */

.nearby-category-list {
    display: flex;
    flex-direction: column;
    gap: 13px;
}

/* Individual location row */

.nearby-section .nearby-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    width: 100%;
    min-width: 0;
    margin: 0;
    padding: 0;
    background: transparent;
    border: none;
    border-radius: 0;
    box-shadow: none;
}

/* Place name */

.nearby-place-name {
    flex: 1;
    min-width: 0;
    margin: 0;
    color: #414141;
    font-size: 15px;
    font-weight: 400;
    line-height: 1.6;
    overflow-wrap: anywhere;
}

/* Distance */

.nearby-distance {
    flex-shrink: 0;
    color: #414141;
    font-size: 15px;
    font-weight: 400;
    line-height: 1.6;
    white-space: nowrap;
}

/* Empty message */

.nearby-empty {
    margin: 0;
    color: #777777;
    font-size: 14px;
}

/* =========================================
   TABLET
========================================= */

@media (max-width: 768px) {
    .nearby-section {
        padding: 18px;
    }

    .nearby-grid {
        column-gap: 22px;
        row-gap: 24px;
    }

    .nearby-place-name,
    .nearby-distance {
        font-size: 14px;
    }
}

/* =========================================
   MOBILE
========================================= */

@media (max-width: 520px) {
    .nearby-section {
        padding: 16px 14px;
        border-radius: 10px;
    }

    .nearby-section .section-title {
        margin-bottom: 20px;
        font-size: 18px;
    }

    .nearby-grid {
        grid-template-columns: minmax(0, 1fr);
        row-gap: 23px;
    }

    .nearby-category-title {
        margin-bottom: 12px;
        font-size: 15px;
    }

    .nearby-category-list {
        gap: 11px;
    }

    .nearby-place-name,
    .nearby-distance {
        font-size: 14px;
    }
}



/* ================= HERO BANNER ================= */
section.jfinHero#home {
    width: 100%;
    overflow: hidden;
}

section.jfinHero#home .jfinHeroSlide {
    width: 100%;
    background-size: cover;
    background-position: center center;
    background-repeat: no-repeat;
}

section.jfinHero#home .jfinHeroContent {
    display: flex;
    align-items: center;
    width: 100%;
    min-height: 550px;
    padding: 40px 7%;
    box-sizing: border-box;
}

/* Transparent black background behind text */
section.jfinHero#home .jfinHeroText {
    width: 100%;
    max-width: 720px;
    padding: 25px 30px;
    /* background: rgba(0, 0, 0, 0.45); */
    border-radius: 10px;
    box-sizing: border-box;
}

/* All text white */
section.jfinHero#home .jfinHeroLabel,
section.jfinHero#home .jfinHeroTitle,
section.jfinHero#home .jfinHeroTitle span,
section.jfinHero#home .jfinHeroDescription {
    color: #ffffff !important;
}

section.jfinHero#home .jfinHeroTitle {
    font-weight: 700;
    line-height: 1.2;
}

section.jfinHero#home .jfinHeroTitle span {
    display: block;
}

section.jfinHero#home .jfinHeroDescription {
    line-height: 1.7;
}

/* Button */
section.jfinHero#home .jfinHeroButtons {
    display: flex;
    flex-wrap: wrap;
    margin-top: 20px;
}

section.jfinHero#home .jfinHeroButtons a.jfinHeroBtn.jfinHeroApply {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 154px;
    min-width: 158px;
    height: 51px;
    padding: 0 15px;
    box-sizing: border-box;

    background: #3069e8 !important;
    color: #ffffff !important;
    border: none !important;
    border-radius: 12px !important;
    box-shadow: none;
    text-decoration: none;
    font-size: 16px;
    font-weight: 600;
    white-space: nowrap;
}

/* Reduce button size on mobile only */
@media (max-width: 480px) {
    section.jfinHero#home .jfinHeroButtons a.jfinHeroBtn.jfinHeroApply {
        width: 130px !important;
        min-width: 100px !important;
        height: 40px !important;
        padding: 0 10px !important;
        font-size: 14px !important;
        border-radius: 10px !important;
    }
}

/* Fix white space above mobile hero banner */
@media (max-width: 768px) {

    section.jfinHero#home {
        width: 100% !important;
        margin-top: 0 !important;
        padding-top: 0 !important;
        overflow: hidden !important;
        background: #17232b !important;
    }

    section.jfinHero#home .jfinHeroSlider {
        width: 100% !important;
        margin: 0 !important;
        padding: 0 !important;
    }

    section.jfinHero#home .jfinHeroSlide {
        margin: 0 !important;
        padding: 0 !important;
        background-size: cover !important;
        background-position: center center !important;
        background-repeat: no-repeat !important;
    }

    section.jfinHero#home .jfinHeroContent {
        min-height: 400px !important;
        margin: 0 !important;
        padding: 14px !important;
    }

    /* Prevent extra space from the first heading */
    section.jfinHero#home .jfinHeroText {
        margin-top: 0 !important;
    }

    section.jfinHero#home .jfinHeroLabel {
        margin-top: 0 !important;
    }
}

/* Fix white patches on mobile hero banner */
@media (max-width: 768px) {

    html,
    body {
        overflow-x: hidden;
    }

    section.jfinHero#home {
        display: block !important;
        width: 100% !important;
        margin: 0 !important;
        padding: 0 !important;
        overflow: hidden !important;
        background: #17232b !important;
        line-height: normal;
    }

    section.jfinHero#home .jfinHeroSlider {
        display: block !important;
        width: 100% !important;
        margin: 0 !important;
        padding: 0 !important;
        background: #17232b !important;
    }

    section.jfinHero#home .jfinHeroSlide {
        display: block !important;
        width: 100% !important;
        min-height: 0 !important;
        height: auto !important;
        margin: 0 !important;
        padding: 0 !important;
        background-size: cover !important;
        background-position: center center !important;
        background-repeat: no-repeat !important;
        background-color: #17232b !important;
    }

    section.jfinHero#home .jfinHeroContent {
        display: flex !important;
        align-items: flex-start !important;
        width: 100% !important;
        min-height: 0 !important;
        height: auto !important;
        padding: 14px !important;
        margin: 0 !important;
        box-sizing: border-box !important;
    }

    section.jfinHero#home .jfinHeroText {
        margin: 0 !important;
        max-width: 100% !important;
    }
}
@media (max-width: 767px) {
    .jfinHeroLabel {
        margin-top: 17px !important;
    }
}

/* ================= TABLET ================= */
@media (max-width: 768px) {
    section.jfinHero#home .jfinHeroContent {
        min-height: 420px;
        padding: 20px;
    }

    section.jfinHero#home .jfinHeroText {
        max-width: 100%;
        padding: 18px;
        /* background: rgba(0, 0, 0, 0.58); */
        border-radius: 8px;
    }

    section.jfinHero#home .jfinHeroTitle {
        font-size: 28px;
        line-height: 1.2;
    }

    section.jfinHero#home .jfinHeroDescription {
        font-size: 14px;
        line-height: 1.5;
    }

    section.jfinHero#home .jfinHeroButtons a.jfinHeroBtn.jfinHeroApply {
        width: 150px;
        min-width: 150px;
        height: 52px;
        font-size: 18px;
    }
}

/* ================= MOBILE / IPHONE ================= */
@media (max-width: 480px) {
    section.jfinHero#home .jfinHeroSlide {
        background-position: 58% center;
    }

    section.jfinHero#home .jfinHeroContent {
        min-height: 400px;
        padding: 14px;
    }

    section.jfinHero#home .jfinHeroText {
        padding: 15px;
        /* background: rgba(0, 0, 0, 0.62); */
        border-radius: 8px;
    }

    section.jfinHero#home .jfinHeroLabel {
        font-size: 10px;
        letter-spacing: 2px;
    }

    section.jfinHero#home .jfinHeroTitle {
        font-size: 24px;
        line-height: 1.25;
        margin: 10px 0;
    }

    section.jfinHero#home .jfinHeroDescription {
        font-size: 12px;
        line-height: 1.5;
        margin-bottom: 12px;
    }

    section.jfinHero#home .jfinHeroButtons {
        margin-top: 15px;
    }

    section.jfinHero#home .jfinHeroButtons a.jfinHeroBtn.jfinHeroApply {
        width: 135px;
        min-width: 135px;
        height: 48px;
