    }
}

/* Extra-small mobile screens */
@media (max-width: 360px) {
    section.jfinHero#home .jfinHeroContent {
        min-height: 380px;
        padding: 10px;
    }

    section.jfinHero#home .jfinHeroText {
        padding: 12px;
    }

    section.jfinHero#home .jfinHeroTitle {
        font-size: 21px;
    }

    section.jfinHero#home .jfinHeroDescription {
        font-size: 11px;
    }
}


/* contact css */

/* ===============================
   CONTACT SECTION
================================ */

.jfin-contact {
    width: 100%;
    padding: 50px 25px 55px;
    background: #f9fbfd;
    font-family: Arial, Helvetica, sans-serif;
    box-sizing: border-box;
}

.jfin-contact *,
.jfin-contact *::before,
.jfin-contact *::after {
    box-sizing: border-box;
}

.jfin-contact-container {
    max-width: 1100px;
    width: 100%;
    margin: 0 auto;
    display: grid;
    grid-template-columns: minmax(0, 1.65fr) minmax(280px, 0.95fr);
    gap: 65px;
    align-items: start;
}

/* LEFT INFO GRID */

.jfin-contact-info-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 16px;
    margin-bottom: 14px;
}

.jfin-contact-info-card {
    min-height: 90px;
    padding: 15px 16px;
    border: 1px solid #e2e2e2;
    border-radius: 10px;
    background: #fff;
    transition: box-shadow 0.25s ease;
}

.jfin-contact-info-card:hover {
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.06);
}

.jfin-contact-info-card h4 {
    display: flex;
    align-items: center;
    gap: 9px;
    margin: 0 0 8px;
    color: #424242;
    font-size: 18px;
    font-weight: 600;
}

.jfin-contact-info-card h4 i {
    font-size: 15px;
    color: #4c4c4c;
}

.jfin-contact-info-card p {
    margin: 0;
    color: #666;
    font-size: 14px;
    line-height: 1.65;
    overflow-wrap: anywhere;
}

.jfin-contact-info-card a {
    color: inherit;
    text-decoration: none;
}

.jfin-contact-info-card a:hover {
    color: #2870e8;
}

/* MAP */

.jfin-contact-map {
    width: 100%;
    height: 269px;
    overflow: hidden;
    border-radius: 10px;
    border: 1px solid #e1e5eb;
    background: #fff;
    margin-top: 14px;
}

.jfin-contact-map iframe {
    display: block;
    width: 100%;
    height: 100%;
    border: 0;
}

/* SOCIAL MEDIA */

.jfin-contact-social {
    min-height: 40px;
    display: flex;
    align-items: center;
    gap: 26px;
    flex-wrap: wrap;
    padding: 10px 12px;
    margin-top: 14px;
    border-radius: 9px;
    background: #fff;
}

.jfin-contact-social strong {
    margin-right: 3px;
    color: #444;
    font-size: 14px;
    font-weight: 700;
}

.jfin-contact-social a {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: 25px;
    text-decoration: none;
}

.jfin-contact-social a:nth-of-type(1) {
    color: #1877f2;
}

.jfin-contact-social a:nth-of-type(2) {
    color: #1da1f2;
}

.jfin-contact-social a:nth-of-type(3) {
    color: #0a66c2;
}

.jfin-contact-social a:nth-of-type(4) {
    color: #e4405f;
}

/* CONTACT FORM CARD */

.jfin-contact-form-card {
    width: 142%;
    padding: 20px 17px 17px;
    border-radius: 13px;
    background: #fff;
    border: 1px solid #edf3f5;
    box-shadow: 0 2px 9px rgba(34, 94, 105, 0.10);
}

.jfin-contact-form-card h3 {
    margin: 0 0 20px;
    color: #333;
    font-size: 14px;
    font-weight: 700;
}

.jfin-form-group {
    margin-bottom: 12px;
}

.jfin-form-group label {
    display: block;
    margin-bottom: 5px;
    color: #333;
    font-size: 14px;
    font-weight: 500;
}

.jfin-form-group input,
.jfin-form-group textarea {
    display: block;
    width: 100%;
    min-width: 0;
    padding: 10px;
    border: 1px solid #dedede;
    border-radius: 6px;
    outline: none;
    background: #fafafa;
    color: #333;
    font-family: inherit;
    font-size: 10px;
    transition: border-color 0.2s ease;
}

.jfin-form-group input {
    height: 35px;
}

.jfin-form-group textarea {
    height: 70px;
    resize: vertical;
}

.jfin-form-group input:focus,
.jfin-form-group textarea:focus {
    border-color: #2870e8;
    background: #fff;
}

.jfin-form-group input::placeholder,
.jfin-form-group textarea::placeholder {
    color: #999;
}

.jfin-contact-consent {
    display: flex;
    align-items: flex-start;
    gap: 8px;
    margin: 10px 0 14px;
}

.jfin-contact-consent input {
    width: 14px;
    height: 14px;
    flex-shrink: 0;
    margin: 2px 0 0;
    cursor: pointer;
    accent-color: #2870e8;
}

.jfin-contact-consent label {
    color: #777;
    font-size: 12px;
    line-height: 1.45;
    cursor: pointer;
}

.jfin-contact-submit {
    display: flex;
    justify-content: center;
    align-items: center;
    width: 100%;
    min-height: 34px;
    padding: 9px 15px;
    border: 0;
    border-radius: 5px;
    background: #2870e8;
    color: #fff;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.2s ease;
}

.jfin-contact-submit:hover {
    background: #185bc8;
}

/* TABLET RESPONSIVE */

@media (max-width: 900px) {
    .jfin-contact-container {
        grid-template-columns: minmax(0, 1.2fr) minmax(260px, 0.9fr);
        gap: 25px;
    }

    .jfin-contact {
        padding: 40px 20px;
    }

    .jfin-contact-info-grid {
        gap: 12px;
    }
}

/* MOBILE RESPONSIVE */

@media (max-width: 650px) {
    .jfin-contact {
        padding: 30px 16px;
    }

    .jfin-contact-container {
        grid-template-columns: minmax(0, 1fr);
        gap: 25px;
    }

    .jfin-contact-info-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 10px;
    }

    .jfin-contact-info-card {
        min-height: 100px;
        padding: 13px 11px;
    }

    .jfin-contact-info-card h4 {
        gap: 6px;
        font-size: 12px;
    }

    .jfin-contact-info-card h4 i {
        font-size: 13px;
    }

    .jfin-contact-info-card p {
        font-size: 11px;
        line-height: 1.6;
    }

    .jfin-contact-map {
        height: 200px;
    }

    .jfin-contact-social {
        gap: 12px;
    }

    .jfin-contact-form-card {
        max-width: 100%;
        padding: 22px 18px;
    }

    .jfin-contact-form-card h3 {
        font-size: 17px;
        margin-bottom: 20px;
    }

    .jfin-form-group label {
        font-size: 12px;
    }

    .jfin-form-group input {
        height: 42px;
        font-size: 13px;
    }

    .jfin-form-group textarea {
        height: 100px;
        font-size: 13px;
    }

    .jfin-contact-consent label {
        font-size: 11px;
    }

    .jfin-contact-submit {
        min-height: 44px;
        font-size: 14px;
    }
}

/* SMALL MOBILE */

@media (max-width: 360px) {
    .jfin-contact-info-grid {
        grid-template-columns: minmax(0, 1fr);
    }

    .jfin-contact-info-card {
        min-height: auto;
    }

    .jfin-contact-social {
        gap: 10px;
    }
}
/* refer nd earn */

        /* ----- RESET & BASE ----- */
       
        .jf-modern {
            max-width: 100%;
            overflow-x: hidden;
        }
        .jf-container {
            width: min(1180px, calc(100% - 40px));
            margin: 0 auto;
        }
        /* buttons & common */
        .jf-btn {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            gap: 10px;
            padding: 12px 28px;
            border-radius: 60px;
            font-weight: 700;
            font-size: 0.95rem;
            text-decoration: none;
            transition: 0.2s;
            border: 2px solid transparent;
            cursor: pointer;
            min-height: 50px;
        }
        .jf-btn-primary {
            background: #1769e0;
            color: #fff;
            border-color: #1769e0;
        }
        .jf-btn-primary:hover {
            background: #0d4fb3;
            border-color: #0d4fb3;
        }
        .jf-btn-outline {
            background: transparent;
            color: #071b33;
            border-color: #cbd9e8;
        }
        .jf-btn-outline:hover {
            border-color: #1769e0;
            color: #1769e0;
            background: #f2f8ff;
        }
        .jf-footnote {
            font-size: 0.8rem;
            color: #718096;
            margin-top: 20px;
        }
        .eyebrow {
            display: inline-flex;
            align-items: center;
            gap: 6px;
            font-size: 0.75rem;
            font-weight: 800;
            text-transform: uppercase;
            letter-spacing: 1.2px;
            color: #1769e0;
            background: #eaf3ff;
            padding: 6px 14px;
            border-radius: 40px;
        }

        /* =========================================================
           JFINMATE HERO BANNER - DESKTOP / TABLET / MOBILE
           ========================================================= */

        #home.hero {
            width: 100%;
            margin: 0;
            padding: 0;
            overflow: hidden;
            position: relative;
        }

        #home .hero-slider {
            width: 100%;
            margin: 0;
            padding: 0;
            position: relative;
        }

        #home .hero-slider .slide {
            width: 100%;
            height: 78vh;
            min-height: 600px;
            max-height: 800px;
            position: relative;
            display: flex;
            align-items: center;
            overflow: hidden;
            background-size: cover;
            background-position: center center;
            background-repeat: no-repeat;
        }

        #home .hero-slider .slide::before {
            content: "";
            position: absolute;
            inset: 0;
            z-index: 1;
            pointer-events: none;
            background: linear-gradient(
                90deg,
                rgba(255,255,255,0.96) 0%,
                rgba(255,255,255,0.88) 28%,
                rgba(255,255,255,0.48) 55%,
                rgba(255,255,255,0.10) 78%,
                rgba(255,255,255,0) 100%
            );
        }

        #home .hero-content {
            width: min(1180px, calc(100% - 40px));
            height: 100%;
            margin: 0 auto;
            padding: 50px 0;
            position: relative;
            z-index: 2;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: flex-start;
            text-align: left;
            box-sizing: border-box;
        }

        #home .hero-intro {
            display: block;
            margin: 0 0 14px;
            color: #295cab;
            font-size: 15px;
            line-height: 1.4;
            font-weight: 800;
            letter-spacing: 2px;
            text-transform: uppercase;
        }

        #home .hero-content h1 {
            width: 100%;
            max-width: 720px;
            margin: 0 0 20px;
            color: #1a1a2e;
            font-size: clamp(42px, 5vw, 68px);
            line-height: 1.08;
            font-weight: 800;
            letter-spacing: -1.5px;
        }

        #home .hero-content h1 span {
            color: #295cab !important;
        }

        #home .hero-content > p {
            width: 100%;
            max-width: 650px;
            margin: 0 0 30px;
            color: #4a5568;
            font-size: 17px;
            line-height: 1.75;
        }

        #home .hero-btns {
            display: flex;
            align-items: center;
            justify-content: flex-start;
            flex-wrap: wrap;
            gap: 14px;
            width: auto;
        }

        #home .hero-btns .btn {
            min-height: 52px;
            padding: 13px 28px;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            border-radius: 50px;
            font-size: 15px;
            font-weight: 700;
            line-height: 1.2;
            text-decoration: none;
            box-sizing: border-box;
            transition: all 0.25s ease;
        }

        #home .hero-btns .btn-primary-hero {
            background: #295cab;
            color: #ffffff;
            border: 2px solid #295cab;
        }

        #home .hero-btns .btn-primary-hero:hover {
            background: #1e4789;
            border-color: #1e4789;
            color: #ffffff;
            transform: translateY(-2px);
        }

        #home .hero-btns .btn-outline {
            background: rgba(255,255,255,0.92);
            color: #295cab;
            border: 2px solid #295cab;
        }

        #home .hero-btns .btn-outline:hover {
            background: #295cab;
            color: #ffffff;
            transform: translateY(-2px);
        }

        /* TABLET */
        @media (max-width: 991px) {
            #home .hero-slider .slide {
                height: 620px;
                min-height: 620px;
            }

            #home .hero-content {
                width: min(100% - 50px, 760px);
            }

            #home .hero-content h1 {
                max-width: 620px;
                font-size: clamp(40px, 6vw, 56px);
            }

            #home .hero-content > p {
                max-width: 580px;
                font-size: 16px;
            }
        }

        /* MOBILE */
