        /* ===== OTHER SECTIONS (JFINMATE MODERN) ===== */
        :root {
            --jf-navy: #071b33;
            --jf-blue: #1769e0;
            --jf-blue-dark: #0d4fb3;
            --jf-sky: #eaf3ff;
            --jf-light: #f6f9fd;
            --jf-text: #26364a;
            --jf-muted: #718096;
            --jf-border: #e3ebf5;
            --jf-white: #ffffff;
            --jf-success: #18a66b;
        }

        .jf-modern .jf-section-heading {
            max-width: 700px;
            margin: 0 auto 55px;
            text-align: center;
        }
        .jf-modern .jf-section-heading h2 {
            font-size: clamp(30px, 4vw, 44px);
            font-weight: 800;
            color: var(--jf-navy);
            margin: 15px 0;
        }
        .jf-modern .jf-section-heading p {
            color: var(--jf-muted);
            font-size: 1rem;
            line-height: 1.8;
        }

        /* why */
        .jf-why {
            padding: 100px 0;
            background: var(--jf-light);
            position: relative;
        }
        .jf-why-wrap {
            display: grid;
            grid-template-columns: 1.2fr 0.8fr;
            gap: 70px;
            align-items: center;
        }
        .jf-why-content h2 {
            font-size: clamp(32px, 4vw, 48px);
            font-weight: 800;
            color: var(--jf-navy);
            line-height: 1.12;
            margin: 20px 0 20px;
        }
        .jf-why-content h2 span { color: var(--jf-blue); }
        .jf-why-content p {
            color: var(--jf-muted);
            line-height: 1.85;
            margin-bottom: 16px;
        }
        .jf-why-points {
            display: grid;
            grid-template-columns: repeat(2,1fr);
            gap: 14px;
            margin-top: 30px;
        }
        .jf-why-point {
            display: flex;
            align-items: center;
            gap: 12px;
            font-weight: 700;
            color: var(--jf-navy);
            font-size: 0.9rem;
        }
        .jf-why-point i {
            width: 30px;
            height: 30px;
            border-radius: 50%;
            background: #e4f7ef;
            color: var(--jf-success);
            display: flex;
            align-items: center;
            justify-content: center;
        }
        .jf-reward-box {
            background: #295cab;
            border-radius: 35px;
            padding: 45px;
            color: #fff;
            min-height: 360px;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            position: relative;
            overflow: hidden;
        }
        .jf-reward-icon {
            width: 72px;
            height: 72px;
            border-radius: 20px;
            background: rgba(255,255,255,0.1);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 30px;
        }
        .jf-reward-box h3 {
            font-size: 28px;
            line-height: 1.2;
            margin: 30px 0 12px;
        }
        .jf-reward-box p { color: rgba(255,255,255,0.7); }
        .jf-reward-tag {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            background: #1769e0;
            padding: 10px 18px;
            border-radius: 50px;
            font-weight: 700;
            font-size: 0.85rem;
            width: fit-content;
        }

        /* journey */
        .jf-journey {
            padding: 100px 0;
            background: #fff;
        }
        .jf-journey-grid {
            display: grid;
            grid-template-columns: repeat(2,1fr);
            gap: 25px;
        }
        .jf-journey-card {
            border: 1px solid var(--jf-border);
            border-radius: 28px;
            padding: 38px;
            background: #fff;
            transition: 0.25s;
            position: relative;
        }
        .jf-journey-card:hover {
            transform: translateY(-7px);
            box-shadow: 0 25px 60px rgba(17,51,89,0.08);
            border-color: #cfe1fa;
        }
        .jf-card-number {
            position: absolute;
            right: 25px;
            top: 20px;
            font-size: 70px;
            font-weight: 900;
            color: #f1f6fc;
            line-height: 1;
        }
        .jf-journey-icon {
            width: 62px;
            height: 62px;
            border-radius: 18px;
            background: #eaf3ff;
            color: var(--jf-blue);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 25px;
            margin-bottom: 25px;
        }
        .jf-journey-card h3 {
            font-size: 25px;
            color: var(--jf-navy);
            margin-bottom: 14px;
        }
        .jf-journey-card > p { color: var(--jf-muted); }
        .jf-benefits {
            list-style: none;
            margin: 25px 0 30px;
        }
        .jf-benefits li {
            display: flex;
            gap: 11px;
            margin-bottom: 12px;
            color: #44556b;
            font-size: 0.9rem;
        }
        .jf-benefits li i { color: var(--jf-success); margin-top: 3px; }

        /* process */
        .jf-process {
            padding: 100px 0;
            background: var(--jf-navy);
            color: #fff;
        }
        .jf-process .eyebrow {
            background: rgba(255,255,255,0.09);
            color: #8ebfff;
        }
        .jf-process .jf-section-heading h2 { color: #fff; }
        .jf-process .jf-section-heading p { color: rgba(255,255,255,0.6); }
        .jf-process-intro {
            max-width: 900px;
            margin: 0 auto 65px;
            padding: 28px 32px;
            border-left: 3px solid var(--jf-blue);
            background: rgba(255,255,255,0.05);
            border-radius: 0 16px 16px 0;
        }
        .jf-process-intro p { color: rgba(255,255,255,0.72); }
        .jf-steps {
            display: grid;
            grid-template-columns: repeat(5,1fr);
            gap: 20px;
        }
        .jf-step-number {
            width: 54px;
            height: 54px;
            border-radius: 50%;
            background: #1769e0;
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: 800;
            font-size: 1rem;
            margin-bottom: 20px;
            box-shadow: 0 0 0 8px rgba(23,105,224,0.12);
        }
        .jf-step h4 { color: #fff; font-size: 1.1rem; margin-bottom: 8px; }
        .jf-step p { color: rgba(255,255,255,0.55); font-size: 0.85rem; }

        /* prefer */
        .jf-prefer {
            padding: 100px 0;
            background: var(--jf-light);
        }
        .jf-prefer-grid {
            display: grid;
            grid-template-columns: repeat(4,1fr);
            gap: 15px;
        }
        .jf-prefer-item {
            background: #fff;
            border: 1px solid var(--jf-border);
            border-radius: 18px;
            padding: 25px 20px;
            min-height: 120px;
            display: flex;
            flex-direction: column;
            justify-content: center;
            gap: 12px;
            transition: 0.2s;
        }
        .jf-prefer-item:hover {
            transform: translateY(-4px);
            box-shadow: 0 15px 35px rgba(17,51,89,0.06);
        }
        .jf-prefer-item i { font-size: 24px; color: var(--jf-blue); }
        .jf-prefer-item span { font-weight: 700; color: var(--jf-navy); }

        /* faq */
        .jf-faq {
            padding: 100px 0;
            background: #fff;
        }
        .jf-faq-layout {
            display: grid;
            grid-template-columns: 0.7fr 1.3fr;
            gap: 70px;
            align-items: start;
        }
        .jf-faq-side h2 {
            font-size: 38px;
            color: var(--jf-navy);
            margin: 14px 0;
        }
        .jf-faq-side p { color: var(--jf-muted); }
        .jf-faq-list {
            display: flex;
            flex-direction: column;
            gap: 12px;
        }
        .jf-faq-item {
            border: 1px solid var(--jf-border);
            border-radius: 15px;
            padding: 20px 23px;
            background: #fff;
        }
        .jf-faq-item h4 {
            display: flex;
            align-items: center;
            gap: 12px;
            color: var(--jf-navy);
            font-size: 1rem;
            margin-bottom: 8px;
        }
        .jf-faq-item h4 i { color: var(--jf-blue); }
        .jf-faq-item p {
            color: var(--jf-muted);
            font-size: 0.9rem;
            line-height: 1.7;
            margin-left: 27px;
        }

        /* final cta */
        .jf-final {
            padding: 100px 0;
            background: #295cab;
            color: #fff;
            text-align: center;
        }
        .jf-final-content .eyebrow {
            background: rgba(255,255,255,0.08);
            color: #86b9ff;
        }
        .jf-final-content h2 {
            font-size: clamp(32px,5vw,52px);
            margin: 16px 0;
        }
        .jf-final-content p { color: rgba(255,255,255,0.7); max-width: 650px; margin: 0 auto; }
        .jf-final-buttons {
            display: flex;
            flex-wrap: wrap;
            justify-content: center;
            gap: 14px;
            margin-top: 30px;
        }
        .jf-final .jf-btn-primary {
            background: #fff;
            color: var(--jf-navy);
            border-color: #fff;
        }
        .jf-final .jf-btn-primary:hover { background: #eaf3ff; }
        .jf-final .jf-btn-outline {
            border-color: rgba(255,255,255,0.25);
            color: #fff;
        }
        .jf-final .jf-btn-outline:hover { background: rgba(255,255,255,0.1); }
        .jf-brand-line {
            margin-top: 40px !important;
            opacity: 0.5;
            font-size: 0.9rem;
        }

        /* ===== RESPONSIVE ===== */
        @media (max-width: 991px) {
            .jf-why-wrap, .jf-faq-layout {
                grid-template-columns: 1fr;
                gap: 45px;
            }
            .jf-steps { grid-template-columns: repeat(2,1fr); }
            .jf-prefer-grid { grid-template-columns: repeat(2,1fr); }
            .jf-faq-side { text-align: center; }
        }
        @media (max-width: 767px) {
            .jf-why, .jf-journey, .jf-process, .jf-prefer, .jf-faq, .jf-final {
                padding: 70px 0;
            }
            .jf-journey-grid { grid-template-columns: 1fr; }
            .jf-why-points { grid-template-columns: 1fr; }
            .jf-steps { grid-template-columns: 1fr; }
            .jf-step {
                display: grid;
                grid-template-columns: 55px 1fr;
                gap: 12px;
            }
            .jf-step-number { grid-row: span 2; margin: 0; }
            .jf-faq-item p { margin-left: 0; margin-top: 8px; }
            .jf-prefer-grid { grid-template-columns: 1fr 1fr; }
            .jf-final-buttons { flex-direction: column; align-items: center; }
            .jf-final-buttons .jf-btn { width: 100%; max-width: 340px; }
        }
        @media (max-width: 480px) {
            .jf-prefer-grid { grid-template-columns: 1fr; }
            .jf-reward-box { padding: 28px; }
            .jf-journey-card { padding: 24px 20px; }
        }

        /* =========================================================
   JFINMATE HERO
   DESKTOP + TABLET + MOBILE
   ========================================================= */

.jf-hero {
    width: 100%;
    margin: 0;
    padding: 0;
    overflow: hidden;
    position: relative;
    background: #eef6ff;
}

.jf-hero-inner {
    width: 100%;
    min-height: 680px;
    height: 680px;

    position: relative;
    overflow: hidden;

    background: #eef6ff;
}


/* =========================================================
   HERO IMAGE
   ========================================================= */

.jf-hero-image {
    position: absolute;

    width: auto;
    height: 100%;

    max-width: none;

    right: 0;
    top: 0;

    object-fit: contain;
    object-position: right center;

    z-index: 1;

    display: block;
}


/* =========================================================
   OVERLAY
   ========================================================= */

.jf-hero-overlay {
    position: absolute;

    left: 0;
    top: 0;
    bottom: 0;

    width: 68%;

    z-index: 2;

    pointer-events: none;

    background: linear-gradient(
        90deg,
        rgba(238,246,255,1) 0%,
        rgba(238,246,255,0.98) 30%,
        rgba(238,246,255,0.85) 52%,
        rgba(238,246,255,0.35) 78%,
        rgba(238,246,255,0) 100%
    );
}


/* =========================================================
   CONTAINER
   ========================================================= */

.jf-hero-container {
    width: 100%;
    max-width: 1200px;

    height: 100%;

    margin: 0 auto;

    padding: 0 25px;

    position: relative;

    z-index: 3;

    box-sizing: border-box;
}


/* =========================================================
   CONTENT
   ========================================================= */

.jf-hero-content {
    width: 55%;
    max-width: 650px;

    height: 100%;

    display: flex;

    flex-direction: column;

    justify-content: center;

    align-items: flex-start;

    text-align: left;
}


/* =========================================================
   INTRO
   ========================================================= */

.jf-hero-intro {
    margin: 0 0 14px;

    color: #295cab;

    font-size: 15px;

    line-height: 1.4;

    font-weight: 800;

    letter-spacing: 2px;

    text-transform: uppercase;
}


/* =========================================================
   HEADING
   ========================================================= */

.jf-hero-content h1 {
    margin: 0 0 20px;

    max-width: 650px;

    color: #101828;

    font-size: clamp(42px, 5vw, 68px);

    line-height: 1.08;

    font-weight: 800;

    letter-spacing: -1.5px;
}

.jf-hero-content h1 span {
    color: #295cab;
}


/* =========================================================
   DESCRIPTION
   ========================================================= */

.jf-hero-content p {
    margin: 0 0 30px;

    max-width: 600px;

    color: #4a5568;

    font-size: 17px;

    line-height: 1.7;
}


/* =========================================================
   BUTTONS
   ========================================================= */

.jf-hero-buttons {
    display: flex;

    align-items: center;

    justify-content: flex-start;

    gap: 14px;

    flex-wrap: wrap;
}


.jf-btn {
    min-height: 52px;

    padding: 13px 27px;

    display: inline-flex;

    align-items: center;

    justify-content: center;

    border-radius: 10px;

    text-decoration: none;

    font-size: 15px;

    font-weight: 700;

    line-height: 1.2;

    box-sizing: border-box;

    transition: all 0.25s ease;
}


/* PRIMARY BUTTON */

.jf-btn-primary {
    color: #ffffff;

    background:#1e4fd8;;

    border: 2px solid #4d62d8;
}

.jf-btn-primary:hover {
    color: #ffffff;

    background: #354bc5;

    border-color: #354bc5;

    transform: translateY(-2px);
}


/* OUTLINE BUTTON */

.jf-btn-outline {
    color:#ffff;

    background:#1e4fd8;

    border: 2px solid #4d62d8;
}

.jf-btn-outline:hover {
    color: #ffffff;

    background: #4d62d8;

    transform: translateY(-2px);
}


/* =========================================================
   TABLET
   ========================================================= */

@media (max-width: 991px) {

    .jf-hero-inner {
        height: 620px;

        min-height: 620px;
    }

    .jf-hero-image {
        height: 100%;

        right: -40px;
    }

    .jf-hero-overlay {
        width: 72%;
    }

    .jf-hero-container {
        padding: 0 25px;
    }

    .jf-hero-content {
        width: 60%;
    }

    .jf-hero-content h1 {
        font-size: 48px;
    }

    .jf-hero-content p {
        font-size: 15px;

        max-width: 520px;
    }

    .jf-btn {
        padding: 12px 22px;

        font-size: 14px;
    }
}


/* =========================================================
   MOBILE
   ========================================================= */

/* =========================================================
   JFINMATE HERO - MOBILE FINAL
   ========================================================= */

@media (max-width: 767px) {

    .jf-hero {
        width: 100%;
        margin: 0;
        padding: 0;
        overflow: hidden;
    }

    .jf-hero-inner {
        width: 100%;
        height: 650px;
        min-height: 650px;
        position: relative;
        overflow: hidden;
        background: #eef6ff;
    }


    /* =====================================================
       IMAGE
       ===================================================== */

    .jf-hero-image {
        position: absolute;

        height: 100%;
        width: auto;
        max-width: none;

        top: 0;

        /*
         * Keep image on right.
         */
        right: -85px;

        object-fit: contain;
        object-position: right center;

        z-index: 1;

        display: block;
    }


    /* =====================================================
       IMAGE OVERLAY
       ===================================================== */

    .jf-hero-overlay {
        position: absolute;

        top: 0;
        left: 0;

        width: 100%;
        height: 100%;

        z-index: 2;

        pointer-events: none;

        background: linear-gradient(
            90deg,
            rgba(238,246,255,0.99) 0%,
            rgba(238,246,255,0.97) 32%,
            rgba(238,246,255,0.82) 48%,
            rgba(238,246,255,0.45) 65%,
            rgba(238,246,255,0.08) 100%
        );
    }


    /* =====================================================
       CONTAINER
       ===================================================== */

    .jf-hero-container {
        width: 100%;
        height: 100%;

        margin: 0;
        padding: 0 5px;

        position: relative;
        z-index: 3;

        box-sizing: border-box;
    }


    /* =====================================================
       CONTENT
       ===================================================== */

    .jf-hero-content {

        width: 68%;
        max-width: 345px;

        height: 100%;

        margin: 0;

        display: flex;
        flex-direction: column;

        justify-content: center;
        align-items: flex-start;

        text-align: left;
    }


    /* =====================================================
       INTRO
       ===================================================== */

    .jf-hero-intro {

        width: 100%;

        margin: 0 0 13px;

        font-size: 11px;
        line-height: 1.4;

        letter-spacing: 1.4px;

        color: #295cab;

        font-weight: 800;

        white-space: nowrap;
    }


    /* =====================================================
       HEADING
       ===================================================== */

    .jf-hero-content h1 {

        width: 100%;
        max-width: 340px;

        margin: 0 0 18px;

        font-size: 30px;
        line-height: 1.13;

        letter-spacing: -0.5px;

        color: #101828;
    }

    .jf-hero-content h1 span {
        color: #295cab !important;
    }


    /* =====================================================
       DESCRIPTION
       ===================================================== */

    .jf-hero-content p {

        width: 100%;
        max-width: 335px;

        margin: 0 0 25px;

        font-size: 13px;
        line-height: 1.65;

        color: #526174;
    }


    /* =====================================================
       BUTTON AREA
       ===================================================== */

    .jf-hero-buttons {

        width: 100%;
        max-width: 285px;

        display: flex;

        flex-direction: column;

        align-items: stretch;

        gap: 10px;
    }


    /* =====================================================
       BUTTON
       ===================================================== */

    .jf-btn {

        width: 100%;

        min-height: 52px;

        padding: 12px 10px;

        display: flex;

        align-items: center;
        justify-content: center;

        box-sizing: border-box;

        border-radius: 10px;

        font-size: 14px;

        line-height: 1.25;

        text-align: center;
    }


    .jf-btn-primary {

        background: #4d62d8;

        color: #ffffff;

        border: 2px solid #4d62d8;
    }


    .jf-btn-outline {

        background:#1e4fd8;;

        color: #fff;

        border: 2px solid #4d62d8;
    }
}


