}


/* =========================================================
   SMALL MOBILE
   ========================================================= */

@media (max-width: 480px) {

    .jf-hero-inner {

        height: 590px;

        min-height: 590px;
    }


    .jf-hero-image {

        height: 590px;

        right: -65px;
    }


    .jf-hero-content {

        width: 68%;

