/* =========================================
   JFINMATE DIFFERENCE SECTION
========================================= */

.jfm-difference-section {
    width: 100%;
    margin: 0;
    padding: 52px 24px 0;
    background: #fbfcfe;
    box-sizing: border-box;
    font-family: Arial, Helvetica, sans-serif;
    overflow: hidden;
}

.jfm-difference-section *,
.jfm-difference-section *::before,
.jfm-difference-section *::after {
    box-sizing: border-box;
}

.jfm-difference-container {
    width: 100%;
    max-width: 1240px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: 0.94fr 1.25fr;
    align-items: start;
    gap: 42px;
}

/* LEFT CONTENT */

.jfm-difference-content {
    min-width: 0;
    padding-top: 1px;
}

.jfm-difference-label {
    display: block;
    margin-bottom: 7px;
    color: #2874ff;
    font-size: 16px;
    font-weight: 400;
    line-height: 1.4;
}

.jfm-difference-content h2 {
    margin: 0 0 10px;
    color: #373737;
    font-size: 18px;
    font-weight: 700;
    line-height: 1.28;
    letter-spacing: -0.2px;
}

.jfm-difference-description {
    margin: 0 0 10px;
    color: #777777;
    font-size: 14px;
    font-weight: 400;
    line-height: 1.55;
}

.jfm-benefits-list {
    display: flex;
    flex-direction: column;
    gap: 10px;
    margin: 0;
    padding: 0;
    list-style: none;
}

.jfm-benefits-list li {
    display: flex;
    align-items: center;
    gap: 9px;
    min-height: 31px;
    color: #353535;
    font-size: 14px;
    line-height: 1.4;
}

.jfm-check-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: 0 0 26px;
    width: 26px;
    height: 26px;
    border-radius: 4px;
    background: #e3edff;
    color: #2874ff;
    font-size: 15px;
    font-weight: 600;
}

/* RIGHT SIDE CARDS */

.jfm-difference-cards {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    align-items: stretch;
    gap: 12px;
    min-width: 0;
}

.jfm-difference-card {
    min-width: 0;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    background: #ffffff;
    border: 1px solid #f0f1f3;
    border-radius: 12px;
    box-shadow: 0 2px 7px rgba(0, 0, 0, 0.07);
}

.jfm-card-image {
    width: 100%;
    height: 174px;
    flex-shrink: 0;
    overflow: hidden;
    background: #edf3f9;
}

.jfm-card-image img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
    transition: transform 0.35s ease;
}

.jfm-difference-card:hover .jfm-card-image img {
    transform: scale(1.035);
}

/* CARD BODY */

.jfm-card-body {
    display: flex;
    flex: 1;
    flex-direction: column;
    align-items: stretch;
    padding: 10px 16px 18px;
}

.jfm-card-body h3 {
    margin: 0 0 7px;
    color: #393939;
    font-size: 16px;
    font-weight: 700;
    line-height: 1.3;
    letter-spacing: -0.2px;
}

.jfm-card-body h3 span {
    color: #2874ff;
}

.jfm-card-body p {
    margin: 0 0 14px;
    color: #777777;
    font-size: 14px;
    font-weight: 400;
    line-height: 1.5;
}

.jfm-card-button {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    width: 100%;
    min-height: 31px;
    margin-top: auto;
    padding: 6px 10px;
    border: 1px solid #4b83ff;
    border-radius: 5px;
    background: #ffffff;
    color: #2874ff;
    font-size: 14px;
    font-weight: 400;
    line-height: 1.3;
    text-align: center;
    text-decoration: none;
    transition: background 0.25s ease, color 0.25s ease;
}

.jfm-card-button:hover,
.jfm-card-button:focus-visible {
    background: #2874ff;
    color: #ffffff;
}

.jfm-card-arrow {
    font-size: 15px;
    line-height: 1;
    transition: transform 0.25s ease;
}

.jfm-card-button:hover .jfm-card-arrow {
    transform: translateX(3px);
}

/* BOTTOM FOOTER STRIP */

.jfm-difference-footer {
    width: calc(100% + 48px);
    min-height: 60px;
    margin: 48px -24px 0;
    padding: 22px 12px 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #eff6ff;
    color: #2874ff;
    font-size: 16px;
    font-weight: 400;
    text-align: center;
}

/* =========================================
   LARGE LAPTOPS
========================================= */

@media (min-width: 1400px) {
    .jfm-difference-container {
        max-width: 1280px;
        gap: 55px;
    }

    .jfm-card-image {
        height: 195px;
    }
}

/* =========================================
   TABLETS
========================================= */

@media (max-width: 991px) {
    .jfm-difference-section {
        padding: 38px 20px 0;
    }

    .jfm-difference-container {
        grid-template-columns: 1fr;
        gap: 28px;
    }

    .jfm-difference-content {
        max-width: 650px;
    }

    .jfm-difference-content h2 {
        font-size: 22px;
    }

    .jfm-difference-description {
        font-size: 13px;
    }

    .jfm-benefits-list {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 12px;
    }

    .jfm-benefits-list li {
        font-size: 12px;
    }

    .jfm-difference-cards {
        gap: 18px;
    }

    .jfm-card-image {
        height: 220px;
    }

    .jfm-card-body {
        padding: 14px 16px 18px;
    }

    .jfm-card-body h3 {
        font-size: 18px;
    }

    .jfm-card-body p {
        font-size: 12px;
    }

    .jfm-card-button {
        min-height: 38px;
        font-size: 12px;
    }

    .jfm-difference-footer {
        width: calc(100% + 40px);
        margin: 35px -20px 0;
    }
}

/* =========================================
   MOBILE PHONES
========================================= */

@media (max-width: 576px) {
    .jfm-difference-section {
        padding: 30px 16px 0;
    }

    .jfm-difference-container {
        grid-template-columns: minmax(0, 1fr);
        gap: 25px;
    }

    .jfm-difference-label {
        font-size: 11px;
        margin-bottom: 8px;
    }

    .jfm-difference-content h2 {
        font-size: 21px;
        line-height: 1.35;
        margin-bottom: 10px;
    }

    .jfm-difference-description {
        font-size: 12px;
        line-height: 1.65;
        margin-bottom: 15px;
    }

    .jfm-benefits-list {
        grid-template-columns: minmax(0, 1fr);
        gap: 10px;
    }

    .jfm-benefits-list li {
        gap: 10px;
        min-height: 32px;
        font-size: 12px;
    }

    .jfm-check-icon {
        flex-basis: 29px;
        width: 29px;
        height: 29px;
        font-size: 16px;
    }

    .jfm-difference-cards {
        grid-template-columns: minmax(0, 1fr);
        gap: 18px;
    }

    .jfm-difference-card {
        width: 100%;
        border-radius: 12px;
    }

    .jfm-card-image {
        height: 210px;
    }

    .jfm-card-body {
        padding: 15px 15px 17px;
    }

    .jfm-card-body h3 {
        font-size: 18px;
        line-height: 1.4;
        margin-bottom: 7px;
    }

    .jfm-card-body p {
        font-size: 12px;
        line-height: 1.6;
        margin-bottom: 14px;
    }

    .jfm-card-button {
        min-height: 42px;
        font-size: 12px;
    }

    .jfm-difference-footer {
        width: calc(100% + 32px);
        min-height: 55px;
        margin: 30px -16px 0;
        padding: 18px 10px;
        font-size: 11px;
    }
}

/* =========================================
   SMALL IPHONES
========================================= */

@media (max-width: 360px) {
    .jfm-difference-section {
        padding-right: 12px;
        padding-left: 12px;
    }

    .jfm-difference-content h2 {
        font-size: 19px;
    }

    .jfm-card-image {
        height: 180px;
    }

    .jfm-card-body h3 {
        font-size: 16px;
    }

    .jfm-difference-footer {
        width: calc(100% + 24px);
        margin-right: -12px;
        margin-left: -12px;
    }
}


/* ==========================================
   JFINMATE REWARDS SECTION
========================================== */

.jfm-rewards-section {
    width: 100%;
    margin: 0;
    padding: 38px 24px 44px;
    background: #f0f6fd;
    font-family: Arial, Helvetica, sans-serif;
    box-sizing: border-box;
    overflow: hidden;
}

.jfm-rewards-section *,
.jfm-rewards-section *::before,
.jfm-rewards-section *::after {
    box-sizing: border-box;
}

.jfm-rewards-container {
    width: 100%;
    max-width: 1250px;
    margin: 0 auto;
}

/* HEADING */

.jfm-rewards-heading {
    text-align: center;
    margin: 0 auto 43px;
}

.jfm-rewards-eyebrow {
    display: block;
    color: #2874f0;
    font-size: 16px;
    line-height: 1.5;
    margin-bottom: 5px;
}

.jfm-rewards-heading h2 {
    margin: 0 0 5px;
    color: #373737;
    font-size: 20px;
    font-weight: 700;
    line-height: 1.35;
}

.jfm-rewards-heading p {
    margin: 0;
    color: #777777;
    font-size: 12px;
    line-height: 1.5;
}

/* STEPS GRID */

.jfm-rewards-steps {
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    gap: 20px;
    align-items: start;
    margin-bottom: 43px;
}

.jfm-reward-step {
    min-width: 0;
    text-align: center;
    display: flex;
    flex-direction: column;
    align-items: center;
}

.jfm-reward-icon {
    width: 39px;
    height: 39px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 0 13px;
    border-radius: 3px;
    background: #2874e8;
    color: #ffffff;
    font-size: 15px;
}

.jfm-reward-step h3 {
    margin: 0 0 10px;
    color: #393939;
    font-size: 13px;
    font-weight: 700;
    line-height: 1.2;
}

.jfm-reward-step h4 {
    min-height: 15px;
    margin: 0 0 5px;
    color: #171717;
    font-size: 16px;
    font-weight: 500;
    line-height: 1.35;
}

.jfm-reward-step p {
    max-width: 190px;
    margin: 0;
    color: #777777;
    font-size: 14px;
    font-weight: 400;
    line-height: 1.45;
}

/* REFERRAL BANNER */

.jfm-referral-banner {
    display: flex;
    align-items: center;
    gap: 22px;
    width: 100%;
    min-height: 78px;
    padding: 15px 17px;
    border-radius: 7px;
    background: #e4efff;
}

.jfm-referral-gift {
    width: 39px;
    height: 39px;
    flex: 0 0 39px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 4px;
    background: #2874e8;
    color: #ffffff;
    font-size: 22px;
}

.jfm-referral-content {
    flex: 1;
    min-width: 0;
}

.jfm-referral-content h3 {
    margin: 0 0 4px;
    color: #3b3b3b;
    font-size: 20px;
    font-weight: 700;
    line-height: 1.4;
}

.jfm-referral-content p {
    max-width: 460px;
    margin: 0;
    color: #777777;
    font-size: 14px;
    font-weight: 400;
    line-height: 1.5;
}

.jfm-referral-button {
    min-width: 144px;
    min-height: 43px;
    padding: 8px 13px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    flex-shrink: 0;
    border: 1px solid #2874e8;
    border-radius: 4px;
    background: #2874e8;
    color: #ffffff !important;
    font-size: 14px;
    line-height: 1.3;
    text-decoration: none;
    transition: background 0.25s ease;
}

.jfm-referral-button:hover {
    background: #185ac4;
    border-color: #185ac4;
    color: #ffffff !important;
}

.jfm-referral-button i {
    font-size: 11px;
    transition: transform 0.25s ease;
}

.jfm-referral-button:hover i {
    transform: translateX(3px);
}

/* ==========================================
   LAPTOP
========================================== */

@media (min-width: 1200px) {
    .jfm-rewards-section {
        padding-right: 30px;
        padding-left: 30px;
    }

    .jfm-rewards-steps {
        gap: 28px;
    }
}

/* ==========================================
   TABLET
========================================== */

@media (max-width: 991px) {
    .jfm-rewards-section {
        padding: 35px 20px;
    }

    .jfm-rewards-steps {
        grid-template-columns: repeat(3, minmax(0, 1fr));
        column-gap: 20px;
        row-gap: 30px;
        margin-bottom: 35px;
    }

    .jfm-reward-step h4 {
        font-size: 12px;
    }

    .jfm-reward-step p {
        font-size: 11px;
    }

    .jfm-referral-banner {
        gap: 14px;
    }
}

/* ==========================================
   MOBILE
========================================== */

@media (max-width: 576px) {
    .jfm-rewards-section {
        padding: 30px 16px 28px;
    }

    .jfm-rewards-heading {
        margin-bottom: 30px;
    }

    .jfm-rewards-heading h2 {
        font-size: 21px;
    }

    .jfm-rewards-heading p {
        max-width: 340px;
        margin: 0 auto;
        font-size: 12px;
        line-height: 1.6;
    }

    .jfm-rewards-eyebrow {
        font-size: 11px;
    }

    .jfm-rewards-steps {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        column-gap: 18px;
        row-gap: 28px;
        margin-bottom: 30px;
    }

    .jfm-reward-icon {
        width: 34px;
        height: 34px;
        margin-bottom: 10px;
        font-size: 17px;
    }

    .jfm-reward-step h3 {
        margin-bottom: 7px;
        font-size: 14px;
    }

    .jfm-reward-step h4 {
        min-height: 0;
        margin-bottom: 6px;
        font-size: 12px;
        line-height: 1.4;
    }

    .jfm-reward-step p {
        max-width: 230px;
        font-size: 11px;
        line-height: 1.55;
    }

    /* Banner stacks cleanly on phones */
    .jfm-referral-banner {
        display: grid;
        grid-template-columns: 40px minmax(0, 1fr);
        align-items: center;
        gap: 12px;
        padding: 16px 13px;
    }

    .jfm-referral-gift {
        width: 38px;
        height: 38px;
        font-size: 20px;
    }

    .jfm-referral-content h3 {
        font-size: 12px;
    }

    .jfm-referral-content p {
        font-size: 10.5px;
        line-height: 1.55;
    }

    .jfm-referral-button {
        grid-column: 1 / -1;
        width: 100%;
        min-height: 42px;
        font-size: 12px;
    }
}

/* ==========================================
   VERY SMALL PHONES
========================================== */

@media (max-width: 360px) {
    .jfm-rewards-section {
        padding-right: 12px;
        padding-left: 12px;
    }

    .jfm-rewards-steps {
        column-gap: 12px;
    }

    .jfm-reward-step h4 {
        font-size: 11px;
    }

    .jfm-reward-step p {
        font-size: 10px;
    }

    .jfm-referral-banner {
        padding: 13px 10px;
    }
}

/* =====================================
   WHY CUSTOMERS PREFER JFINMATE
===================================== */

.jfm-why-section {
    width: 100%;
    padding: 50px 24px 48px;
    margin: 0;
    background: #fbfcfe;
    font-family: Arial, Helvetica, sans-serif;
    box-sizing: border-box;
    overflow: hidden;
}

.jfm-why-section *,
.jfm-why-section *::before,
.jfm-why-section *::after {
    box-sizing: border-box;
}

.jfm-why-container {
    width: 100%;
    max-width: 1240px;
    margin: 0 auto;
}

/* HEADING */

.jfm-why-heading {
    text-align: center;
    margin-bottom: 32px;
}

.jfm-why-heading > span {
    display: block;
    color: #2874ff;
    font-size: 16px;
    line-height: 1.5;
    margin-bottom: 5px;
}

.jfm-why-heading h2 {
    margin: 0 0 5px;
    color: #383838;
    font-size: 30px;
    font-weight: 700;
    line-height: 1.35;
}

.jfm-why-heading p {
    margin: 0;
    color: #777;
    font-size: 14px;
    line-height: 1.5;
}

/* GRID */

.jfm-why-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    column-gap: 22px;
    row-gap: 32px;
    align-items: start;
}

/* CARD */

.jfm-why-card {
    min-width: 0;
    width: 100%;
    background: transparent;
    border: none;
    border-radius: 0;
    overflow: hidden;
}

/* IMAGE */

.jfm-why-image {
    width: 100%;
    height: 195px;
    overflow: hidden;
    border-radius: 9px 9px 0 0;
    background: #edf2f7;
}

.jfm-why-image img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
    transition: transform 0.3s ease;
}

.jfm-why-card:hover .jfm-why-image img {
    transform: scale(1.025);
}

/* CARD TEXT */

.jfm-why-card-content {
    padding: 9px 11px 0;
}

.jfm-why-card-content h3 {
    margin: 0 0 7px;
    color: #3b3b3b;
    font-size: 16px;
    font-weight: 700;
    line-height: 1.35;
}

.jfm-why-card-content p {
    margin: 0;
    color: #777;
    font-size: 11px;
    font-weight: 400;
    line-height: 1.5;
}

/* =====================================
   TABLETS
===================================== */

@media (max-width: 991px) {
    .jfm-why-section {
        padding: 40px 20px;
    }

    .jfm-why-grid {
        column-gap: 18px;
        row-gap: 28px;
    }

    .jfm-why-image {
        height: 165px;
    }

    .jfm-why-card-content {
        padding: 9px 5px 0;
    }

    .jfm-why-card-content h3 {
        font-size: 14px;
    }

    .jfm-why-card-content p {
        font-size: 11px;
    }
}

/* =====================================
   MOBILE
===================================== */

@media (max-width: 600px) {
    .jfm-why-section {
        padding: 32px 16px 35px;
    }

    .jfm-why-heading {
        margin-bottom: 25px;
    }

    .jfm-why-heading h2 {
        font-size: 20px;
        line-height: 1.35;
    }

    .jfm-why-heading p {
        max-width: 340px;
        margin: 0 auto;
        font-size: 12px;
    }

    .jfm-why-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        column-gap: 14px;
        row-gap: 25px;
    }

    .jfm-why-image {
        height: 135px;
        border-radius: 7px 7px 0 0;
    }

    .jfm-why-card-content {
        padding: 8px 2px 0;
    }

    .jfm-why-card-content h3 {
        margin-bottom: 5px;
        font-size: 13px;
        line-height: 1.4;
    }

    .jfm-why-card-content p {
        font-size: 11px;
        line-height: 1.5;
    }
}

/* SMALL PHONES */

@media (max-width: 380px) {
    .jfm-why-section {
        padding-right: 12px;
        padding-left: 12px;
    }

    .jfm-why-grid {
        column-gap: 12px;
        row-gap: 22px;
    }

    .jfm-why-image {
        height: 115px;
    }

    .jfm-why-card-content h3 {
        font-size: 12px;
    }

    .jfm-why-card-content p {
        font-size: 10px;
    }
}



/* =========================================
   WHY CUSTOMERS PREFER JFINMATE
========================================= */

.jf-prefer {
    width: 100%;
    padding: 80px 20px;
    background: #f7f9fc;
    overflow: hidden;
}

.jf-prefer .jf-container {
    width: 100%;
    max-width: 1200px;
    margin: 0 auto;
}


/* =========================================
   SECTION HEADING
========================================= */

.jf-prefer .jf-section-heading {
    text-align: center;
    max-width: 750px;
    margin: 0 auto 45px;
}

.jf-prefer .eyebrow {
    display: inline-block;
    margin-bottom: 10px;

    font-size: 14px;
    font-weight: 700;
    letter-spacing: 1.5px;
    text-transform: uppercase;

    color:#1e4fd8;
   
}

.jf-prefer .jf-section-heading h2 {
    margin: 0 0 12px;

    font-size: 38px;
    line-height: 1.2;
    font-weight: 700;

    color: #172b4d;
}

.jf-prefer .jf-section-heading p {
    margin: 0;

    font-size: 17px;
    line-height: 1.6;

    color: #667085;
}


/* =========================================
   CARD GRID
========================================= */

.jf-prefer-grid {
    display: grid;

    grid-template-columns: repeat(4, minmax(0, 1fr));

    gap: 24px;

    width: 100%;
}


/* =========================================
   CARD
========================================= */

.jf-prefer-card {
    width: 100%;
    min-width: 0;

    background: #ffffff;

    border-radius: 18px;

    overflow: hidden;

    border: 1px solid #e8ecf2;

    box-shadow: 0 8px 30px rgba(20, 40, 70, 0.07);

    transition:
        transform 0.3s ease,
        box-shadow 0.3s ease;
}

.jf-prefer-card:hover {
    transform: translateY(-7px);

    box-shadow: 0 16px 40px rgba(20, 40, 70, 0.13);
}


/* =========================================
   IMAGE
========================================= */

.jf-prefer-image {
    width: 100%;
    height: 190px;

    overflow: hidden;

    background: #e9edf3;
}

.jf-prefer-image img {
    display: block;

    width: 100%;
    height: 100%;

    object-fit: cover;

    transition: transform 0.5s ease;
}

.jf-prefer-card:hover .jf-prefer-image img {
    transform: scale(1.06);
}


/* =========================================
   CARD CONTENT
========================================= */

.jf-prefer-content {
    padding: 22px 20px 24px;

    text-align: center;
}

.jf-prefer-content h3 {
    margin: 0 0 10px;

    font-size: 18px;
    line-height: 1.35;
    font-weight: 700;

    color: #172b4d;
}

.jf-prefer-content p {
    margin: 0;

    font-size: 14px;
    line-height: 1.6;

    color: #667085;
}


/* =========================================
   TABLET
========================================= */

@media (max-width: 1100px) {

    .jf-prefer {
        padding: 70px 20px;
    }

    .jf-prefer-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 20px;
    }

    .jf-prefer-image {
        height: 180px;
    }

    .jf-prefer .jf-section-heading h2 {
        font-size: 34px;
    }
}


/* =========================================
   SMALL TABLET
========================================= */

@media (max-width: 768px) {

    .jf-prefer {
        padding: 55px 16px;
    }

    .jf-prefer .jf-section-heading {
        margin-bottom: 30px;
    }

    .jf-prefer .jf-section-heading h2 {
        font-size: 29px;
    }

    .jf-prefer .jf-section-heading p {
        font-size: 15px;
    }

    .jf-prefer-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 16px;
    }

    .jf-prefer-image {
        height: 165px;
    }

    .jf-prefer-content {
        padding: 18px 15px 20px;
    }

    .jf-prefer-content h3 {
        font-size: 16px;
    }

    .jf-prefer-content p {
        font-size: 13px;
    }
}
  
        /* =========================================================
   JFINSERV HERO - CLEAN VERSION
   ========================================================= */

.jfinHero,
.jfinHero * {
    box-sizing: border-box;
}


/* =========================================================
   HERO
   ========================================================= */

.jfinHero {
    position: relative;

    width: 100%;
    height: 570px;

    overflow: hidden;

    margin: 0;
    padding: 0;

    background: #eef7ff;
}


/* =========================================================
   SLIDER
   ========================================================= */

.jfinHeroSlider {
    position: relative;

    width: 100%;
    height: 100%;
}


/* =========================================================
   SLIDE
   ========================================================= */

.jfinHeroSlide {
    position: absolute;

    inset: 0;

    width: 100%;
    height: 100%;

    background-repeat: no-repeat;

    background-size: cover;
    background-position: center center;

    opacity: 0;
    visibility: hidden;

    transition:
        opacity .7s ease,
        visibility .7s ease;

    z-index: 1;
}


/* Active */

.jfinHeroSlideActive {
    opacity: 1;

    visibility: visible;

    z-index: 2;
}


/* =========================================================
   SLIDE IMAGE POSITIONS - DESKTOP
   ========================================================= */

.jfinHeroSlide:nth-child(1) {
    background-position: center center;
}

.jfinHeroSlide:nth-child(2) {
    background-position: right center;
}


/* =========================================================
   CONTENT
   ========================================================= */

.jfinHeroContent {
    position: relative;

    width: 100%;
    max-width: 1350px;

    height: 100%;

    margin: 0 auto;

    padding: 0 70px;

    display: flex;

    align-items: center;

    justify-content: flex-start;

    z-index: 10;
}


/* =========================================================
   TEXT
   ========================================================= */

.jfinHeroText {
    position: relative;

    width: 52%;
    max-width: 650px;

    z-index: 20;
}


/* =========================================================
   LABEL
   ========================================================= */

.jfinHeroLabel {
    margin-bottom: 15px;

    color: #ed1c24;

    font-size: 13px;
    font-weight: 700;

    line-height: 1.3;

    letter-spacing: 4px;

    text-transform: uppercase;
}


/* =========================================================
   TITLE
   ========================================================= */

.jfinHeroTitle {
    margin: 0 0 18px;

    color: #295cab;

    font-size: 48px;
    font-weight: 800;

    line-height: 1.12;

    letter-spacing: -.5px;
}


.jfinHeroTitle span {
    color: #009fe3;
}


/* =========================================================
   DESCRIPTION
   ========================================================= */

.jfinHeroDescription {
    max-width: 570px;

    margin: 0 0 28px;

    color: #333;

    font-size: 16px;

    line-height: 1.6;
}


/* =========================================================
   BUTTONS
   ========================================================= */

.jfinHeroButtons {
    display: flex;

    align-items: center;

    gap: 12px;
}


.jfinHeroBtn {
    min-width: 130px;

    height: 48px;

    padding: 0 25px;

    display: inline-flex;

    align-items: center;
    justify-content: center;

    border-radius: 30px;

    font-size: 15px;
    font-weight: 700;

    text-decoration: none;

    transition: .25s ease;
}


/* Apply */

.jfinHeroApply {
    color: #fff;

    background: #2858d7;

    border: 2px solid #2858d7;

    box-shadow: 0 8px 20px rgba(40,88,215,.25);
}


/* Login */

.jfinHeroLogin {
    color: #fff;

    background: #ed1c24;

    border: 2px solid #ed1c24;

    box-shadow: 0 8px 20px rgba(237,28,36,.22);
}


/* =========================================================
   ARROWS
   ========================================================= */

.jfinHeroNavigation {
    position: absolute;

    right: 35px;
    bottom: 30px;

    display: flex;

    gap: 10px;

    z-index: 100;
}


.jfinHeroArrow {
    width: 48px;
    height: 48px;

    border: 0;

    border-radius: 50%;

    display: flex;

    align-items: center;
    justify-content: center;

    color: #444;

    background: rgba(255,255,255,.95);

    cursor: pointer;

    font-size: 15px;

    box-shadow: 0 5px 15px rgba(0,0,0,.12);
}

