/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 767px) {

    .jfinHero {
        position: relative;

        width: 100%;

        /*
         * Banner starts normally.
         * No negative margin.
         * No transform.
         */
        height: 225px !important;
        min-height: 225px !important;

        margin: 0 !important;
        padding: 0 !important;

        overflow: hidden !important;
    }


    .jfinHeroSlider {
        width: 100%;
        height: 100%;
    }


    /* =====================================================
       MOBILE SLIDE
       ===================================================== */

    .jfinHeroSlide {
        position: absolute;

        inset: 0;

        width: 100%;
        height: 100%;

        /*
         * VERY IMPORTANT
         */
        background-size: auto 100% !important;

        background-repeat: no-repeat !important;

        background-position: right center !important;

        opacity: 0;

        visibility: hidden;

        transform: none !important;
    }


    .jfinHeroSlideActive {
        opacity: 1;

        visibility: visible;
    }


    /* Slide 1 */

    .jfinHeroSlide:nth-child(1) {
        background-position: right center !important;
    }


    /* Slide 2 */

    .jfinHeroSlide:nth-child(2) {
        background-position: right center !important;
    }


    /* =====================================================
       CONTENT
       ===================================================== */

    .jfinHeroContent {
        position: relative;

        width: 100%;
        height: 100%;

        margin: 0;
        padding: 16px 12px 10px !important;

        display: block !important;

        z-index: 10;
    }


    /* =====================================================
       TEXT AREA
       ===================================================== */

    .jfinHeroText {
        position: relative;

        width: 54% !important;

        max-width: 210px !important;

        margin: 0 !important;

        padding: 0 !important;

        z-index: 30;
    }


    /* =====================================================
       LABEL
       ===================================================== */

    .jfinHeroLabel {
        margin: 0 0 5px;

        color: #ed1c24;

        font-size: 7px;

        font-weight: 700;

        line-height: 1.25;

        letter-spacing: 2px;
    }


    /* =====================================================
       TITLE
       ===================================================== */

    .jfinHeroTitle {
        position: relative;

        margin: 0 0 6px;

        padding: 0;

        color: #295cab;

        font-size: 18px !important;

        font-weight: 800;

        line-height: 1.08 !important;

        letter-spacing: 0;

        /*
         * Prevent clipping
         */
        top: auto !important;
        left: auto !important;
        right: auto !important;
        bottom: auto !important;

        transform: none !important;
    }


    .jfinHeroTitle span {
        color: #009fe3;
    }


    /* =====================================================
       DESCRIPTION
       ===================================================== */

    .jfinHeroDescription {
        width: 100%;

        max-width: 200px;

        margin: 0 0 10px;

        padding: 0;

        color: #333;

        font-size: 7.5px;

        line-height: 1.35;

        display: -webkit-box;

        -webkit-line-clamp: 3;

        -webkit-box-orient: vertical;

        overflow: hidden;
    }


    /* =====================================================
       BUTTONS
       ===================================================== */

    .jfinHeroButtons {
        display: flex;

        align-items: center;

        gap: 7px;

        margin: 0;

        padding: 0;

        position: relative;

        z-index: 40;
    }


    .jfinHeroBtn {
        width: 94px;

        min-width: 94px;

        height: 40px;

        padding: 0 5px;

        border-radius: 25px;

        font-size: 11px;

        white-space: nowrap;
    }


    /* =====================================================
       MOBILE ARROWS
       ===================================================== */

    .jfinHeroNavigation {
        position: absolute;

        right: 10px;

        bottom: 9px;

        display: flex;

        gap: 8px;

        z-index: 100;
    }


    .jfinHeroArrow {
        width: 38px;

        height: 38px;

        font-size: 12px;
    }

}


