/* ==========================================
   JFINMATE FAQ SECTION
========================================== */

.jf-faq {
    width: 100%;
    padding: 30px 24px 24px;
    margin: 0;
    background: #ffffff;
    font-family: Arial, Helvetica, sans-serif;
    box-sizing: border-box;
}

.jf-faq *,
.jf-faq *::before,
.jf-faq *::after {
    box-sizing: border-box;
}

.jf-faq .jf-container {
    width: 100%;
    max-width: 1000px;
    margin: 0 auto;
}

/* Heading */

.jf-faq-heading {
    text-align: center;
    margin: 0 0 34px;
}

.jf-faq-heading h2 {
    margin: 0 0 5px;
    color: #2874f0;
    font-size: 30px;
    font-weight: 600;
    line-height: 1.35;
}

.jf-faq-heading p {
    margin: 0;
    color: #555555;
    font-size: 14px;
    font-weight: 400;
    line-height: 1.5;
}

/* FAQ list */

.jf-faq-list {
    width: 100%;
    max-width: 770px;
    margin: 0 auto;
}

.jf-faq-item {
    width: 100%;
    margin: 0;
    border: 0;
    border-bottom: 1px solid transparent;
    background: transparent;
}

/* Question row */

.jf-faq-question {
    width: 100%;
    min-height: 51px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    padding: 12px 4px;

    border: 0;
    border-radius: 0;
    outline: none;
    background: transparent;

    color: #333333;
    font-family: inherit;
    font-size: 16px;
    font-weight: 600;
    line-height: 1.45;
    text-align: left;

    cursor: pointer;
    appearance: none;
    -webkit-appearance: none;
}

.jf-faq-question > span:first-child {
    flex: 1;
    min-width: 0;
}

/* Plus / minus icon */

.jf-faq-toggle {
    flex: 0 0 20px;
    width: 20px;
    height: 20px;
    display: flex;
    align-items: center;
    justify-content: center;

    color: #333333;
    font-family: Arial, sans-serif;
    font-size: 21px;
    font-weight: 400;
    line-height: 1;

    transition: transform 0.2s ease;
}

/* Answer */

.jf-faq-answer {
    display: none;
    padding: 0 30px 15px 4px;
}

.jf-faq-answer p {
    margin: 0;
    color: #6b6b6b;
    font-size: 12px;
    font-weight: 400;
    line-height: 1.7;
}

/* Open item */

.jf-faq-item.active .jf-faq-answer {
    display: block;
}

.jf-faq-item.active .jf-faq-toggle {
    transform: rotate(45deg);
}

.jf-faq-question:focus-visible {
    outline: 2px solid #2874f0;
    outline-offset: 2px;
}

/* ==========================================
   TABLET
========================================== */

@media (max-width: 768px) {
    .jf-faq {
        padding: 28px 22px 24px;
    }

    .jf-faq-heading {
        margin-bottom: 25px;
    }

    .jf-faq-heading h2 {
        font-size: 22px;
    }

    .jf-faq-heading p {
        font-size: 12px;
    }

    .jf-faq-list {
        max-width: 100%;
    }

    .jf-faq-question {
        min-height: 50px;
        font-size: 13px;
    }
}

/* ==========================================
   MOBILE
========================================== */

@media (max-width: 480px) {
    .jf-faq {
        padding: 27px 16px 25px;
    }

    .jf-faq-heading {
        margin-bottom: 23px;
    }

    .jf-faq-heading h2 {
        font-size: 21px;
        line-height: 1.35;
    }

    .jf-faq-heading p {
        max-width: 330px;
        margin: 0 auto;
        font-size: 12px;
        line-height: 1.6;
    }

    .jf-faq-question {
        min-height: 52px;
        padding: 13px 2px;
        gap: 12px;
        font-size: 12px;
    }

    .jf-faq-toggle {
        flex-basis: 18px;
        width: 18px;
        height: 18px;
        font-size: 20px;
    }

    .jf-faq-answer {
        padding: 0 24px 14px 2px;
    }

    .jf-faq-answer p {
        font-size: 12px;
        line-height: 1.65;
    }
}

/* Small phones */

@media (max-width: 360px) {
    .jf-faq {
        padding-right: 12px;
        padding-left: 12px;
    }

    .jf-faq-heading h2 {
        font-size: 19px;
    }

    .jf-faq-question {
        font-size: 11.5px;
    }
}

/* Fix excessive spacing between FAQ items */
.jf-faq {
    padding: 30px 24px 24px !important;
}

.jf-faq-heading {
    margin-bottom: 25px !important;
}

.jf-faq-list {
    max-width: 770px;
    margin: 0 auto;
}

.jf-faq-item {
    margin: 0 !important;
    padding: 0 !important;
    min-height: 0 !important;
    border: 0 !important;
}

.jf-faq-question {
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    width: 100% !important;
    min-height: 0 !important;
    height: auto !important;
    padding: 15px 4px !important;
    margin: 0 !important;
    line-height: 1.4 !important;
    font-size: 16px !important;
}

.jf-faq-answer {
    padding: 0 30px 14px 4px !important;
    margin: 0 !important;
}

.jf-faq-answer p {
    margin: 0 !important;
    line-height: 1.6 !important;
    font-size: 14px;
}

/* Mobile spacing */
@media (max-width: 576px) {
    .jf-faq {
        padding: 25px 16px 20px !important;
    }

    .jf-faq-heading {
        margin-bottom: 18px !important;
    }

    .jf-faq-question {
        padding: 13px 2px !important;
        font-size: 12px !important;
    }

    .jf-faq-answer {
        padding: 0 24px 12px 2px !important;
    }
}


/* =========================================
   REFER SUB HERO BANNER
========================================= */

.referSubHero {
    position: relative;
    isolation: isolate;
    width: 100%;
    min-height: 423px;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
    box-sizing: border-box;

    padding: 35px 24px;

    background: linear-gradient(
        110deg,
        #1b59cf 0%,
        #1550be 60%,
        #1048ae 100%
    );

    font-family: Arial, Helvetica, sans-serif;
}

.referSubHero *,
.referSubHero *::before,
.referSubHero *::after {
    box-sizing: border-box;
}

/* LEFT DECORATIVE PATTERN */

.referSubPattern {
    position: absolute;
    z-index: -1;
    top: 0;
    left: 0;
    width: 24%;
    height: 100%;
    pointer-events: none;

    background-image: radial-gradient(
        circle,
        rgba(111, 180, 255, 0.35) 1.2px,
        transparent 1.6px
    );

    background-size: 13px 13px;

    -webkit-mask-image: linear-gradient(
        to right,
        #000 0%,
        rgba(0, 0, 0, 0.7) 50%,
        transparent 100%
    );

    mask-image: linear-gradient(
        to right,
        #000 0%,
        rgba(0, 0, 0, 0.7) 50%,
        transparent 100%
    );
}

/* BUILDING IMAGE ON RIGHT */

.referSubBuilding {
    position: absolute;
    z-index: -1;
    right: 0;
    bottom: 0;

    width: 25%;
    height: 94%;

    display: flex;
    align-items: flex-end;
    justify-content: flex-end;

    pointer-events: none;
}

.referSubBuilding img {
    display: block;
    width: 100%;
    height: 100%;

    object-fit: contain;
    object-position: right bottom;

    opacity: 0.85;
}

/* CENTER CONTENT */

.referSubContent {
    position: relative;
    z-index: 1;

    width: 100%;
    max-width: 720px;
    margin: 0 auto;

    text-align: center;
    color: #ffffff;
}

.referSubContent h2 {
    margin: 0 0 8px;

    color: #ffffff;
    font-size: 25px;
    font-weight: 700;
    line-height: 1.25;
    letter-spacing: 0.05px;
}

.referSubContent p {
    margin: 0 auto 20px;
    max-width: 610px;

    color: rgba(255, 255, 255, 0.94);
    font-size: 14px;
    font-weight: 400;
    line-height: 1.5;
}

/* =========================================
   REFER SUB BANNER - FINAL UI UPDATE
========================================= */

/* Make building image transparent */
.referSubBuilding {
    opacity: 1 !important;
}

.referSubBuilding img {
    opacity: 0.45 !important;
    mix-blend-mode: screen;
    object-fit: contain;
    object-position: right bottom;
}

/* Increase button size and text */
.referSubButtons .referSubBtn {
    width: 175px !important;
    min-width: 175px !important;
    min-height: 44px !important;
    padding: 11px 16px !important;

    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 11px;

    font-size: 12px !important;
    font-weight: 600 !important;
    line-height: 1.4 !important;

    border-radius: 7px;
    box-sizing: border-box;
}

/* Increase icon size */
.referSubButtons .referSubBtn i {
    font-size: 16px !important;
}

/* Tablet */
@media (max-width: 991px) {
    .referSubButtons .referSubBtn {
        width: 165px !important;
        min-width: 165px !important;
        min-height: 43px !important;
        font-size: 12px !important;
    }

    .referSubBuilding img {
        opacity: 0.35 !important;
    }
}

/* Mobile */
@media (max-width: 600px) {
    .referSubButtons {
        gap: 10px !important;
    }

    .referSubButtons .referSubBtn {
        width: 165px !important;
        min-width: 0 !important;
        min-height: 44px !important;
        padding: 10px 12px !important;
        font-size: 12px !important;
    }

    .referSubButtons .referSubBtn i {
        font-size: 15px !important;
    }

    .referSubBuilding img {
        opacity: 0.25 !important;
    }
}

/* Small phones */
@media (max-width: 360px) {
    .referSubButtons .referSubBtn {
        width: 145px !important;
        min-height: 42px !important;
        padding: 9px 8px !important;
        gap: 7px !important;
        font-size: 11px !important;
    }
}


/* BUTTONS */

.referSubButtons {
    display: flex;
    align-items: center;
    justify-content: center;
    flex-wrap: wrap;
    gap: 7px;
}

.referSubBtn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 10px;

    width: 146px;
    min-height: 35px;
    padding: 8px 12px;

    border: 1px solid #ffffff;
    border-radius: 7px;

    background: #ffffff;
    color: #2874f0 !important;
    -webkit-text-fill-color: #2874f0;

    font-size: 10px;
    font-weight: 500;
    line-height: 1.3;
    text-decoration: none;
    white-space: nowrap;

    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.08);

    transition:
        background 0.25s ease,
        color 0.25s ease,
        transform 0.25s ease;
}

.referSubBtn i {
    flex-shrink: 0;
    color: #2874f0;
    -webkit-text-fill-color: #2874f0;
    font-size: 13px;
}

.referSubBtn:hover {
    background: #edf4ff;
    border-color: #edf4ff;
    color: #1550be !important;
    -webkit-text-fill-color: #1550be;
    transform: translateY(-1px);
}

.referSubBtn:hover i {
    color: #1550be;
    -webkit-text-fill-color: #1550be;
}

/* =========================================
   TABLET
========================================= */

@media (max-width: 991px) {
    .referSubHero {
        min-height: 235px;
        padding: 32px 22px;
    }

    .referSubContent {
        max-width: 640px;
    }

    .referSubContent h2 {
        font-size: 17px;
    }

    .referSubBuilding {
        width: 25%;
        height: 85%;
        opacity: 0.7;
    }

    .referSubContent p {
        max-width: 520px;
        font-size: 10px;
    }
}

/* =========================================
   MOBILE
========================================= */

@media (max-width: 600px) {
    .referSubHero {
        min-height: 245px;
        padding: 30px 16px;

        background: linear-gradient(
            110deg,
            #1b59cf,
            #1048ae
        );
    }

    .referSubPattern {
        width: 32%;
        opacity: 0.65;
    }

    .referSubBuilding {
        width: 34%;
        height: 72%;
        opacity: 0.24;
    }

    .referSubContent {
        max-width: 100%;
    }

    .referSubContent h2 {
        font-size: 19px;
        line-height: 1.35;
        margin-bottom: 10px;
    }

    .referSubContent p {
        max-width: 430px;
        margin-bottom: 18px;
        font-size: 11px;
        line-height: 1.6;
    }

    .referSubDesktopBreak {
        display: none;
    }

    .referSubButtons {
        gap: 9px;
    }

    .referSubBtn {
        width: auto;
        min-width: 140px;
        min-height: 40px;
        padding: 9px 13px;
        font-size: 11px;
    }
}

/* SMALL PHONES */

@media (max-width: 380px) {
    .referSubHero {
        min-height: 235px;
        padding: 26px 12px;
    }

    .referSubContent h2 {
        font-size: 17px;
    }

    .referSubContent p {
        font-size: 10px;
    }

    .referSubButtons {
        gap: 7px;
    }

    .referSubBtn {
        min-width: 130px;
        padding: 8px 10px;
        gap: 7px;
        font-size: 10px;
    }

    .referSubBuilding {
        width: 38%;
        opacity: 0.18;
    }
}

